window.QUESTIONS_DATA = {"generated":"2026-11-27 03:44 UTC","news_checked":"2026-11-27","fields":["Mathematics","Physics","Computer science and AI","Biology","Medicine","Other fields"],"questions":[{"id":"OP-MATH-RH","kind":"landmark","field":"Mathematics","title":"The Riemann hypothesis","text":"Do all non-trivial zeros of the Riemann zeta function have real part 1/2?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-MATH-RH-","open":1,"news":[{"date":"2026-11-24","status":"Claim, machine-checked, not refereed","headline":"The formal proof is certified by the Lean and Mathlib organisations; still no refereed account","summary":"On 21 November 2026 the Lean Focused Research Organization and the Mathlib Initiative issued a joint statement on Levent Alpöge's formal proof: \"We hereby certify that both the statement and the proof of the Riemann Hypothesis are correct.\" The Next Web reports that dozens of people compiled the code without errors and that several independent proof checkers accepted it. The same report quotes the Association for Human Mathematics objecting that \"no human being can reasonably claim to be responsible for, or even to understand, such a document\", and says Alpöge wants to simplify and write up the argument. The Clay Mathematics Institute's page for the problem, last modified on 24 November, carries the label \"Active\", where its pages for Yang-Mills and P versus NP say \"Unsolved\"; the page does not mention the claim, and we found no Clay statement explaining the label. There is still no refereed or journal-published account, so this page keeps the problem listed as open.","sources":[{"publisher":"The Next Web","title":"Lean and Mathlib certify the Riemann hypothesis proof","date":"2026-11-23","url":"https://thenextweb.com/news/lean-mathlib-certify-riemann-hypothesis-proof-alpoge-claude"},{"publisher":"Clay Mathematics Institute","title":"Riemann Hypothesis (problem page)","date":"2026-11-24","url":"https://www.claymath.org/millennium/riemann-hypothesis/"}],"checked":"2026-11-27"},{"date":"2026-11-20","status":"Claim, machine-checked, not refereed","headline":"A proof is claimed, published only as a formal proof in Lean","summary":"On 20 November 2026 Levent Alpöge, a mathematician at Anthropic, announced a proof of the Riemann hypothesis that he says he found working with the AI system Claude. It was released as a four-page note and a very large formal proof in the Lean proof assistant; no human-readable account of the mathematics has been written. Several independent groups have compiled the formal proof and report that the proof checker accepts it and that its statements match the standard formal statement of the hypothesis, and on 21 November a group of people who work on formalizing mathematics stated full confidence that it is correct. It has not been refereed or published in a journal, and we found no statement from the Clay Mathematics Institute. Number theorists quoted by Quanta Magazine say the note's outline does not make sense to them, and that a machine-checked proof does not yet explain why the hypothesis is true. This page keeps the problem listed as open until the mathematical community accepts the proof.","sources":[{"publisher":"Quanta Magazine","title":"A claimed proof of the Riemann hypothesis","date":"2026-11-20","url":"https://www.quantamagazine.org/update/169564/"},{"publisher":"Quanta Magazine","title":"What does authorship mean in the age of AI?","date":"2026-11-24","url":"https://www.quantamagazine.org/update/169609/"},{"publisher":"GitHub, nasqret/riemann-rev","title":"Status dashboard of the formal proof: who has checked what","date":"2026-11-20","url":"https://github.com/nasqret/riemann-rev"}],"checked":"2026-11-26"}],"source":"Clay Mathematics Institute (2000), Riemann Hypothesis","source_url":"https://www.claymath.org/millennium/riemann-hypothesis/"},{"id":"OP-MATH-COLLATZ","kind":"landmark","field":"Mathematics","title":"The Collatz (3x+1) conjecture","text":"Does iterating n -> n/2 for even n and n -> 3n+1 for odd n reach 1 from every positive integer?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-MATH-COLLATZ-","open":1,"source":"Lagarias (2021), The 3x+1 Problem: An Overview","source_url":"https://arxiv.org/abs/2111.02635"},{"id":"OP-MATH-ERDOS-AP","kind":"landmark","field":"Mathematics","title":"Erdős's conjecture on arithmetic progressions","text":"Does every set of positive integers whose reciprocals have a divergent sum contain arithmetic progressions of every finite length?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-MATH-ERDOS-AP-","open":1,"note":"The case of three-term progressions follows from the cited paper; the conjecture for every length is open.","source":"Bloom (2020), Breaking the logarithmic barrier in Roth's theorem on arithmetic progressions","source_url":"https://arxiv.org/abs/2007.03528"},{"id":"OP-PHYS-YM","kind":"landmark","field":"Physics","title":"Yang-Mills existence and mass gap","text":"Does a quantum Yang-Mills theory exist on four-dimensional space-time for every compact simple gauge group, and does it have a mass gap?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-PHYS-YM-","open":1,"news":[{"date":"2026-10-26","status":"Claim, under expert review","headline":"OpenAI reports a formal proof that pure Yang-Mills theory exists; the mass gap is not claimed","summary":"On 26 October 2026 OpenAI wrote that its work includes a proof of the existence of pure Yang-Mills theory, produced on 9 September, with a formalization in the Lean proof assistant finished on 16 October. It named a group led by David Gross, with Michael Douglas, Arthur Jaffe, Igor Klebanov and Nikita Nekrasov, to understand and explain the result; OpenAI's page does not say the group has confirmed it. The page makes no claim about the mass gap, which is the second half of this problem. The Clay Mathematics Institute's page for the problem, last modified on 24 November, still carries the label \"Unsolved\" and does not mention the work.","sources":[{"publisher":"OpenAI","title":"Working with academic communities to build scientific understanding","date":"2026-10-26","url":"https://openai.com/index/building-scientific-understanding-with-academic-communities/"},{"publisher":"Clay Mathematics Institute","title":"Yang-Mills and the Mass Gap (problem page)","date":"2026-11-24","url":"https://www.claymath.org/millennium/yang-mills-the-maths-gap/"}],"checked":"2026-11-27"}],"source":"Clay Mathematics Institute (2000), Yang-Mills & the Mass Gap","source_url":"https://www.claymath.org/millennium/yang-mills-the-maths-gap/"},{"id":"OP-PHYS-DM","kind":"landmark","field":"Physics","title":"The nature of dark matter","text":"What is the dark matter that astronomical observations require made of?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-PHYS-DM-","open":1,"news":[{"date":"2026-09-05","status":"Progress report","headline":"The LZ experiment reports one unexplained event and says it is not claiming a detection","summary":"In early September 2026 the LUX-ZEPLIN (LZ) dark matter experiment reported a single particle interaction, in 220 days of data taken from March 2023 to April 2024, that is hard to explain with known backgrounds. Stanford's account gives the significance as 2.6 sigma, well short of the 5 sigma that physicists require for a discovery. The collaboration's spokesperson, Rick Gaitskell, said: \"We are not claiming to have seen dark matter.\" The result was presented at a conference; the paper was to be posted on arXiv and submitted to Physical Review Letters, and the sources we read do not say it has been peer reviewed. They quote only members of the collaboration, who say more data will show whether the signal grows or fades.","sources":[{"publisher":"Stanford Report","title":"Dark matter detection signal at LZ","date":"2026-09","url":"https://news.stanford.edu/stories/2026/09/dark-matter-detection-signal-lz"},{"publisher":"Al Jazeera","title":"Have scientists discovered a dark matter particle?","date":"2026-09-05","url":"https://www.aljazeera.com/features/2026/9/5/have-scientists-discovered-a-dark-matter-particle"}],"checked":"2026-11-26"}],"source":"Bertone (2018), History of dark matter","source_url":"https://doi.org/10.1103/RevModPhys.90.045002"},{"id":"OP-PHYS-HTSC","kind":"landmark","field":"Physics","title":"The mechanism of high-temperature superconductivity","text":"What pairs the electrons in the copper-oxide superconductors, and what sets their transition temperature?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-PHYS-HTSC-","open":1,"source":"Keimer (2015), From quantum matter to high-temperature superconductivity in copper oxides","source_url":"https://doi.org/10.1038/nature14165"},{"id":"OP-CS-PNP","kind":"landmark","field":"Computer science and AI","title":"P versus NP","text":"Can every problem whose solution is verifiable in polynomial time also be solved in polynomial time?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-CS-PNP-","open":1,"news":[{"date":"2026-10-28","status":"Claim, under expert review","headline":"A related conjecture, the exponential time hypothesis, is reported refuted; P versus NP is untouched","summary":"In late October 2026 OpenAI announced a proof, with a formalization in Lean, that the exponential time hypothesis is false: an algorithm that solves k-SAT faster than the hypothesis allows. Anthropic released a paper of its own on the same question. Lance Fortnow, a complexity theorist, wrote on 28 October that he had not verified the proof himself but that \"it is safe to assume now that the exponential-time hypothesis is toast\", and noted that Russell Impagliazzo, Ramamohan Paturi and Ryan Williams had set up a site to examine it. This does not answer P versus NP. Fortnow writes that the result \"applies to k-SAT but not to NP problems in general\" and is far from the speed a polynomial-time algorithm would need. The Clay Mathematics Institute's page for P versus NP, last modified on 24 November, carries the label \"Unsolved\".","sources":[{"publisher":"Computational Complexity (blog), Lance Fortnow","title":"The Exponential Time Refutation","date":"2026-10-28","url":"https://blog.computationalcomplexity.org/2026/10/the-exponential-time-refutation.html"},{"publisher":"OpenAI","title":"Working with academic communities to build scientific understanding","date":"2026-10-26","url":"https://openai.com/index/building-scientific-understanding-with-academic-communities/"},{"publisher":"Clay Mathematics Institute","title":"P vs NP (problem page)","date":"2026-11-24","url":"https://www.claymath.org/millennium/p-vs-np/"}],"checked":"2026-11-27"}],"source":"Clay Mathematics Institute (2000), P vs NP","source_url":"https://www.claymath.org/millennium/p-vs-np/"},{"id":"OP-CS-OMEGA","kind":"landmark","field":"Computer science and AI","title":"The exponent of matrix multiplication","text":"Is the exponent omega of matrix multiplication equal to 2?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-CS-OMEGA-","open":1,"news":[{"date":"2026-11-24","status":"Claim, not checked","headline":"An OpenAI preprint claims the exponent is exactly 9/4, which would mean it is not 2","summary":"A preprint dated 24 November 2026 in OpenAI's public mathematics repository is titled \"The matrix multiplication exponent is nine fourths\". According to a news report of 26 November, it claims a lower bound matching the earlier upper bound of 9/4, so that the exponent would equal 2.25 exactly and the answer to this problem would be no. We could not open the preprint ourselves and rely on that report for its contents. The report says the accompanying Lean formalization covers a narrower setting than the headline theorem (circuits without division), that the rest stands on a written proof which has not been peer reviewed, and that outside mathematicians had had the manuscript for two days; it quotes no outside expert. Treat this as an unchecked claim.","sources":[{"publisher":"GitHub, openai/math","title":"The matrix multiplication exponent is nine fourths (preprint, 24 November 2026)","date":"2026-11-24","url":"https://github.com/openai/math/tree/main/preprints/The-matrix-multiplication-exponent-is-nine-fourths-November-24-2026"},{"publisher":"i10X News","title":"OpenAI: Matrix Multiplication Exponent Is 9/4, What Is Proven","date":"2026-11-26","url":"https://i10x.ai/news/openai-matrix-multiplication-exponent-9-4-lower-bound-preprint"}],"checked":"2026-11-27"},{"date":"2026-11-09","status":"Claim, under expert review","headline":"An upper bound of 9/4 on the exponent is reported, with an independent exposition","summary":"A preprint by Mahmut Levent Doğan, Vladimir Lysikov, Keiya Sakabe and Michael Walter, posted on 9 November 2026, gives what its abstract calls an exposition of a recent OpenAI result that the exponent of matrix multiplication is at most 9/4 (2.25), valid over every field. That would be a large step down from the bound of about 2.3712 reported in August. We did not open OpenAI's own account of the result, and the preprint's abstract does not say it has been peer reviewed. The open problem is whether the exponent equals 2, which neither result settles.","sources":[{"publisher":"arXiv","title":"Tensor value and the 9/4 bound for matrix multiplication (arXiv:2611.09716)","date":"2026-11-09","url":"https://arxiv.org/abs/2611.09716"}],"checked":"2026-11-26"},{"date":"2026-08-17","status":"Progress report","headline":"A preprint lowers the upper bound on the exponent to 2.371177","summary":"A preprint posted on 17 August 2026 by Emilien Dupont and nine co-authors, including Josh Alman and Virginia Vassilevska Williams, reports an upper bound of omega below 2.371177, improving the previous best bound of 2.371339. The authors say they designed a new optimization algorithm with machine learning and refined it with the AI system AlphaEvolve. The abstract does not say the paper has been peer reviewed.","sources":[{"publisher":"arXiv","title":"Improving the matrix multiplication exponent with modern optimization and AlphaEvolve (arXiv:2608.16884)","date":"2026-08-17","url":"https://arxiv.org/abs/2608.16884"}],"checked":"2026-11-26"}],"source":"Alman (2020), A Refined Laser Method and Faster Matrix Multiplication","source_url":"https://arxiv.org/abs/2010.05846"},{"id":"OP-CS-GI","kind":"landmark","field":"Computer science and AI","title":"Graph isomorphism in polynomial time","text":"Can it be decided in polynomial time whether two finite graphs are isomorphic?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-CS-GI-","open":1,"source":"Babai (2015), Graph Isomorphism in Quasipolynomial Time","source_url":"https://arxiv.org/abs/1512.03547"},{"id":"OP-BIO-ORIGIN","kind":"landmark","field":"Biology","title":"The origin of life","text":"How and where did life on Earth arise?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-BIO-ORIGIN-","open":1,"source":"Kennedy (2005), What Don't We Know?","source_url":"https://doi.org/10.1126/science.309.5731.75"},{"id":"OP-BIO-REGEN","kind":"landmark","field":"Biology","title":"Organ regeneration","text":"What controls organ regeneration, and why can some animals regrow organs that others cannot?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-BIO-REGEN-","open":1,"source":"Kennedy (2005), What Don't We Know?","source_url":"https://doi.org/10.1126/science.309.5731.75"},{"id":"OP-BIO-DIVERSITY","kind":"landmark","field":"Biology","title":"Species diversity","text":"What determines how many species live in a place?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-BIO-DIVERSITY-","open":1,"source":"Kennedy (2005), What Don't We Know?","source_url":"https://doi.org/10.1126/science.309.5731.75"},{"id":"OP-MED-PETO","kind":"landmark","field":"Medicine","title":"Peto's paradox","text":"Why does cancer risk not rise across species with body size and lifespan, although larger and longer-lived animals have more cell divisions in which to acquire mutations?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-MED-PETO-","open":1,"source":"Caulin (2011), Peto's Paradox: evolution's prescription for cancer prevention","source_url":"https://doi.org/10.1016/j.tree.2011.01.002"},{"id":"OP-MED-HIV-VACCINE","kind":"landmark","field":"Medicine","title":"An effective HIV vaccine","text":"Is a vaccine that reliably prevents HIV infection feasible?","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-MED-HIV-VACCINE-","open":1,"source":"Kennedy (2005), What Don't We Know?","source_url":"https://doi.org/10.1126/science.309.5731.75"},{"id":"OP-UQ-20261015-02","kind":"literature","field":"Mathematics","title":"Does the palindromic gap pdg(2;3,t) = w(2;3,t) − q(t) attain 0 infinitely often?","text":"Does the palindromic gap pdg(2;3,t) = w(2;3,t) − q(t) attain 0 infinitely often? Computable part: extend pdw(2;3,t) (OEIS A198685) past t = 20 and compare with w(2;3,t).","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261015-02","open":1,"source":"Ahmed, Kullmann & Snevily, arXiv:1102.5433 §5.4 open problem 2","badge":"Has a part computable from public sources","tier":"A (computational part)"},{"id":"OP-UQ-20261015-08","kind":"literature","field":"Computer science and AI","title":"Does leaderboard-based LLM capability structure (inter-benchmark correlations, general-factor share, Jin et al. 2025 causal ordering) hold up under a lineage-structured (phylogenetic) …","text":"Does leaderboard-based LLM capability structure (inter-benchmark correlations, general-factor share, Jin et al. 2025 causal ordering) hold up under a lineage-structured (phylogenetic) covariance beyond flat corrections? Computable part: Pagel's lambda and Blomberg's K per Open LLM Leaderboard v2 benchmark on the Hugging Face fine-tune/merge genealogy, then refit the published factor results under PGLS against contributor random effects and base-model strata. First check the unread arXiv:2605.02930 (full text) and arXiv:2609.28177.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261015-08","open":1,"source":"Hardy et al. 2026, arXiv:2605.25272 (names hierarchical dependence, corrects only with a contributor random effect); Ilić & Gignac 2024, arXiv:2310.11616 (raises it, de-duplication only)","badge":"Has a part computable from public sources","tier":"A (part a, computational on public data); part b nearer B"},{"id":"OP-UQ-20261015-12","kind":"literature","field":"Medicine","title":"Does time-to-plasma-separation shift chromosome-arm-level cfDNA fragmentation profiles (the DELFI feature space) enough to move a fragmentation score?","text":"","work":[],"target":"","open":0,"source":"bioRxiv 10.1101/2021.09.17.460828 / Clin Chem 2022 doi 10.1093/clinchem/hvac029 — reports a \"moderate impact\" of processing time on genome-wide fragmentation patterns, observational (time recorded not randomised), 30 healthy donors, no statistics given, no action recommended","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"OP-UQ-20261015-17","kind":"literature","field":"Other fields","title":"Is the data-driven-minus-physical weather forecast skill gap the same in analysis space and in observation space, resolved by variable/level/region and regressed on observation influence?","text":"","work":[],"target":"","open":0,"source":"arXiv:2305.00048 (asks it; answers only qualitatively for one model, one year, surface variables, assimilated observations, initialisation confound unresolved) and Geosci. Model Dev. 19:4703-4724 (2026) (both verification spaces computed operationally, contrast never reported)","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (regressor part nearer C: needs operational-centre observation-influence fields)"},{"id":"OP-UQ-20261015-24","kind":"literature","field":"Computer science and AI","title":"Can an external, utility-side observer detect synchronised AI-training datacentre load episodes from grid measurements on field rather than simulated data, with a detection floor in job MW …","text":"Can an external, utility-side observer detect synchronised AI-training datacentre load episodes from grid measurements on field rather than simulated data, with a detection floor in job MW crossed with local grid strength (SCR/inertia) and per-measurement-class (PMU P/M-class, point-on-wave, wall-socket ENF) performance?","work":[],"target":"","open":0,"source":"arXiv:2609.18997 (detection posed; validated only on an RTDS IEEE 39-bus simulation, performance stated as a \"wide margin over chance\", no field data, no ROC, no MW threshold) with PNNL-39191 (PNNL/DOE-OE, Apr 2026: PMU validated bandwidth 2 Hz P-class / 5 Hz M-class, aliasing above half the reporting rate, measurement adequacy above 2-5 Hz unresolved, POW recommended but data-volume-limited)","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (detection-floor part; field-ground-truth arm needs an operator partner and utility PMU/POW access, nearer C)"},{"id":"OP-UQ-20261016-01","kind":"literature","field":"Computer science and AI","title":"What is P(hardware-fault-coincident \\| loss spike or divergence not explained by batch replay or optimizer state) in large-scale training runs, with a confidence interval and a …","text":"What is P(hardware-fault-coincident \\| loss spike or divergence not explained by batch replay or optimizer state) in large-scale training runs, with a confidence interval and a false-attribution rate measured on fault-free control periods? Posed in print as a central question, answered only in the forward direction (inject a fault, observe the loss). The obstacle is documented rather than hypothetical: SDCHunter reports that loss, gradient norm and hardware telemetry do not correlate with SDCs, so the reverse conditional is not estimable from the signals labs already collect.","work":[],"target":"","open":0,"source":"Altenbernd, Wiesner & Kao, arXiv:2604.00726v1 (poses it centrally; reports only P(spike \\| injected fault), declines recall/F1 because \"many SDC are masked during training\"); Lei et al., AEGIS (OSDI '26) (supplies the fleet denominator, concedes it \"cannot completely rule out undetected SDCs\"); Zheng et al., SDCHunter (OSDI '26) (the non-correlation result)","badge":"Needs laboratory work or restricted data","tier":"C (needs fleet-scale instrumented-run telemetry from an operator; no public dataset carries both the spike diagnoses and the fault log)"},{"id":"OP-UQ-20261016-04","kind":"literature","field":"Medicine","title":"For a designated variant's invasion window in one sewershed, is the per-lineage sewage-to-clinical frequency odds ratio constant in time, and does its measured time-drift displace the …","text":"For a designated variant's invasion window in one sewershed, is the per-lineage sewage-to-clinical frequency odds ratio constant in time, and does its measured time-drift displace the fitted logistic growth advantage enough to change a designation or strain-selection decision? The constant-ratio case is closed by algebra (it cancels out of the logistic slope and is absorbed by the midpoint); only the time-varying residual can bias the slope, and that is the part left open in print.","work":[],"target":"","open":0,"source":"Dreifuss D, Huisman JS, Rusch JC, Caduff L, Ganesanandamoorthy P, Devaux AJ, Gan C, Stadler T, Kohn T, Ort C, Beerenwinkel N, Julian TR, medRxiv 2023.10.25.23297539 / *Nature Communications* 16, 2025, doi 10.1038/s41467-025-62790-y — proves the invariance for a constant shedding ratio, compares wastewater- and clinical-derived logistic growth rates across six Swiss sewersheds, and states in discussion that other biases including \"shifts in shedding load distributions\" \"should be rigorously studied\"","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (paired wastewater and clinical lineage-frequency series exist for the Swiss and Québec settings; the shedding-versus-ascertainment components of the composite ratio are not identified from paired frequency series alone, so an external within-host shedding anchor must be specified or the residual bounded first)"},{"id":"OP-UQ-20261016-09","kind":"literature","field":"Medicine","title":"Does the secular decline in age-specific dementia incidence reflect a fall in the prevalence of Alzheimer pathology, or only a fall in the probability that a given pathology burden is …","text":"Does the secular decline in age-specific dementia incidence reflect a fall in the prevalence of Alzheimer pathology, or only a fall in the probability that a given pathology burden is expressed as clinical dementia? Measurable part: archived plasma from two epochs of one decline-documenting cohort at a matched age window, assayed in one lot with bridging controls, reporting the epoch p-tau217 positivity ratio, the continuous quantile shift, the incidence/positivity ratio, and a within-epoch storage-duration gradient test for assay drift.","work":[],"target":"","open":0,"source":"Wharton et al., *Neuropathol Appl Neurobiol* 2023 (PMC10946587) — states the pathological basis of the CFAS I-to-CFAS II decline is unknown because no neuropathology cohort was developed for CFAS II; with Grodstein et al., *JAMA Neurol* 2023;80(4):370–376 (via alzforum.org/node/2689231) and Merrick & Matthews, *Nat Rev Neurol* 2023, which answer the autopsy version in ROSMAP only — a cohort that never published the incidence decline","badge":"Needs laboratory work or restricted data","tier":"C (needs access to an archived-plasma biobank from a cohort that published the incidence decline; the assay itself is routine, the specimens are the constraint)"},{"id":"OP-UQ-20261016-11","kind":"literature","field":"Other fields","title":"Is the ambient-seed explanation of disappearing polymorphs measurable?","text":"Is the ambient-seed explanation of disappearing polymorphs measurable? Establish the flip threshold — the quantity of the stable form that, introduced as recovered surface or air residue into a standardised seed-controlled supersaturated crystallisation, flips the outcome from the metastable to the stable form — then test whether residue from rooms with documented handling history carries activity at or above it while naive and cleaned rooms do not, and measure the persistence half-life. Settle presupposition 7 first and cheaply: a spiked-swab calibration establishing whether the flip threshold lies above the sampling chain's limit of quantitation, because if it does not the campaign returns \"uninterpretable\" whatever the rooms contain.","work":[],"target":"","open":0,"source":"Bučar D-K, Lancaster RW, Bernstein J, \"Disappearing Polymorphs Revisited\", *Angew Chem Int Ed* 2015;54(24):6972–6993, doi 10.1002/anie.201410356 (PMC4479028, opened and independently re-verified) — asserts the mechanism as leading (\"the working atmosphere inevitably becomes contaminated with seeds of the particular material\") while stating, quoting Dunitz & Bernstein 1995, that such seeds \"have never actually been directly observed\" and that \"there is no consensus about the size and range of activity of such seeds\". Thirty years from the first statement of the gap to this one, with no measurement in between.","badge":"Needs laboratory work or restricted data","tier":"C (wet-lab plus facility access: needs a stratified room panel, the cleaning-validation swab chain and replicate crystallisation capacity; nothing is computable from public data, and the spiked-swab calibration should gate the rest)"},{"id":"OP-UQ-20261016-13","kind":"literature","field":"Medicine","title":"Panel-level S/I/R discordance rate of ISO 20776-1 broth microdilution at 31/33 °C versus 35 °C in cool-site clinical isolates (chronic wound, diabetic foot, burn eschar, CF airway) …","text":"Panel-level S/I/R discordance rate of ISO 20776-1 broth microdilution at 31/33 °C versus 35 °C in cool-site clinical isolates (chronic wound, diabetic foot, burn eschar, CF airway), multi-species and multi-agent, referenced to same-experiment replicate discordance at 35 °C and with a reading-time-only control arm, reporting whether any excess concentrates in identifiable agent classes. Asked and answered only at organism-drug granularity; the febrile arm is already answered and is not part of this residue. Check three unread own-field records first (PMC6325273; the Galway \"influence of incubation temperature and time on the precision of ...\" record; SciTePress 2019 gentamicin/S. aureus at 33 versus 35 °C), any of which may close it.","work":[],"target":"","open":0,"source":"Welch & Southern, *J Clin Microbiol* 1984;19(6):831–833, PMID 6565708 (30 versus 35 °C, methicillin only, framed as MRSA detection sensitivity); Wheat, Winstanley & Spencer, *J Clin Pathol* 1985;38(9):1055 (30 versus 37 °C, multi-agent but one species, MIC comparison only, no category discordance and no reproducibility comparator); Rahmati-Bahram, Magee & Jackson, *J Antimicrob Chemother* 1996;37(4):665–676, doi 10.1093/jac/37.4.665 (mechanism, single organism) — none reports a panel-level categorical discordance rate against the method's own reproducibility bound","badge":"Needs laboratory work or restricted data","tier":"C (crisply specified but wet-lab only: needs a cool-site clinical isolate collection and replicate broth-microdilution capacity, so nothing in it is computable from public data)"},{"id":"OP-UQ-20261016-15","kind":"literature","field":"Medicine","title":"Is disagreement between independent Y-site physical-compatibility determinations on the same drug pair ordered by detection sensitivity (visual inspection < pH < turbidimetry < sub-visible …","text":"Is disagreement between independent Y-site physical-compatibility determinations on the same drug pair ordered by detection sensitivity (visual inspection < pH < turbidimetry < sub-visible particle counting), i.e. do less sensitive endpoints systematically return \"compatible\"? Named in print as the probable cause of contradictory compatibility information and never tested. Computable sub-part: concordance and endpoint-ordering tabulation over the verdicts already extracted in Gostynska 2024 (*Pharmaceutics* 16(2):264) and the 475 determined pairs of the *Medicina Intensiva* review, with the matched-replicate count reported first.","work":[],"target":"","open":0,"source":"Neininger MP et al., *Die Pharmazie* 2018;73:605–608 — 17.1% (6/35) outright contradiction between two databases on shared pairs, attributed to \"the heterogeneity of the methods used to determine incompatibility\" (citing Kanji et al. 2010), with no test; *Medicina Intensiva* S2173572719302139 (PMID 30262380) — endpoints extracted per study (pH 44%, HPLC 22%, triplicate 26%), turbidimetry/microscopy called more accurate and underused, no study-versus-study comparison reported","badge":"Needs laboratory work or restricted data","tier":"C for the matched-replicate limb (needs the primary corpus plus commercial compendia that are not auditable from outside, and the replicate set may be empty); the published-table sub-part is nearer B"},{"id":"OP-UQ-20261016-22","kind":"literature","field":"Biology","title":"Two residuals only, after the published work is subtracted. (a) Is the order in which individual laboratory rodents are caught out of a cage a REPEATABLE individual trait — an ICC or …","text":"Two residuals only, after the published work is subtracted. (a) Is the order in which individual laboratory rodents are caught out of a cage a REPEATABLE individual trait — an ICC or equivalent across >=5 days in individually marked cage-mates? No repeatability estimate exists for catch order; the only repeatability work is on wild-rodent trappability, a different construct, and it concluded trappability is not a personality proxy. (b) Does the group-mean shift induced by catch-order allocation, benchmarked against PUBLISHED treatment effect sizes for the same endpoints, reach the size of the effects such experiments report? Do NOT re-run the endpoint-effect measurement: Takao et al. 2016 already did it at scale.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261016-22","open":1,"source":"ARRIVE 2.0 Item 4a asserts the hazard in the field's own words (\"Selecting an animal 'at random' (i.e., haphazardly or arbitrarily) from a cage is not statistically random\"), names researcher judgement as the mechanism and prescribes allocation concealment, citing no measurement — https://resources.equator-network.org/reporting-guidelines/arrive/items/randomisation.html; NC3Rs guidance names the easier-to-catch mechanism explicitly. The endpoint half is already partly answered: Takao et al. 2016, Front Behav Neurosci 10:99, measured removal-order effects on rectal temperature, hot-plate latency, elevated-plus-maze open-arm time and plasma corticosterone in ~1,700 control C57BL/6J mice; Schipper et al. 2025 adds within-cage order effects on three behavioural tests (its Methods could not be read, so whether its \"testing order\" is physical catch order or a pre-assigned order is unverified). Neither reports repeatability-as-trait or the benchmark.","badge":"Has a part computable from public sources","tier":"A (limb (a) is a single-lab observational log; limb (b) is a re-analysis against published effect sizes — both cheap, neither needing new treatment arms)"},{"id":"OP-UQ-20261016-26","kind":"literature","field":"Biology","title":"What share of the vertebrate taxa on an airborne-eDNA detection list had its source OUTSIDE the pre-specified survey unit?","text":"What share of the vertebrate taxa on an airborne-eDNA detection list had its source OUTSIDE the pre-specified survey unit? Needs a unit with an enumerated in- and off-unit source inventory, reporting the off-unit share with a CI by taxon group and sampler type. A cheaper bounding sub-part: re-analyse published taxon lists against local occurrence records, which bounds the share without settling true source location. Do NOT re-run the distance limb — it is answered four times over (Clare et al. 2022: read count against distance from the enclosure, LR = 2.51, df = 1, p = 0.113, 0-276 m, 27 in-enclosure points excluded; Kroos et al. 2026: three distance classes to 1000 m, Bayesian active-sampler estimate -0.91, 95% CI -1.73 to -0.10; Stewart et al. 2026: modelled wind catchments to 655 m, \"likely originate less than 200 m downwind\"; UK national survey: estimated 18.6 km median, 400 m to 75.6 km range).","work":[],"target":"","open":0,"source":"Stewart et al. 2026, *Environmental DNA*, doi 10.1002/edn3.70329 — makes source provenance the paper's object and stops at model-catchment agreement; UK national airborne-eDNA survey, *Sci Rep* s41598-025-03650-z — \"the true source origin(s) of these species' DNA could be missed\", its estimated distances \"should be interpreted with caution\", and \"a dedicated experimental design will be necessary to further rigorously test eDNA transport distances\"; Lynggaard et al. 2026, *Commun Biol* s42003-026-09950-y — calls for \"investigations into the state, transportation, and persistence of vertebrate airborne eDNA\". Clare et al. 2022 label residency but hedge several non-resident detections as possible zoo stock or food. No source partitions a taxon list by whether a taxon's source lay inside or outside a defined unit.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (the bounding re-analysis is public-data work; the verified-inventory arm needs a field campaign at a site with an enumerated source inventory, nearer C)"},{"id":"OP-UQ-20261016-29","kind":"literature","field":"Biology","title":"Over a plasmid repository's sequenced catalogue, how many distinct citing publications are attached to plasmids whose repository sequence departs from the depositor-supplied map, by …","text":"Over a plasmid repository's sequenced catalogue, how many distinct citing publications are attached to plasmids whose repository sequence departs from the depositor-supplied map, by discrepancy class (ORF-altering / regulatory / backbone / selection marker / silent)? Settle the denominator first: what fraction of papers citing a repository plasmid describe the construct by map, sequence or element composition rather than by catalogue number alone — the exposure estimand is undefined until that number exists. Check the premise before modelling: neither cited source establishes that a repository holds a depositor map joinable to its own full-construct sequencing at catalogue scale. Do NOT re-run the catalogue-scale classification (McGuffie & Barrick 2024: 51,384 fully sequenced Addgene plasmids, 171,828 part mismatches against canonical sequences) or the map-versus-material rates (Bai et al. 2024, bioRxiv 10.1101/2024.06.17.596931, a vendor preprint whose true map-versus-material arm is 49 Addgene AAV plasmids).","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261016-29","open":1,"source":"McGuffie MJ, Barrick JE, *PLOS ONE* 19(5):e0304164, 2024 — the Discussion defers the publication join explicitly: \"It may be possible to trace more of our variants of interest to existing publications\", \"this will require analyzing hundreds or thousands of publications\", \"Such efforts will take years of expert curation and laboratory experiments by a community of scientists\"; the Results record a failed instance — \"none of the five publications associated with the plasmids containing this derivative mention its provenance\". Bai et al. 2024 never mentions citing publications, so it is not part of this routing ground.","badge":"Has a part computable from public sources","tier":"A for the class-by-exposure table on public data, gated on the denominator; the direction-of-error arm (which construct the published work actually used) is C, needing repository and depositor cooperation, and is not routed"},{"id":"OP-UQ-20261016-32","kind":"literature","field":"Medicine","title":"What is the extent of under-staging and under-treatment produced by terminal-digit preference in reported breast tumour diameter — the fraction of cases whose pT category, and with it …","text":"What is the extent of under-staging and under-treatment produced by terminal-digit preference in reported breast tumour diameter — the fraction of cases whose pT category, and with it adjuvant-therapy and trial eligibility, is decided by rounding to a multiple of five rather than by the tumour? Posed and deferred by the paper that quantified the error. Computable part: deconvolve the digit heap in a national registry's invasive-breast diameter distribution and integrate the recovered density across the 20 mm pT1/pT2 cut-point, reporting cases per year with the deconvolution assumption named as the load-bearing one — note that the reported-integer windows 18-22 mm and 16-24 mm each contain exactly one multiple of five, so the answer is set by how the 20 mm spike is deconvolved and barely at all by the window width. Do NOT re-run the error characterisation: Tsuruda 2020 already gives the digit distribution (all mammographic and 97.2% of histopathologic diameters in whole millimetres; digit 0 or 5 in 38.7% and 34.8%), the paired mammographic-minus-histopathologic difference (+1.26 mm, growing with size) and ICC 0.52 on the 6,865 cases with both. Read PMID 29580861 first: \"Breslow thickness measurements of melanomas around AJCC staging cut-off points\" pairs imprecision with terminal-digit bias for melanoma and may already have done this for one organ — its PubMed page returned an empty body from this environment, so it is unread rather than absent. The estimator is not new and should not be reinvented: laboratory medicine computes the same quantity as the \"incremental reclassification rate\" with published fitness-for-purpose bands (Farrell et al. 2026, doi 10.1515/cclm-2026-0259), and educational measurement as classification accuracy and consistency at cut scores. PROVENANCE: routed from a ledger entry that is Provisional, not rejected, and this is NOT that entry's question — UQ-20261016-32 asks about specimen-handling-induced change along the excision-to-slide chain, a different error source, so the two do not overlap and working this row does not pre-empt it.","work":[],"target":"","open":0,"source":"Tsuruda KM, Hofvind S, Akslen LA, Hoff SR, Veierod MB, \"Terminal digit preference: a source of measurement error in breast cancer diameter reporting\", *Acta Oncologica* 2020;59(3):260-267, doi 10.1080/0284186X.2019.1669817 — the conclusion, read and verified verbatim against the paper: \"Further studies are needed to investigate the potential extent of under-staging and under-treatment resulting from this measurement error.\" \"This measurement error\" is terminal-digit preference (rounding to 0 or 5) together with mammographic-versus-histopathologic disagreement. Data: Cancer Registry of Norway, invasive breast cancers 2012-2016, n = 7,792 mammographic and 13,541 histopathologic diameters. Correction to an earlier draft of this row: the phrase \"remains to be examined\" was attributed to this paper during the batch and does not appear in it, and the error it defers is NOT specimen handling.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B — the method is standard and the deconvolution is cheap, but the heaping deconvolution needs record-level diameters rather than published aggregates, so a registry data request (Cancer Registry of Norway, or any registry publishing whole-millimetre diameters) is the gating step; the melanoma read in the Problem column should come before the request, since it may close the question for one organ"},{"id":"OP-UQ-20261016-40","kind":"literature","field":"Biology","title":"Does a particle set that a cryo-EM curation step FILTERED OUT contain a distinct conformational state of the same molecule?","text":"Does a particle set that a cryo-EM curation step FILTERED OUT contain a distinct conformational state of the same molecule? Raised in print as untested speculation by the paper that reconstructed such complements and measured only their map quality. The undone part: 3D-classify the rejected complement of deposited EMPIAR entries under a pre-registered distinct-state criterion, against size-matched random subsets of the retained set, and report per entry whether a state appears that the retained reconstruction does not carry. Do NOT re-run the map-quality half - bioRxiv 2025.11.12.688030 already reconstructs complements for EMPIAR-10024 (lowest-scoring 12k and 18k particles reaching 5.44 A and 4.67 A, the complement arithmetic exact against the stated 43.5k total) and EMPIAR-10093 (lowest-scoring 90k reaching 4.38 A, against 4.08 A from the top 84k; note those two subsets differ by about 7%, are nowhere stated to be disjoint, and cannot be shown to be complements at all because the entry's stack total is not printed). Do NOT treat the ALK reanalysis as having answered it: PLoS Biol 23 (2025), doi 10.1371/journal.pbio.3003124, recovers a 2:1 ALK-ALKAL2 state at 3.2 A from EMPIAR-10930, but that archive deposits only 13,618 micrographs plus about 18M picked-particle coordinates and no curated final stack, so the original study's accept/reject labels are not recoverable and its result is a re-processing of raw data rather than a rejected-set finding. Read first: PMC12485487, \"How many (distinguishable) classes can we identify?\" (2025), unopened by this ledger. Provenance: located at Gate 2 and Gate 4 of UQ-20261016-40 and narrowed by its verification pass. UQ-20261016-40's own compound question - a pooled share across K entries plus a curator-overlap Jaccard - is NOT this row and is deliberately not routed: nobody has posed either, and the Jaccard limb additionally needs a within-curator replicate baseline, since RELION/cryoSPARC classification is stochastic run to run.","work":[],"target":"","open":0,"source":"bioRxiv 2025.11.12.688030, \"Automated filtering of particle images in single particle cryoEM\" - raises it and does not test it. Verbatim, closing its section: \"It is important to note that the filtered-out particles may exhibit different conformation(s) of the molecule, implying heterogeneity.\" No 3D classification or heterogeneity analysis is performed on any rejected set, and no rate, share or count of distinct-state recovery is estimated under any stated criterion. Independently checked while verifying this entry: no pooled picked-to-final attrition statistic exists over cryo-EM depositions, and no cryo-EM processing ring trial has measured the overlap of independently curated retained or rejected sets.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"OP-UQ-20261016-61","kind":"literature","field":"Medicine","title":"Is the fall in rare-disease time-to-diagnosis real, once the patients whose symptoms began recently and whose diagnosis has not happened yet are accounted for?","text":"Is the fall in rare-disease time-to-diagnosis real, once the patients whose symptoms began recently and whose diagnosis has not happened yet are accounted for? Posed in print as a correction to a specific published decline, and explicitly left unanswered: the letter that raised it offers waiting twenty more years as its only remedy. The routed limb is the identifiable one only — estimate the onset-to-diagnosis distribution per symptom-onset cohort from registry records that carry both an onset date and a diagnosis date, under explicit right truncation (reverse-time Kaplan–Meier, or a reporting-delay nowcast), report it beside the naive diagnosed-only estimate on the same records, bound with a pre-stated sensitivity band how far a delay-dependent never-diagnosed fraction could move it, and decompose any remaining change into truncation artefact, case-mix and diagnosis hazard. NOT routed, deliberately: the stronger version that would enumerate symptom-onset cohorts including the never-diagnosed. The ledger's own Gate 4 on UQ-20261016-61 (attack 4, Unresolved) showed that onset-cohort membership is not knowable without the diagnosis label or a biomarker clock, and the HIV precedent does not transfer — Birrell et al. 2012 identifies time-to-diagnosis and undiagnosed prevalence jointly only because CD4 count at diagnosis supplies a time-since-infection clock, which rare disease has no counterpart to. Do NOT re-run the qualitative demonstration that the naive estimate is biased: the letter states it, and the authors of the series it criticises name censoring, channelling and immortal-time bias in their own text. Provenance: located at Gate 2 of UQ-20261016-61 and narrowed by its verification pass.","work":[],"target":"","open":0,"source":"Feldtkeller E, Rudwaleit M, correspondence, *Ann Rheum Dis* 2014;73(12):e77, https://ard.bmj.com/content/73/12/e77 — opened and verified verbatim, each string checked singly and jointly: \"The authors neglected in their analysis and interpretation all the patients with recent symptom onset who were not yet diagnosed and are therefore not part of their database.\"; \"the average delay in diagnosis found in the DANBIO register seems to be a realistic approximation only for former disease-onset decades, that is, for patients with symptom onset 20-40 years ago\"; \"However, in order to demonstrate this reduction reliably, we need another 20 years passing by.\" No correction is proposed or applied: the letter names the missing observations as \"diagnoses to be expected in the future\", records that Fries et al. called the problem \"right censoring\", and prefers to call it \"an incorrect analysis and incorrect data interpretation\". The paper it criticises (Sørensen & Hetland, DANBIO, *Ann Rheum Dis* 74(3):e12, opened in full during the batch) reports the delay decline and names censoring, channelling and immortal-time bias without correcting for right truncation; its 240-month cap is a variance cap, not truncation handling, and its recent-onset sensitivity analyses make the truncation worse. Twenty queries in the batch plus the verification pass found no truncation-corrected onset-cohort delay distribution for any rare disease. Caveat: the verbatim matches come from a page summariser rather than raw page text.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B for the routed limb — the estimator family and software exist (reverse-time Kaplan–Meier, back-calculation, nowcasting), so the gating step is record-level access to onset and diagnosis dates for a registry that has published a delay decline. The incidence-anchored version is C and is not routed; see the Problem column."},{"id":"OP-UQ-20261017-05","kind":"literature","field":"Other fields","title":"Does exposure to the expected value — an analyst's knowledge of a preexisting recommended value — degrade the calibration of quoted uncertainties in a series of physics measurements of the …","text":"Does exposure to the expected value — an analyst's knowledge of a preexisting recommended value — degrade the calibration of quoted uncertainties in a series of physics measurements of the same quantity? Posed in print in 1986 with its predicted signature named, and never estimated. Any test must estimate herding and calibration JOINTLY per stratum rather than excluding the central-value limb by assertion: this is the ledger's own algebra, not a cited result — the squared bias enters E[p^2] for a normalised residual, so a calibration factor fitted on pulls cannot be made independent of the central value by declaring it so. Computable part on public data: the two-reference decomposition — chi-square of normalised residuals against the contemporaneous published average AND against the final value, per quantity, which Klein & Roodman did for four quantities — run over the Review of Particle Physics measurement histories, Bailey's Dryad dataset (doi 10.5061/dryad.jb3mj), Croft & Dailey's 637 cosmological measurements and Lopez-Corredoira's H0 series. Report a robust per-stratum scale (a Student-t scale or the median absolute pull) alongside the variance multiplier first, because the factor is outlier-dominated in this corpus family. Do NOT re-run the marginal calibration: it is published several times over (Birge ratios 1.2-3.0; Bailey's tail index near 2-3; Croft & Dailey's factor of about 2 before 2000, with supernova errors recently OVERestimated at N_sigma 0.5 +/- 0.07 and 0.77 +/- 0.12, a direction reversal inside the same corpus). NOT part of this row: the central-value limb (does blinding de-bias the mean?). It looks routable on the same two sources, but the sentences that would pose it were not verbatim-verified by this ledger's checking pass, and a row's posing sentence is quoted from the paper rather than from an adversary's summary. It is recorded here as a candidate row awaiting that check. Provenance: located at Gate 2 and Gate 4 of UQ-20261017-05 and corrected by its verification pass.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261017-05","open":1,"source":"Henrion M, Fischhoff B, \"Assessing uncertainty in physical constants\", *Am. J. Phys.* 54(9):791-798 (1986), doi 10.1119/1.14447 — opened in full and verified verbatim: \"Having a preexisting recommended value may particularly encourage investigators to discard or adjust unexpected results, and so induce correlated errors in apparently independent experiments.\" and \"The result would be initially small Birge ratios, unduly tight confidence intervals, and the exclusion of discrepant data.\" They pose the mechanism and do not estimate it: there is no exposed-versus-unexposed arm anywhere in the paper. What they do measure is pooled calibration — Birge ratio, interquartile index and surprise index over the speed of light (27 values, 1875-1958), G (14 values), the proton magnetic moment, the inverse fine-structure constant, the ohm ratio, and 306 Particle Data Group lifetimes and meson masses — concluding \"Reported uncertainties are too small.\" CORRECTION to an earlier draft of this row: the remedy they propose is referee-blind review, not analysis blinding — \"referees might be asked to scrutinize the account of an experiment 'blind,' before knowing its outcome and whether it affirmed prior expectations.\" Blinding the analyst to the recommended value is this ledger's operationalisation, not theirs. Klein JR, Roodman A, *Annu. Rev. Nucl. Part. Sci.* 55:141-163 (2005) report no blinded-versus-unblinded calibration comparison; their one quantitative item is a clustering check on four historical unblinded series — \"the measurements do tend to cluster nearer the prior published averages than the final value\", with chi-square \"131.2 for 83 degrees of freedom\" about the prior averages against \"249.7\" about the final average. The words \"pull\" and \"normalized residual\" do not appear in what could be read, so the pull-variance argument in the Problem column is this ledger's derivation, and the factors it implies (1.26 against 1.73) are the ledger's arithmetic on those two printed chi-squares. Croft RAC & Dailey M, arXiv:1112.3108, opened and verified: \"The total number of parameter measurements in the 20 year period shown is 637\", 12 cosmological parameters 1990-2010 scraped from ADS abstracts, endpoint N_sigma against a WMAP7 fiducial, \"consistent with an average underestimate of the error bars by a factor of ~2\" before 2000 and \"results in the last 10 years are consistent with expectations\"; blinding appears only as a recommendation — \"Wider use of blind analyses in cosmology could help to avoid this\" — and never as a measured covariate. So the era- and method-stratified version of this analysis exists and is one covariate short, fifteen years on.","badge":"Has a part computable from public sources","tier":"A for the two-reference herding-plus-calibration decomposition on the existing public compilations, which are already assembled and public. The blinding-coded exposure arm is C: it needs hand-coding of analysis protocol from hundreds of primary papers with inconsistent pre-2000 reporting, and it is collinear with the factor-of-two era shift Croft & Dailey document at the same boundary where blinding spread, so the era confound has to be addressed in the design rather than adjusted away afterwards."},{"id":"OP-UQ-20261017-13","kind":"literature","field":"Biology","title":"Does a change of the aggregation unit move spatial-transcriptomics conclusions, and is there a support above which they stop moving?","text":"Does a change of the aggregation unit move spatial-transcriptomics conclusions, and is there a support above which they stop moving? Posed in print by name, in this field, and explicitly left unmeasured: the posing paper says the influence of the aggregation unit \"is completely unknown and ignored\" while noting that \"there are well established approaches for quantifying the impact of the MAUP\". The routed limb is the measurable one: for a pre-declared set of Visium HD and Stereo-seq datasets re-binned to a ladder of square supports, and for outputs well defined on an arbitrary areal support (an SVG rank list; a spatial-domain partition at fixed k), decompose each output's variance into a tissue-identity component and an aggregation-support component against a within-support resampling noise floor, and test whether a support s* exists above which the support component falls below that floor by a criterion declared before any data are pulled. Declare the ladder, the datasets, the methods and the criterion first, because both branches are substantive and the criterion is what makes them distinguishable. Use the owning field's existing instrument rather than inventing one: S-maup (PLOS ONE 2018, doi 10.1371/journal.pone.0207377) is a formal MAUP-sensitivity statistic, and the geography literature's change-of-support machinery already covers this. Do NOT re-run the qualitative demonstration that bin size matters, which is published several times over: arXiv 2602.02825 \"On the consistent and scalable detection of spatial patterns\" already plots per-gene spatial-variability Z-scores at 8 um against 16 um on Visium HD (\"comprising 164,800 bins at 16 um resolution, and 656,788 bins at 8 um\") with outliers picked out, including that \"the 'Swiss roll' pattern introduced during sample preparation was preferentially detected at 8 um resolution\", attributed to \"signal dampening at the 16 um Nyquist limit\"; and FICTURE (bioRxiv 2023.11.04.565621) reports grid-size dependence qualitatively (\"Making the grid smaller slightly improved the resolution but led to extremely noisy cluster assignments\") as its motivation for going segmentation-free. Neither is an answer, and this ledger's verification pass narrowed what arXiv 2602.02825 is: the 8-vs-16 um contrast appears only in the full HTML text, is one illustrative cross-resolution sanity check inside a paper about a scalable spatial-pattern test, and carries no stability metric, no noise floor, no variance decomposition and no mention of MAUP. What is missing is the metric, the floor and the criterion, not another pair of supports. Do NOT treat STExplorer (Zormpas et al., bioRxiv 2025.01.17.633539) as having answered it: it names MAUP and Visium HD binning (\"may introduce artificial ecotones by binning\") and then fixes the support, its unit is the bin at one support and its estimand is a local non-stationary association. Do NOT treat the SVG and domain-detection benchmark family (Genome Biology 2024 and 2025; Bioinformatics 2025; NAR 2025) as prior art: their unit is the method and their endpoint is performance, all at fixed support. Two presuppositions must be carried as stated limitations rather than assumed away: re-binning only stands in for capture at that support, since real coarse capture also changes sensitivity and diffusion, so any measurement is a LOWER BOUND on support-dependence; and segmentation-based pipelines and cell-level cell-cell communication must be quarantined as a separate limb, because they presuppose cells rather than an arbitrary areal support. One further limb is NOT established and should be measured rather than assumed: that a non-trivial body of published conclusions actually rests on a default support. Read first, unopened by this ledger: the body of the Cell 2023 review \"Mapping the transcriptome\" (cell.com fulltext and PDF both client-errored; the White Rose eprint 218767 landing page was read and its keyword list includes \"modifiable areal unit problem\", but the PDF was not opened within budget) — it is the most likely place the posing already reaches into the target field's flagship venue, and it can only harden the case that the question is asked. Provenance: this is UQ-20261017-13's own canonical question, rejected at Gate 2 as asked-but-open rather than as a disguised known, since the import is explicit and under its own name.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261017-13","open":1,"source":"Comber A, Zormpas G, Queen R, Cockell S, \"Lessons from spatial transcriptomics and computational geography in mapping the transcriptome\", *AGILE: GIScience Series* 5:21 (2024), doi 10.5194/agile-giss-5-21-2024 — read in full and verified verbatim in the PDF body by a fresh-context checker: \"The choice of aggregation unit will influence process understanding through scale (MAUP) driven distortions but this is completely unknown and ignored\", alongside \"there are well established approaches for quantifying the impact of the MAUP\". It is a position piece: no data unit, no endpoint, no estimand, and it measures nothing. Corroborated as still open two ways. STExplorer (bioRxiv 2025.01.17.633539), from overlapping authorship, carries the named problem into the field's own literature and then fixes the support without testing it. And the quantity itself is unpublished: a mandatory query aimed squarely at the fraction of spatially variable genes that changes with bin size found it has never been reported, and a search for re-binning concordance of spatial-domain clustering (Stereo-seq bin20/bin50/bin100, ARI) found no such study — the comparators in that literature are methods, platforms and organs, never supports. Twenty documented searches across the target field in its own words, geography and geostatistics (MAUP, change of support, ecological fallacy), landscape ecology (grain and extent), signal processing (Nyquist), image downsampling and Chinese-language terms found no formulation that measures it. Caveat: the verbatim matches come from a page summariser rather than raw page text, and the Cell 2023 review body is unread.","badge":"Has a part computable from public sources","tier":"A — public Visium HD and Stereo-seq data exist down to 2 um, re-binning is arithmetic, the methods are installed and S-maup supplies the criterion; the binding constraint is pre-declaration discipline, not compute or access. The segmentation limb is B, since it needs a segmentation ground truth the binned limb does not."},{"id":"OP-UQ-20261017-14","kind":"literature","field":"Biology","title":"Do individual DNA molecules carrying a mutation differ in their own local methylation from molecules at the same locus that do not?","text":"Do individual DNA molecules carrying a mutation differ in their own local methylation from molecules at the same locus that do not? Posed in print as a cis-factor hypothesis and shipped as a documented statistical test, and reported by nobody. The routed problem is to run the test and publish the estimate, which nothing read here has done for any variant class, germline or somatic. The tool already exists and should be used rather than rebuilt: epialleleR's generateVcfReport (Bioconductor; Nikolaienko, Lønning & Knappskog, GigaScience 12:giad087, 2023) \"calculates frequencies of single nucleotide variants (SNVs) within epialleles\" and \"tests for the association between SNV and epiallelic status using Fisher Exact test\", returning per-strand Fisher p-values (FEp+, FEp-) over methylated and unmethylated read counts split by reference and alternate allele at the same position (columns M+Ref U+Ref M-Ref U-Ref M+Alt U+Alt M-Alt U-Alt SumRef SumAlt). DO THIS FIRST, before any new analysis, because it could close the problem instead of opening it: establish whether a generateVcfReport result has in fact been published. Open the three epialleleR user papers its README names (Lønning et al., JAMA Oncol 2022; Nikolaienko et al., Genome Med 2023; Nikolaienko et al., Clin Epigenet 2025) — the README does not say any of them used that function — and the forward citations of both epialleleR and MethylSaferSeqS (PNAS 120:e2220704120). None of those was opened by the ledger, and they are the likeliest place an answer sits. Two sourced constraints bound the design and are the sharpest things this problem has to say. (1) Under bisulfite chemistry the standard tool is blind to the headline mutation class: the vignette's own code comment reads \"# NA values are shown for the C->T variants on the '+' and G->A on the '-'\" \"# strands, because bisulfite conversion makes their counting impossible\", and output is \"currently limited to SNVs only\". Since C>T at CpG is canonically 5mC deamination, the class with the strongest mechanistic prior is exactly the one that cannot be counted that way, so either a conversion-free route or a copy-the-strand-first architecture is needed for it. (2) No per-read 5mC error rate exists for any instrument demonstrated to co-measure sequence and methylation on one molecule. Per-read rates DO exist off that intersection and are the right calibration precedent — Yuen et al., Nat Commun 12:3438 (2021), nanopore, \"The predictions were performed on individual reads, and then summarized per CG site\", \"using reads from 0% and 100% methylated sets\", AUCPR \"above 0.8\"; and ccsmeth (Nat Commun 2023, PacBio CCS) reports per-read \"accuracies of 0.9232, 0.8788, and 0.8765\" against M.SssI and PCR controls — but both are floors rather than tight bounds, the same literature says per-read accuracy \"remains largely unknown\" and calls per-read recovery \"a major limitation\", and PacBio's own primrose/jasmine figures could not be opened. Three things NOT to redo, each already published with numbers. MethylSaferSeqS (PNAS 2023) demonstrated the co-measurement chemistry and compared mutant with wild-type molecules in two patients — but at the mutated base itself, at loci chosen because the mutation alters the very CpG being measured (\"As expected\"), with no flanking window: PIK3CA p.H1047R, 11 of 406 UIDs mutant, 82% of those methylated in the CGT trimer against 1.3% of 398 C residues in the wild-type CAT trimer; TP53 p.R248W, 65 of 900 mutant, 98% of 835 wild-type UIDs methylated in CCG against 3.1% of mutant CCA trimers. Kusmartsev et al. 2020 (Genetics 214:809) is NOT prior art and runs the opposite direction of inference — a population-level association in which methylation predicts flanking SNP incidence, \"nucleotides in the close vicinity (+/-3 bp) of methylated cytosines mutate less frequently\". And HiDEF-seq (Nature 630, 2024) is not the conversion-free escape it looks like: it does not call 5mC at all, detecting cytosine deamination as damage and using polymerase kinetics to characterise ssDNA damage rather than methylation. Two design hazards to carry as stated limitations rather than assume away, both identified by the ledger's own Gate 4 and NEITHER sourced, so they are reasoning to address rather than findings to cite: in non-clonal tissue, mutation-bearing molecules are enriched for the lineage carrying the mutation and matching on locus, sample and strand does not match on cell of origin, so a positive association is equally well explained by subpopulation composition as by anything in cis; and a conversion deficit shared by both arms of a within-locus matched contrast attenuates it and costs power rather than manufacturing it, which bites hardest on the bounded-null branch, where attenuation and a true null are not distinguishable without a measured per-read conversion rate. Per-read conversion QC on the read's own non-CpG cytosines is the available remedy and was not applied by MethylSaferSeqS; epialleleR itself models a read-level epiallele that \"represents the product of incomplete bisulfite conversion\". Also unresolved and worth one fetch: Beaulaurier et al. (PMC4490391), bacterial single-molecule methylome phasing, defeated the ledger's fetch cap and is the nearest unopened cross-field neighbour. Provenance: this is UQ-20261017-14's own canonical question. It is routed rather than withheld because the ledger's reason for rejecting it is that the question is ASKED, not that it is answered: its original \"already answered\" ground was withdrawn on verification, and the late Gate 4 rejected it instead on Disguise, the question being posed and implemented while its answer is unpublished.","work":[],"target":"","open":0,"source":"epialleleR, Bioconductor package and GigaScience 12:giad087 (2023), doi 10.1093/gigascience/giad087 — poses the question and ships the test, and reports no result. Verified at first hand by three independent fresh-context readers, two of whom opened the vignette and README and one the published paper, with a third opening the bioRxiv preprint. Verbatim from the vignette: \"The association of methylation with single-nucleotide variations within epialleles can be tested using generateVcfReport\" and \"tests for the association between SNV and epiallelic status using Fisher Exact test\"; from the README, \"test for the association between epiallele methylation status and sequence variations\"; from the preprint, the framework \"allows to connect DNA methylation status with potential underlying cis-factors\" \"such as single-nucleotide variation or mutations within the immediate proximity\" — a capability statement with no result attached. The published paper names \"single-nucleotide variations or mutations within the immediate proximity\" as cis-factors for epimutations. The vignette's own worked example returns no association, and the package's output is \"currently limited to SNVs only\". Still unanswered: a dedicated sweep for a published comparison of methylation between variant-carrying and non-carrying reads at the same locus in the same sample found nothing over 8 searches and 6 fetches, in vocabularies spanning read-level joint variant-and-methylation analysis, epiallele association with sequence variants, allele-specific methylation at somatic variants, methylation haplotypes, clonal haematopoiesis, tumour long-read sequencing split by somatic-variant status, and cis-effects of somatic mutation on local methylation; plus 16 Disguise queries across two cold adversaries in paleoepigenetics, immunology and somatic hypermutation, bacterial single-molecule methylomics, hairpin-bisulfite, cis-ASM and meQTL, Chinese-language terms, pre-NGS single-clone bisulfite, epiallele/epihaplotype and single-cell multi-omics. The nearest things found are each something else: a 2026 clonal-haematopoiesis preprint (medRxiv 2026.04.03.26350108, DNMT3A R882 and TET2) compares across individuals and edited cells on per-CpG beta values — \"Individual beta values, represented as the ratio of methylated reads to total coverage\" — not mutant versus wild-type reads; a nanopore DLBCL abstract calls somatic variants and phases them with no methylation comparison; and Akbari et al. (bioRxiv 2024.02.26.582089) mentions joint genome-and-epigenome measurement only in its introduction. Caveats on the negative: it is bounded over what was opened, not over the literature. The epialleleR reference manual is ROBOTS_DISALLOWED, so how a read is classed methylated or unmethylated (and the claimed 0.5 beta threshold) is UNVERIFIED and is a user inference; the three named user papers and both forward-citation sets are unopened; MethylSaferSeqS was read in its medRxiv preprint rather than the PNAS version of record, which could not be opened by any route; and every page was read through a summariser that caps quoted strings near 125 characters.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B — the tool is installed and the statistic is a Fisher exact test, so the analysis itself is cheap; the gate is data. It needs reads that carry both a called mutation and their own 5mC calls, which today means either targeted bisulfite amplicons with a copy-the-strand-first architecture (and then the C>T blind spot on one strand) or a conversion-free per-molecule route whose per-read 5mC error rate nobody has published. A germline-variant version on existing read-level bisulfite data is A and is the sensible first execution, since it exercises the same estimand without the mutant-molecule yield problem — but it is also the version closest to being already done, so the literature check above comes first."},{"id":"OP-UQ-20261017-16","kind":"literature","field":"Medicine","title":"Re-fit a published per-minute outcome-vs-elapsed-time decrement for a genuinely multi-clock prehospital interval (call-to-first-shock, EMS-to-ED hand-off) under a measured inter-source …","text":"Re-fit a published per-minute outcome-vs-elapsed-time decrement for a genuinely multi-clock prehospital interval (call-to-first-shock, EMS-to-ED hand-off) under a measured inter-source clock-offset error model by regression calibration or SIMEX, reporting the change in slope, its CI and the implied benefit of a one-minute improvement. Posed in print as a consequence and as a recommendation; never estimated.","work":[],"target":"","open":0,"source":"Brabrand et al., Dan Med J 2012;59(10):A4512 — \"the use of unsynchronized time telling devices in research introduces a systematic error and could lead to skewed results\" alongside \"Survival decreases with 7-10% per minute\", then dismisses it in passing: \"Such a small deviation will probably have little impact on the treatment of our patients or on research.\" (all three verified at first hand) — consequence asserted, never estimated; Goodwin et al., Front Digit Health 2022;4:932599, doi 10.3389/fdgth.2022.932599 — \"Employ techniques that incorporate temporal uncertainty into analysis\", recommended, never applied to a per-minute decrement; Utstein 2015 update (Perkins et al.) — \"The problem of lack of synchronization of clocks and other time-recording devices persists\", with \"The recommendation remains that 1 clock (or synchronization to a single clock) be used to determine all times\", i.e. the field's own consensus document names the problem and prescribes against it without quantifying its effect on any published estimate","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (a bounded sensitivity band is computable from Brabrand's published offset distribution plus a published slope and exposure SD; a true re-fit needs registry case-level timestamps and a measured per-pair offset model, nearer C)"},{"id":"OP-UQ-20261017-20","kind":"literature","field":"Medicine","title":"Identified effect of pre-analytical specimen rejection on downstream clinical endpoints — time to recognition of a critical result, escalation or ICU transfer, length of stay, additional …","text":"Identified effect of pre-analytical specimen rejection on downstream clinical endpoints — time to recognition of a critical result, escalation or ICU transfer, length of stay, additional venipunctures — in a linked LIS-EHR frame, with the rejected order as exposed unit and a non-rejected order for the same test, window and acuity stratum as comparator, under a declared identification strategy (phlebotomist identity, draw route or shift-level haemolysis propensity as instrument) whose exclusion restriction is tested by falsification outcomes. The process limbs are already published; the clinical-endpoint limb is not.","work":[],"target":"","open":0,"source":"Karcher & Lehman, Arch Pathol Lab Med 2014;138(8):1003-1008 (publisher article page opened on verification) — publishes abandonment at 11.2%, a 65-minute median delay to a usable result and \"In this study, 86.8% of rejected blood specimens led to repeated phlebotomy\", with no non-rejected comparator anywhere, and states of the clinical link \"Although not specifically assessed in this study, longer delays in test result availability\" ... \"may have an even greater negative impact on patient safety\"; Jacobsz et al., Clin Chem Lab Med 2011;49(12):2047-2050 (publisher PDF opened) — 481 of 32,910 specimens rejected, 51.7% repeated at a mean of 121 h, 5.1% in the critical range, and 40% of 30 chart-reviewed files judged affected by unblinded holistic judgement, with no comparator and no identification; SHOT Annual Report, acute-transfusion-reaction/ADU chapter (opened) — 15 of 94 delayed transfusions caused by sample errors and deaths attributed to repeat-sample delay, i.e. the harm limb case-answered and never estimated","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (the method is standard once the data exist; the binding constraint is linked LIS-EHR access at several sites with recollection policy recorded)"},{"id":"OP-UQ-20261017-26","kind":"literature","field":"Computer science and AI","title":"Does a serving engine's speculative verify pass reproduce plain decoding bit for bit at fixed input, M=1 against M=k+1?","text":"Does a serving engine's speculative verify pass reproduce plain decoding bit for bit at fixed input, M=1 against M=k+1? The narrow, identified form of the question, taken from the vLLM RFC's own title. The routed problem: on one engine and one open target/draft pair, run the target model's forward pass twice on the SAME prefix with the SAME weights, dtype and kernel configuration, once as a single query row (M=1) and once teacher-forced over the k+1 rows [t..t+k] that speculation submits, and compare the resulting logits and argmax bit for bit, reporting the rate and magnitude of disagreement as a function of k, batch shape and attention backend. This version is identified, and the broad one is NOT: this ledger's own Gate 4 established that in a production engine the \"excess deviation of speculation-on over a composition-matched speculation-off baseline\" has no estimand, because enabling speculation changes the number of query rows and hence the kernel path and reduction order even for a lone request, so batch composition is a post-treatment mediator and matching on it matches on a mediator. Teacher-forcing the same prefix through both shapes removes exactly that confound: there is no sampling, no acceptance, no trajectory drift, and the only difference is tensor shape. DO THIS FIRST, before any measurement: establish whether a vLLM maintainer has since adjudicated RFC 54506 and whether the batch-invariance work (the batch_invariant kernels and the deterministic-mode flags) already covers the verify pass; this session could read the issue body but not its metadata, comments beyond two non-maintainer replies, or linked PRs, because its GitHub access is scoped to one repository. An adjudication or a shipped guarantee could close the problem outright. Do NOT redo three things that are already published with numbers. arXiv:2607.17283 (Chordiya) already reports a non-rejection of distributional equality on the sampled leg (chi-squared 162.5 on 200 degrees of freedom, p = 0.976, 201 bins, 9,209 against 9,214 tokens from 100 prompts of 100 tokens at temperature 1.0) and already separates the bit-exactness question as \"a backend property\", running its greedy leg on an fp32 CPU backend because bit-exactness on its quantized backend was unattainable; its own limitations say \"All results are single-stream, batch-size-one, on one consumer machine;\" and \"The sampled-leg equivalence test has the statistical resolution of about 9,200 tokens per method\", and it discounts its own KL figure (\"the reported smoothed symmetric KL (0.471) is dominated by add-0.5 smoothing\"). arXiv:2510.22876 already reports same-engine spec-on against spec-off exact-match rates (vLLM+Spec 96.9 / 65.6 / 72.7 on Vicuna / Qwen3 / GLM4; SGLang+EAGLE 69.8 and 47.7; with its deterministic mode 85.0 and 50.6) and, importantly, a NON-speculative batched control at batch 4 of 53.8 / 92.9 / 93.3 — so on Vicuna the nuisance exceeds the treatment. And arXiv:2609.04748 already runs the adjacent prefix-cache axis against a disabled-cache repeat baseline (36.2% trajectory change at 16-bit against 75.0% at 4-bit), at batch size one, serially, with no speculation. Two hazards to carry as stated limitations rather than assume away. A null needs a noise floor, and the RFC itself supplies the right one: its control experiment ran two launches of the NON-speculative engine and found logits differing by up to 5.25 nats while the 64-token greedy output was identical, so a same-shape repeat baseline must be measured before any M=1-against-M=k+1 difference is called an effect. And every result is a statement about one build: dtype, attention backend, kernel autotuning and engine version all have to be pinned and reported, because in exact arithmetic the algorithmic effect is zero by the speculative-sampling proof, so whatever is measured is numerics-through-shape and is a property of the implementation rather than of the algorithm. Provenance: this is UQ-20261017-26's own canonical question, NARROWED. The entry is rejected, but not as an already-answered question: its Gate 2 novelty ground fell on a first-hand read, and the late Gate 4 rejected it on presupposition failure instead. The broad composition-matched version is explicitly not routed, because a question this ledger has shown to be non-identifiable is not routable as posed.","work":[],"target":"","open":0,"source":"vLLM RFC 54506, \"[RFC]: Batch invariance for speculative decoding needs to cover the forward pass (M=1 vs M=k+1)\" — open and unadjudicated, verified verbatim by a fresh-context reader. It states \"nothing in the current stack guarantees those two produce identical bits\" and \"At temperature 0, enabling speculative decoding can change the generated sequence relative to plain decoding.\", and asks that \"the target model's verify pass over rows `[t..t+k]` must reproduce, bit for bit, what plain `M=1` decode would produce\". That is the question posed, by the maintainers' own issue tracker, in the engine where it would be answered. Its status as open is bounded rather than certain: the only two responders are non-maintainers, no maintainer has ruled in what could be read, and the issue's metadata and linked PRs COULD NOT BE READ from this session (GitHub access scoped to one repository), so a later adjudication would not have been visible here. Corroborated as unmeasured two ways. The two purpose-built instruments for detecting served-model deviation both exclude this axis in terms: arXiv:2410.20247 (Model Equality Testing) evaluates quantization, watermarking, finetuning, 13 model substitutions and 31 API endpoints, and speculative decoding, batch size, concurrency, engine version and kernel choice are absent from 98% of its text as read; arXiv:2511.20621 (DiFR) states \"We have not evaluated our approach on other sampling procedures such as speculative decoding\" and \"We do not evaluate speculative decoding scenarios,\" citing lack of vLLM 0.10.0 support, with its Appendix F a sketch carrying no experiments. And no published study reports the teacher-forced M=1 against M=k+1 parity rate: nine fresh searches and four fetches in a cold literature survey found nothing, with the nearest miss being the prefix-cache paper above. Caveats on the negative: most of that survey's hits were titles only, it read no issue trackers or maintainer blogs, and every page in both passes came through a page summariser rather than raw text.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B — open software and open weights, so there is no access gate, and the comparison itself is arithmetic. What it needs is one GPU and a teacher-forced harness inside the engine that can dump both forward passes' logits at full precision, plus discipline about pinning the build. The smallest decisive version — one model, one prefix, one k, one backend, against a same-shape repeat baseline — is A."},{"id":"OP-UQ-20261017-32","kind":"literature","field":"Biology","title":"Source publication as a cluster, or a second variance component beside phylogeny, in a species-level allometric fit on a trait compilation: the per-publication entry counts, the design …","text":"Source publication as a cluster, or a second variance component beside phylogeny, in a species-level allometric fit on a trait compilation: the per-publication entry counts, the design effect for the SLOPE, and a source-clustered refit of a published exponent against its published interval. Routed as the narrow limb only. The broad form the candidate declared — deduplication to shared primary determinations — is NOT routable: it is non-identifiable at the unit its own priors use, because Genoud et al. put one entry per species into every analysis data set, so two rows cannot share a measurement on specified individuals. Published work not to redo: Genoud et al. 2018's own ALL / SELECT / SPOILED contrast, exponents 0.737 / 0.729 / 0.711 ± 0.009 / 0.010 / 0.013 S.E. over N = 817 / 549 / 549, which stratifies by measurement-condition quality, not by shared origin, and discards cluster identity by taking \"one of them ... chosen randomly\"; and Farrell-Gray & Gotelli's species-disjoint pairing of 22 published exponents (P = 0.2371 / 0.8827 / 0.1441), which looks like the remedy and is not, because it pairs studies sharing no species and so cannot touch clusters that span different species inside one database. Looks like an answer and is not: survey-statistics design effects and cluster-robust SEs, which exist and are applied to no species-level trait compilation; and the Moulton factor, which DEFINES the slope design effect (Cameron & Miller Eq. 6, exact for equal cluster sizes) without estimating it here — a definition, not a number. No effective sample size for a slope was found in anything opened. Unread items that could close or kill it: Genoud's Table S2, the only plausible input for per-publication entry counts, which failed on all six routes tried in two independent attempts (Wiley /doi/, /doi/full/, /doi/suppl/, doi.org 429, BORIS which states it holds no supplementary data, and a file-name search); Farrell-Gray & Gotelli's ESA archive E086-109-A1; and Kattge et al. 2020, unread on every route in two attempts, which leaves TRY's duplicate-record question unverified rather than open.","work":[],"target":"","open":0,"source":"Farrell-Gray & Gotelli 2005, Ecology 86(8):2084 — \"The second kind of nonindependence arises because data on the same species are sometimes used in multiple studies.\" (confirmed verbatim), remedied only by species-disjoint pairing, with no fraction, design effect or effective N and no pair of studies named; Genoud, Isler & Martin 2018, Biol Rev 93:404-438 — combination noise as \"common practice for time-saving convenience\", duplicates resolved by random choice, no per-publication entry counts","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (A only if Table S2 opens)"},{"id":"OP-UQ-20261017-37","kind":"literature","field":"Medicine","title":"Does realised cross-arm clinician exposure move cluster-randomised and stepped-wedge trial effect estimates, and what is the professional-level ICC that design methodology needs and cannot …","text":"Does realised cross-arm clinician exposure move cluster-randomised and stepped-wedge trial effect estimates, and what is the professional-level ICC that design methodology needs and cannot get? Asked twice in medicine's own literature and answered in neither. Magill et al. 2019 counted 82 of 234 trial articles (35%) reporting that staff delivered the active intervention in the control arm, 76 of those 82 citing one clinician delivering both treatments, with a median contamination of 13% (IQR 5–33%) over 23 binary-outcome trials whose unit is CONTROL-ARM PARTICIPANTS, and called for a systematic review of the design. Keogh-Brown et al. 2007 set out nineteen years earlier to quantify the effect of contamination on magnitude and precision, found that “Few relevant studies quantified contamination” and made reporting its extent “a priority”; its all-studies analysis found trials avoiding contamination “tended to have larger effects” while concluding “there is no clear evidence that the effectiveness estimate in trials that do not avoid contamination is biased”, and its high-quality reminder subset runs the other way, so the DIRECTION is genuinely open rather than merely unquantified. Three limbs, in order of cost. (i) The systematic review Magill asks for, executable from the public record: compare within-study cluster-level against participant-level allocation across the trials that ran both, on more than the 4 trials and 21 outcomes (8 of 21 attenuated, one tie, “just under half” in the anticipated direction) that Magill's own null rests on. (ii) The professional-level ICC, which Moerbeek & Safarkhani 2018 ask for in print — for cluster-randomised trials with crossed random effects “such estimates are hardly available in the literature” — and which their own worked example has to assume (ru = .3 from a published power analysis, rv = .1 and rw = .05 “without further justification”); they issue NO call to measure crossing FREQUENCY, so that is not what this row routes from them. (iii) A within-trial refit under a crossed clinician random effect, reporting how far the estimate and interval move against the published analysis, in a trial that holds provider identifiers. What this row does NOT route, because it is asked and partly answered: the article- and protocol-level prevalence of the phenomenon (Magill above; Jacobsen & Wood 2020, 14 of 100 protocols at high contamination risk with 10 of those 14 therapist-related, and only 57 of 100 protocols stating clearly who delivered the intervention, which is the ceiling on any literature-assembled frame). Nor is the causal contrast identified from a single realised cluster-level assignment, which the posing record concedes, so limb (iii) is a model-sensitivity comparison and must be reported as one. Adjacent and not prior art: Xierali 2018 reports 63.2% of 20,116 Georgia Medicaid-registered physicians at multiple sites with a mean of 3.3 — a marginal workforce rate, not a trial cohort, and internally inconsistent with its own Discussion statement that two thirds of Georgia physicians practised in one service location; Wilson-Aggarwal et al., Commun Med 2:165 (2022) supplies the instrument (staff located by ward and day from EHR pseudonymous identifiers plus door-access logs) with no trial and no arms.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261017-37","open":1,"source":"Magill et al., BMC Med Res Methodol 19:4 (2019), doi 10.1186/s12874-018-0646-z — “a systematic review of this particular trial design is needed”, verbatim, publisher route, verified at first hand post-batch; Keogh-Brown et al., Health Technol Assess 11(43) (2007), doi 10.3310/hta11430 — “it is a priority to report the extent, nature and effects of contamination” and CACE “if it can be measured”, read at executive-summary plus Chapters 1–2 level post-batch; Moerbeek & Safarkhani, J Educ Behav Stat 43(2):159–181 (2018), doi 10.3102/1076998617730303 — crossed-factor estimates “are hardly available in the literature”, SAGE full-text PDF, two independent fetches agreeing. All three verified post-batch by separate fresh-context readers; see the Verification block of UQ-20261017-37 in unasked-ledger.md for the unit corrections those readers made to the figures above.","badge":"Has a part computable from public sources","tier":"A for limb (i), which is public-record systematic-review work and is what the posing paper actually asks for. C for limbs (ii) and (iii): both need trial-held provider identifiers linked to arm and calendar window, so they are executable only by a trial team or an embedded-trial consortium — the instrument exists (Wilson-Aggarwal 2022) but the data are inside the trials. Limb (i) should come first regardless of access, because a null there changes what limbs (ii) and (iii) are worth."},{"id":"OP-UQ-20261017-46","kind":"literature","field":"Computer science and AI","title":"Cross-perturbation-type concordance of per-item benchmark flips for one fixed open-weight checkpoint: is numeric fragility a property of the item or of the perturbation — i.e. is the …","text":"Cross-perturbation-type concordance of per-item benchmark flips for one fixed open-weight checkpoint: is numeric fragility a property of the item or of the perturbation — i.e. is the between-type component of per-item flip propensity non-zero against a within-type null, with lossy (quantizer at matched bit width) and nominally-lossless (dtype cast, attention kernel, decode seed) arms crossed on one item frame at batch size 1 offline, and does it survive conditioning on the top-two logit margin? Post-batch verification enlarged this residual: the attention/kernel arm is absent from ALL FOUR priors, including HEAL, which the ledger record had wrongly listed as varying attention implementation (it holds TritonAttention fixed throughout because FlashAttention lacks 32-bit support).","work":[],"target":"","open":0,"source":"arXiv:2608.21382 Sec. 6 names a per-item flip predictor from the top-two margin as future work, verified at first hand — with the narrowing that the margin is recorded in its release for the plain-cloze scorer only, not for all 26 configurations, and that the paper contains no numerics arm, no concordance statistic, no null model, no margin conditioning and no stated batch size (the word \"batch\" does not occur in it). arXiv:2606.21023 (HEAL) asserts that flips originate from \"highly unstable questions\" but, verified at first hand, only as a two-fragment manual-inspection remark in Appendix B.1, scoped to high-precision configurations and framed by its authors as a dataset-quality caveat, with no statistic, no null and no batch-size-1 control. arXiv:2608.06564, read in full post-batch, states in Sec. 5.1 that which decision breaks is a property of the item rather than the algorithm, and supplies only raw same-item counts (77 of 77, 16 of 16) with no concordance statistic and no nominally-lossless arm. NOT VERIFIED: the adversary also cited arXiv:2605.28873 as stating \"We do not run paired McNemar tests on per-example correctness\"; that paper was not among the sources opened in the verification pass, so treat the quote as unconfirmed.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"OP-UQ-20261017-47","kind":"literature","field":"Computer science and AI","title":"Systematic cross-boundary accounting of frontier-model production compute: per-model estimates with stated uncertainty of (a) gradient-step, (b) RL rollout and verifier/reward inference …","text":"Systematic cross-boundary accounting of frontier-model production compute: per-model estimates with stated uncertainty of (a) gradient-step, (b) RL rollout and verifier/reward inference, (c) synthetic-data generation, (d) distillation-teacher inference and (e) discarded/failed-run compute, for a frame declared before any data pull; the distribution of R = (b+c+d+e)/a; Spearman rho between reported \"training compute\" and total production compute; and how many models change 10^25 FLOP status (EU AI Act Art. 51(2)) between the Commission's C(2025) 5045 paragraph 119-122 inclusion list and a widened one — i.e. is the boundary choice larger than the 30% estimation tolerance paragraph 123 allows, and does the answer hold with GPU-hours or board energy as the denominator rather than FLOP?","work":[],"target":"","open":0,"source":"Epoch AI, Somala, Ho & Krier, \"Three challenges facing compute-based AI policies\" (2025-09-11), verified at first hand: it poses the accounting problem, states that \"current policies typically only count the compute from the student run\" and that \"the compute invested in building reward models remains entirely unaccounted for\", and supplies only scattered best-guess point ratios (phi-4 synthetic data ~25% of pretraining; R1-Zero RL one-fifth of base pretraining; DistilBERT 3%) with no uncertainty, no frame, no distribution, no rank correlation and no threshold recount — the strings 10^25 and 10^26 FLOP do not appear in it. Verification also narrows what Epoch poses: discarded and failed runs are NOT discussed in it at all, verifier inference is not quantified, and the o1-high figure is reasoning training compute rather than inference. Epoch AI, Cottier & Owen, \"Model counts and compute thresholds\" (2025-05-30, opened at Gate 4) declares post-trained variants out of scope and needing further investigation. EC C(2025) 5045 paragraphs 119-123 declares inclusion and exclusion lists and a 30% tolerance without testing its own exclusions against that tolerance. The only partial per-model answer is in hardware-hours and energy: arXiv 2605.01158, which verification identifies as Morrison, Smith & Strubell's \"The Hidden Cost of Thinking\" (1 May 2026) rather than the Olmo 3 report, puts development including failed runs at 82.2% of total GPU hours (6.85M of 8.34M) for the Olmo 3 family — but its denominator excludes 4,866,064 MI250X GCD-hours of synthetic-data generation in a non-comparable hardware unit, it computes no non-gradient-to-gradient ratio, and it contains no FLOP figure anywhere.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"OP-UQ-20261017-51","kind":"literature","field":"Biology","title":"Does the within-body cell count-size relation, and its consequence of near-equal cell biomass per logarithmic cell-size class, hold in animal bodies other than the human one, and is the …","text":"Does the within-body cell count-size relation, and its consequence of near-equal cell biomass per logarithmic cell-size class, hold in animal bodies other than the human one, and is the fitted slope independent of species body mass?","work":[],"target":"","open":0,"source":"Hatton et al., \"The human cell count and size distribution\", PNAS 2023, 120(39):e2303077120, read twice at https://www.pnas.org/doi/10.1073/pnas.2303077120 by independent readers. Posed as a conditional expectation in the section \"A Recurrent Pattern\": \"If we assume that the ratios of different cell types in different tissues are constant across species, we should expect a similar inverse cell size-count relation to hold in other mammals.\" Untested there: the paper's cross-species dataset is cell SIZE only for 33 cell types (Methods, Supporting data, SI Appendix Fig. S1) and carries no counts, so the premise is supplied and the measurement is not. The salamander precedent it cites is per organ, not whole body, and only partially compensating (read in Fankhauser, J Exp Zool 100:445-455, 1945; the cited Quarterly Review of Biology 20:20-78 review is COULD NOT READ). No non-human whole-body cell count-and-size census was found by Gate 2, by either adversary's answer-side sweep, or by two further dedicated sweeps.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"OP-UQ-20261017-52","kind":"literature","field":"Biology","title":"Does measured protein half-life predict the extent of acute degron depletion achieved per strain in a proteome-wide yeast AID collection?","text":"Does measured protein half-life predict the extent of acute degron depletion achieved per strain in a proteome-wide yeast AID collection? Narrow limb only. NOT routed, and the distinction matters: the composite the parent candidate asked for — decomposing the degron-versus-deletion essentiality discordance into incomplete degradation, half-life, conditional essentiality and readout artefact — is posed by nobody and is not identified on a depth-matched stratum, because that stratum is selected on degradability, which is correlated with the half-life regressor. Also NOT routed: the headline discordance rate, which these same papers answer.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261017-52","open":1,"source":"Valenti et al., \"A proteome-wide yeast degron collection for the dynamic study of protein function\", J Cell Biol 224(2):e202409050 (2025), rupress.org/jcb/article/224/2/e202409050/277168 — \"milder depletion could also reflect longer protein half-lives\", offered as an untested explanation and confirmed in the paper by three independent readers. Half-lives are estimated for only a handful of proteins by one-phase decay fits (Fig. 1D, \"A one-phase decay curve was fitted to the data to estimate the half-lives of each protein\"), and no correlation of half-life with depletion extent is reported anywhere. The companion paper, Gameiro et al., J Cell Biol 224(2):e202409007, does NOT raise half-life at all, offering incomplete degradation, conditional essentiality and readout artefact instead, so this row is sourced to e202409050 alone.","badge":"Has a part computable from public sources","tier":"A"},{"id":"OP-UQ-20261018-01","kind":"literature","field":"Medicine","title":"Once a disconfirming test result is already filed in the record, what is the time-to-event rate at which the chronic-disease label itself is retracted (problem-list removal …","text":"Once a disconfirming test result is already filed in the record, what is the time-to-event rate at which the chronic-disease label itself is retracted (problem-list removal, \"resolved\"/inactivated status, exclusion code) and at which disease-specific prescribing stops, measured against matched person-time in labelled patients with no such result? Asked and answered only in part: the two published limbs are cross-sectional prevalences of persistence with no comparator and no clock. Computable part: none from public sources. The prior art to read first is listed in the Source column; Fortis 2016's full text has resisted about 26 distinct retrieval routes across five independent readers, so an interlibrary or author request is the first step, not another search.","work":[],"target":"","open":0,"source":"Fortis SP et al., Respir Care 2016;61(9):1192-1200, doi 10.4187/respcare.04647 — asks the question for COPD and reports both limbs as prevalences (60/855 = 7% diagnosis persistence, 208/855 = 24% treatment persistence, both confirmed verbatim in the abstract), with no comparator, no time origin and a denominator of all non-obstructive attendees rather than of labelled patients; FULL TEXT UNREAD after about 26 routes. Jones H et al., Br J Gen Pract 2024;74(743):e364-e370, doi 10.3399/BJGP.2023.0271 — builds the retraction event into a 16,023-per-cohort CPRD GOLD design but treats resolution as the EXPOSURE, so the rate of retraction is never estimated. Two further priors that look like an answer and are not: Arnold NR et al., Respir Care 2021;66(4):652-660, doi 10.4187/respcare.08016 (COPDGene, 541/4,303 = 12.6% on inhaled medication at enrolment with about five years of follow-up and a no-medication reference group, the nearest longitudinal design in this literature — but its population is smokers with normal spirometry rather than patients carrying a label, and its main text reports neither diagnosis nor inhaler persistence); and Fortis 2013, BMC Pulm Med 13:68 (21/62 = 33.9% of obese patients with normal spirometry kept on obstructive-disease medication, the same manoeuvre by the same author three years earlier, in a different population).","badge":"Needs laboratory work or restricted data","tier":"C (nothing computable from public sources: needs licensed EHR data, CPRD/OpenSAFELY or a US EHR network, so a data application precedes any analysis)"},{"id":"OP-UQ-20261018-03","kind":"literature","field":"Medicine","title":"Is the within-operator recency-outcome association real, procedure-specific rather than general, and transportable across registries and specialties — and does any fitted curve support an …","text":"Is the within-operator recency-outcome association real, procedure-specific rather than general, and transportable across registries and specialties — and does any fitted curve support an outcome-calibrated currency interval? Open because the two CABG papers have never been reconciled, and because the one source that bins recency categorically declines to name a threshold. Computable part: none from public data; the transportability arm is nearer C than the rest.","work":[],"target":"","open":0,"source":"Hockenberry JM & Helmchen LA, J Health Econ 2014;37:70-80, doi 10.1016/j.jhealeco.2014.06.001 — positive per-day within-surgeon mortality association in Pennsylvania CABG, scheduling flagged endogenous, no interval derived; read in full only as NBER WP 20017, whose Table 2 flags the 0.032 coefficient at 5% while its text reportedly calls it non-significant, and the published body could not be read. Huesch 2014 (California CABG) — null on in-hospital and 30-day mortality, never reconciled with the above. Van Gestel YRBM et al., Health Econ 2017, doi 10.1002/hec.3505 — read as a working paper and found to be CENTRE-level: exposures are per hospital with hospital fixed effects and operator identity unobserved, so it is not the second positive operator-level registry it was taken for. Hockenberry JM, Lien H-M & Chou S-Y, J Human Capital 2008;2(3):303-335, doi 10.1086/593064 (read 2026-10-18) — the nearest published approach to the interval limb: 1-month mortality for CATEGORICAL day-bins of operator recency with surgeon fixed effects (CABG 3-14 days 0.008562 and 15+ days 0.013499 against a 0-2 day reference on 5.03% baseline mortality; PTCA in five bins), and it recommends no threshold. Note that WP 20017's \"11-14%\" does not appear in this 2008 paper, whose own coefficients imply about 17%. The 2025 target-field review (de Andres Crespo et al., Int J Surg) cites neither 2014 paper.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (standard method once the data exist; binding constraint is protocol-approved registry access carrying operator identifiers and dated per-operator case histories — a PHC4-style restricted extract, or NCDR/STS/NJR/GIQuIC. The cross-registry transportability arm is nearer C.)"},{"id":"OP-UQ-20261018-06","kind":"literature","field":"Other fields","title":"In block-maxima extreme-value modelling of environmental series, where an instrument's probability of failing to record depends on the MAGNITUDE of the value it would have recorded …","text":"In block-maxima extreme-value modelling of environmental series, where an instrument's probability of failing to record depends on the MAGNITUDE of the value it would have recorded (informative, measurand-dependent missingness), model that missingness mechanism explicitly inside the GEV fit and report the signed change in long-return-period levels against the conventional fit. Posed as an open need by Simpson & Northrop in their own Discussion and explicitly excluded from their approach. Still open on the modelling limb: every execution found imputes the censoring probability from information observed WITHIN the block, so none conditions on the magnitude of the unobserved value. The adjacent hazard-estimation question (what is the failure probability as a function of the measurand, in its own units) is NOT routed here, because it was asked and coarsely answered for the US ASOS/AWOS network in 2005 (Blessing & Masters, 10ACWE Paper No. 102) — which is why candidate UQ-20261018-06 was rejected while this limb survives as open. Computable part: the re-fit itself is standard once a magnitude-dependent missingness model is specified and a defensible h(y) exists for one network and measurand; the binding work is the selection model and its identification, not the GEV machinery.","work":[],"target":"","open":0,"source":"Simpson, E. S. & Northrop, P. J., \"Accounting for missing data when modelling block maxima\", arXiv:2512.15429v1, 17 Dec 2025, since published in Environmetrics, doi 10.1002/env.70075 (read at FULL TEXT on verification 2026-10-18). Two §6 strings verified verbatim, each checked alone: \"It is also quite likely for informative missingness to occur in environmental applications, but this is not accounted for in our current approach\" and \"one could attempt to explicitly model the missingness mechanism and incorporate this into the GEV model\". CAUTION for whoever picks this up: the routing candidate's record stitched those into one passage joined by \"To account for this,\" together with \"there is a need to be able to capture such phenomena\"; that stitch is NOT verified, and the last phrase is the tail of a different §6 sentence (\"It is easy to imagine situations where the most extreme events are the ones that are the hardest to reliably record, e.g., river flow gauges being damaged by fast-running water, and there is a need to be able to capture such phenomena.\"). Their own simulations impose MCAR within each block with the per-block missing proportion drawn from U(0, 0.2). Nearest executions, both read at full text and neither closing it: McVittie, J. H. & Murphy, O. A., arXiv:2506.15970 — unconditional-soft, conditional-soft and EM estimators whose censoring probability comes from the within-block non-missing proportion, the empirical CDF of observed values, or the fitted GEV CDF at the observed block maximum, with no external instrument, network or failure-rate information entering anywhere and the realized block maximum never reconstructed (Table 4, Saint John 20-year levels: observed 1.73 m, hard 6.26 m with SE 137.66 and unusable, softUC 1.88, softC 2.95, EM 2.65 m), and whose \"failure of the equipment was attributed to the high intensity waves\" is a HYPOTHETICAL MNAR scenario, not a documented station failure; and Dokic, Blagojevic & Mihailovic, \"Missing data representation by perception thresholds in flood flow frequency assessment\", J. Appl. Eng. Sci. 19(2):432-438, 2021, doi 10.5937/jaes0-28902 — the authors' own proposal (not B17C operational guidance, as the candidate record first had it), whose gaps are magnitude-dependent only by construction and which carries no magnitude-dependent probability model.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (standard method once the inputs exist; all public data — the published annual-maxima or peak series plus network outage flags — but the binding constraint is specifying and identifying a magnitude-dependent missingness model, plus an external evidence source for each lost peak that is independent of the failed instrument. The purely statistical arm, re-fitting under a declared h(y) on an existing series, is nearer A.)"},{"id":"OP-UQ-20261018-11","kind":"literature","field":"Computer science and AI","title":"For a released mixture-of-experts checkpoint evaluated under an expert-capacity limit, measure the quality penalty attributable to dropped tokens PER STRATUM against a capacity-free run on …","text":"For a released mixture-of-experts checkpoint evaluated under an expert-capacity limit, measure the quality penalty attributable to dropped tokens PER STRATUM against a capacity-free run on identical weights, inputs and decoding, and test whether that penalty rises with the stratum's own drop rate. Strata declared in advance: token position, dataset or domain, language or script, and token-frequency decile under a declared tokenizer proxy. The incidence limb alone is NOT routed: OpenMoE already measures drop rate by position and by dataset category, and LIMoE by modality. What is open is the paired penalty and the slope.","work":[],"target":"","open":0,"source":"POSED, verbatim and confirmed at first hand on 2026-10-18: OpenMoE (arXiv:2402.01739) Sec. 3.3.2 raises the attribution and leaves it as the untested conjecture \"We found that this probably be caused by the token drop of a long sequence\", while the paper contains no capacity-free arm at all (the strings \"dropless\" and \"capacity factor\" do not appear) and attributes no measured penalty to drops. Rectify-Router (arXiv:2402.12399) infers only that \"the dropped tokens have a substantial impact on model performance\" from router-variant gains, with no dropless baseline. LOOKS LIKE AN ANSWER AND IS NOT: Capacity-Aware Inference (arXiv:2503.05066, ICLR 2026) does run a true capacity-free baseline, but its finest accuracy grain is the benchmark sub-category (MMBench's six capabilities, SEED-Bench's dimensions) and never a token stratum, and its drop-rate breakdowns are per layer, per capacity factor and per dataset; LIMoE (arXiv:2206.02770) reports a per-modality share of tokens not dropped at layer 9 and compares dispatch orders on validation accuracy, but runs no capped-against-uncapped arm; Switch Transformers' \"(typically < 1%)\" is a remark about independence from the number of experts, not a rate at a stated capacity factor. UNREAD, so it could still close the slope limb: ST-MoE (2202.08906), V-MoE scaling (2303.07226) and 2212.07571.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (no training compute: released dropless-trained checkpoints, an inference harness that imposes a capacity factor and logs per-token drops, and a declared permutation test. The binding constraints are an in-harness noise floor small enough to resolve per-stratum deltas near a ~0.9% aggregate, and a token-frequency proxy for closed-corpus checkpoints. The incidence-only arm is nearer A and is not what is routed here.)"},{"id":"OP-UQ-20261018-12","kind":"literature","field":"Computer science and AI","title":"Measure the per-step FROZEN FRACTION — the share of nonzero optimizer proposals erased by low-precision write-back — in the frame shipped training configurations actually use: BF16 …","text":"Measure the per-step FROZEN FRACTION — the share of nonzero optimizer proposals erased by low-precision write-back — in the frame shipped training configurations actually use: BF16 parameters with BF16 or block-quantized 8-bit Adam state, across a full cosine schedule, in pretraining, at two or more model scales, broken down by parameter group, and with the held-out-loss consequence of the frozen set measured in a matched arm. NOT routed, because each is already answered: the aggregate per-step unchanged fraction, the coarse embedding-against-linear split, and the DIRECTION of schedule-phase dependence with the gradient-shrinkage-against-LR-decay confound decomposed.","work":[],"target":"","open":0,"source":"POSED IN PRINT, and verified at first hand on 2026-10-18. arXiv:2607.09800 (sole author Zekai Shang; NOTE its title differs between surfaces — \"Auditing Invisible Weight Updates with Reference Traces\" on the abs page, \"Reference Traces for Auditing Invisible Weight Updates and Guiding Exact-Budget Protection\" on the document's first page, and a third on a mirror) poses exactly this question and defines the event: Eq. (1) Q_m(q_i + d_i) = q_i, with \"and f_t is the fraction frozen on step t\". UNANSWERED IN THE DECLARED FRAME, on the paper's own text: in every study but two the low-precision values are analytic grids — \"Model values are signed-INT3 grid values held in fp32 containers\" — with fp32 compute, \"Adam moments remain fp32\" in all runs, and 1-D normalization parameters explicitly outside the quantized write-back path; nearly every tabulated figure is the CUMULATIVE never-moved fraction, which the paper itself says \"differs from the never-moved fraction\"; and it reports no per-group behavioural consequence. The one paper that does quantize the optimizer state, arXiv:2603.16731 (Topollai & Choromanska), keeps weights in BF16 except an App. A.12 FP8-weights ablation and carries no group, decile, norm-gain or token-frequency stratification and no LR-schedule link. arXiv:2605.07330 (SparseRL-Sync) measures a per-step unchanged fraction at 8B-671B (\"tends to increase over training\"; 99.3030-99.4006% at 30B) with no per-tensor or per-group breakdown and no mention of the learning rate anywhere. Zamirai et al. arXiv:2010.06192 App. D.3 / Fig. 9 gives the per-iteration cancelled-update percentage with a constant-LR control arm and attributes the rise to \"the compound effect from decaying gradient magnitude and decaying learning rates\", but on DLRM and splitting only embedding from linear. So: asked, partly answered on other units and other precisions, open in the frame that ships.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B (no new method: a logging patch inside an existing BF16 trainer that compares the optimizer proposal with the stored grid value each step, plus one matched-arm run per scale for the consequence limb. The binding constraints are access to a pretraining run at two scales with a block-quantized 8-bit optimizer state, and a frozen-set definition that EXCLUDES parameters outside the low-precision write-back path — 1-D normalization parameters and fp32-container grids silently inflate or deflate any fraction computed over \"all parameters\", which is the trap the prior literature falls into.)"},{"id":"OP-UQ-20261018-20","kind":"literature","field":"Biology","title":"What is the quantitative contribution of each form of cell death to the PHYSIOLOGICAL turnover of neutrophils?","text":"What is the quantitative contribution of each form of cell death to the PHYSIOLOGICAL turnover of neutrophils? Neutrophils are the one cell type for which the posing source states the per-modality split and declares it unclear, and they are a large share of the quantity: 0.5-1 million neutrophil deaths per second in humans on the posing source's own figures, and 18 +/- 4 g/day of the 80 +/- 20 g/day whole-body cellular mass turnover on Sender & Milo's. The candidate's own broader question -- the per-modality partition for a declared tissue under a calibrated marker panel -- is NOT routed, because it is a Provisional ledger entry's own question. This narrower one is routed because the posing source asks it of its own subject and answers it with \"unclear\": one cell type rather than a declared tissue, no panel, no residual, no reconciliation to a turnover total. The competing candidates for the dominant route are named by the source and are testable against each other: cell death by phagocytosis of still-living aged neutrophils (which leaves no corpse to count), against apoptosis followed by efferocytosis.","work":[],"target":"","open":0,"source":"POSED, and confirmed at first hand on 2026-10-18 by a fresh-context reader of the publisher-typeset PDF: Brown GC, \"Cell death by phagocytosis\", Nat Rev Immunol 24:91-102 (2024; online 2023), doi 10.1038/s41577-023-00921-6, subsection \"Turnover of erythrocytes and neutrophils\", sentence 14. The complete returned fragment is \"contribution of different forms of cell death to physiological turnover of neutrophils is still unclear\"; the whole sentence, labelled as a reconstruction from two consecutive returned fragments rather than seen as one unbroken string, is \"However, there is evidence of some contribution of apoptosis to the turnover of neutrophils45, and the quantitative contribution of different forms of cell death to physiological turnover of neutrophils is still unclear.\" The same review's Conclusions say the understanding of the \"extent and significance\" of death by phagocytosis \"is limited by the paucity\" of methods, and name the needed step as \"to quantify the contribution of phagoptosis to cell turnover in health or disease\". LOOKS LIKE AN ANSWER AND IS NOT: the same review asserts death by phagocytosis is \"the most common form of cell death in the body\", but that is an inference from erythrocyte and neutrophil lifespan arithmetic, performs no calculation, states no denominator for total body cell death, and is a claim about which form is largest whole-body -- not the neutrophil split, which the same subsection calls unclear two sentences earlier. Sender & Milo 2021 (Nat Med 27:45-48, read in full) fixes the neutrophil mass and count but assigns no modality in its accounting; its only modality sentence is a ~50/50 apoptosis-plus-phagocytosis against GI-and-skin-shedding split in a Methods subsection on power consumption, uncited, framed as an assumption. The NCCD 2018 recommendations, read at partial level, carry no quantitative share of deaths by modality anywhere in the read portion and do not address in-situ detection in tissue at all.","badge":"Needs laboratory work or restricted data","tier":"C (the measurement needs animal work: neutrophil turnover is bone-marrow-and-margin-dominated, the leading candidate route removes a living cell and leaves no corpse for any in situ panel to score, and no public dataset carries neutrophil death events with a modality assignment. The one arm that needs no new specimens is a bounding exercise -- how far published neutrophil lifespan, efferocytosis-rate and caspase- or MLKL-knockout data constrain the shares, and whether they constrain them at all -- which is worth doing first because it would say whether the question is currently answerable from the literature, but it is a bound and not the split.)"},{"id":"OP-UQ-20261021-02","kind":"literature","field":"Medicine","title":"Does decider-versus-recorded-prescriber discordance in hospital prescribing generalise beyond one UK teaching hospital: confirm the 61% (112/183) new-medicine rate at which the decision …","text":"Does decider-versus-recorded-prescriber discordance in hospital prescribing generalise beyond one UK teaching hospital: confirm the 61% (112/183) new-medicine rate at which the decision maker was not the prescription writer, in a larger sample of hospitals, and resolve it by drug class and by grade of doctor? NARROW THE ROW TO THE RESIDUAL: the prevalence itself is published for six wards of one large UK teaching hospital observed two weeks per ward from January to April 2011, and the authors call that estimate provisional, so the work not to redo is the single-site rate. The denominator there is new-medicine prescribing events only (183 of them), so no all-prescriptions rate exists to compare against. What could close it and was not readable here: the paper's own full text, for how observers established who decided as against who signed, and for any per-drug or per-grade breakdown. NOT part of this row, because nobody poses it: what wrong-prescriber attribution does to a prescriber-preference instrumental-variable estimate. The ledger looked for a poser and found none — Jiang and Ding (Biometrika 2020;107(1):238-245) prove their no-bias result for an all-binary model and write \"We do not consider the differential measurement error of Z\", which is a scope exclusion rather than a question, and Gudemann et al. (arXiv:2308.08020) raise within-practice preference heterogeneity, a different defect.","work":[],"target":"","open":0,"source":"Ross S, Hamilton L, Ryan C, Bond C, \"Who makes prescribing decisions in hospital inpatients? An observational study\", Postgrad Med J 2012;88(1043):507-510, doi:10.1136/postgradmedj-2011-130602 — Conclusions, quoted whole and checked verbatim at abstract level post-batch: \"Further research in a larger sample of hospitals is required to confirm generalisability of the results, and to inform educational interventions to reduce error rates.\" Full text paywalled with no deposited copy: COULD NOT READ (OUP article-abstract page serves the structured abstract; the Aberdeen Pure record offers no manuscript or PDF).","badge":"Needs laboratory work or restricted data","tier":"C (needs prospective multi-site ward observation, or a validated record-review gold standard; no public dataset carries the decider)"},{"id":"OP-UQ-20261022-11","kind":"literature","field":"Other fields","title":"Which GPS ground and on-orbit software models assume that UT1 minus UTC stays under one second, and what does a larger tolerance require of each?","text":"Which GPS ground and on-orbit software models assume that UT1 minus UTC stays under one second, and what does a larger tolerance require of each? THE POSED TASK, in the words it was posed in, is “an engineering assessment of all GPS ground and on-orbit software models that presently assume that UT1 – UTC < 1.0 second.” NARROW THE ROW TO WHAT WAS POSED. This is a GPS provider’s own answer to a question put to GNSS providers, reported by the presenter, and it is CONDITIONAL on the tolerance on the magnitude of UT1−UTC actually being increased: restored from a verb-initial fragment it reads “[a new tolerance would] necessitate an engineering assessment”. So it is not an assertion that the assessment is overdue today, it is not posed in the presenter’s own voice, and it reaches GPS only — no other constellation’s software is in scope. The threshold is quoted exactly as printed: the slide prints no absolute-value bars, and inserting them would insert a mathematical commitment the document does not make. NOT ROUTED, because nobody poses them: (i) the ledger’s own candidate question, a maximum representable magnitude of UT1−UTC across time-handling artifact classes, which was rejected because the named classes carry the integral TAI−UTC offset or UT1−GPST rather than UT1−UTC, so a ceiling on the magnitude of UT1−UTC has no referent for them; (ii) a census of public time-handling code, which would be a different question nobody has asked. THE ONE ARM THAT NEEDS NO ACCESS TO GPS SOFTWARE, and is worth doing first because it would say whether the posed assessment is tractable from outside it: a bounding exercise over the public artifacts that do carry a UT1-referenced quantity, namely the broadcast Earth-rotation parameters of GPS CNAV, BeiDou, QZSS and IRNSS. Their governing ICDs (IS-GPS-200L message type 32 and IS-GPS-800G, BDS-SIS-ICD B-CNAV-1/2/3, IS-QZSS-PNT-004, IRNSS SPS ICD) would give, per constellation, whether the broadcast delta-UT1 is referenced to UTC or to the constellation’s own system time, and its bit count and scale factor. That is a bound on which broadcast fields could saturate, not the software assessment that was posed, and the row should not be read as though it were.","work":[],"target":"","open":0,"source":"POSED, and the posing sentence checked post-batch at first hand by a fresh-context reader: Coleman, Michael J. (Naval Center for Space Technology, U.S. Naval Research Laboratory), “Towards Continuous Universal Time and the Future of the Leap Second”, 64th Civil GPS Service Interface Committee Timing Subcommittee Meeting, convened with ION GNSS+, Monday 16 September 2024, https://www.gps.gov/cgsic/meetings/2024/coleman.pdf (conference presentation, no DOI) — slide 14, first bullet under the heading “GPS”, on a slide headed “Answers from GNSS Providers” and framed by the line “Impacts of a new tolerance”. RECORDED AS A RECONSTRUCTION from two consecutive served fragments rather than seen as one unbroken string, WITH THE JUNCTION VERIFIED rather than inferred: a second, differently prompted fetch was asked which word immediately follows “models” and returned “that”, matching the second fragment’s opening token, and reported the bullet to be a single sentence ending in a period, so two independent reads agree at the cut. UNANSWERED: no slide reports the assessment as carried out, and the ICG’s own recommendation on the UTC tolerance (identifier ICG/REC/2025, “Information on the work related to the UTC (revision of Recommendation 16-B (2016))”, 24 October 2025, https://www.unoosa.org/documents/pdf/icg/2025/ICG-19/ICG-19_WG-D_Recommendation_C_.pdf) asks providers to anticipate the increased UT1−UTC tolerance and to promote research on a possible negative leap second, and asks for no inventory and prints no count — “inventory”, “survey” and “catalogue” appear nowhere in it, though it does print “increased in or before 2035” and “expected at CGPM 2026”. READ-LEVEL RESIDUAL, recorded so a later pass does not repeat the route: the absence check over the deck’s remaining 21 slides was summariser-mediated rather than verbatim. That is enough to show the task unreported, and NOT enough to assert that the GNSS community has done no such assessment; a verbatim read of slides 1-13 and 16-23 is what would close it. LOOKS LIKE AN ANSWER AND IS NOT, checked post-batch: Steigenberger, Montenbruck, Bradke et al., “Evaluation of earth rotation parameters from modernized GNSS navigation messages”, GPS Solutions 26:50 (2022), doi 10.1007/s10291-022-01232-4, evaluates the broadcast Earth-rotation parameters of four constellations to about 0.13 ms against IERS C04 — but it performs no software assessment, and it does not even establish that those fields carry UT1−UTC, because for GPS it records that “∆UT1 = UT1 − UTC has been replaced by ∆UT1GPS = UT1 − GPST” per IS-GPS-200L/705G/800G (2020), GPST being “a continuous time scale” that “avoids potential problems in the vicinity of leap second changes”, and it states that “no details about the origin of the ERP data and the parameterization of the ERP prediction model are provided for BDS, QZSS, and IRNSS”. (Author positions 4-5 of that citation could not be read: the publisher page as served truncates to “et al.” and Crossref rate-limited twice. Not contradicted, not verified.) ALSO NOT AN ANSWER: QZSS self-declares a 64 s DUT1 limit on slide 15 of the same deck, needed to avoid “broadcast message format and ground control algorithm changes”, with “(a value of 1 minute or less might be preferred)” on the same line — a provider’s declared limit on a broadcast quantity, not an assessment of software models.","badge":"Needs laboratory work or restricted data","tier":"C for the posed task (it needs the GPS ground and on-orbit software itself, which is not public, and the assessment is in any case conditional on a tolerance change that the CGPM has not yet fixed — Resolution 4 (2022) decides only that the maximum value of UT1−UTC “will be increased in, or before, 2035” and requests a proposal for a new maximum; the 3,600 s figure is a CGPM-2026 DRAFT resolution, not a decision). The bounding arm over the four ICDs is A: public documents, and the deliverable is a per-constellation table of reference frame, bit count and scale factor."},{"id":"OP-UQ-20261022-17","kind":"literature","field":"Computer science and AI","title":"What is the round-trip failure rate decode(encode(d)) != d of shipped, revision-pinned multilingual tokenizer configurations over a dated real-world document corpus, reported per script and …","text":"What is the round-trip failure rate decode(encode(d)) != d of shipped, revision-pinned multilingual tokenizer configurations over a dated real-world document corpus, reported per script and per orthographic feature, and does it confound published per-language loss? Posed in print as a metric and never evaluated: the computable part is running TokEval's §3.4 Reconstruction Exact Match and CER over a document corpus on at least 6 shipped configs pinned by revision, with the per-script strata TokEval does not take (it stratifies by byte width) and the meaning-changing split it does not define. VERIFICATION NARROWED THIS ROW AND STRENGTHENED IT. Strengthened: TokEval's Tables 2 and 3 were read in full and Reconstruction Exact Match and CER are ABSENT from their 14 and 9 intrinsic metrics - a NOT FOUND in those words, so the paper names the metric and then does not report it among its intrinsic results. Narrowed: the unreadable-table loss is ONE table, not four, because Appendix A.3 says Table 4 “gives an overview of the panel definitions” and Table 5 “specifies all tokenizers”, which are metadata; only Table 10 could carry a printed value. Also open rather than occupied: per-language BPB is computed over 31 languages UNCONDITIONED on round-trip stability, and no benchmark anywhere is restricted to round-trip-stable text. FLAGGED OPEN-ON-TABLE-10: if Table 10 proves to carry an Exact-match or CER column, this question is ASKED AND ANSWERED for TokEval's 39-tokenizer panel and this row must be WITHDRAWN.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261022-17","open":1,"source":"TokEval, arXiv:2608.18062v3 §3.4 “Encoding Fidelity” and Table 1 (Clara Meister, sole author, from front matter). The load-bearing sentence, reconstructed from three consecutive PDF fragments verified at both junctions and corroborated on the HTML route, is “A tokenizer is not necessarily lossless: the round-trip reconstruction x-hat = T-inverse(T(x)) may differ from the original due to Unicode normalization, UNK substitution, or whitespace handling.” It has no scope-limiting opener, its subject is universally quantified, and it ASSERTS the property; it is also the hedged formulation, the paper nowhere stating a bare “tokenizers are lossy”. §3.4 NAMES AND INTERPRETS the two metrics and defers their definition to Table 1, and it names three mechanisms with “or” rather than enumerating a closed set. No printed value of either metric was reachable at any route across four agents; Table 10 is COULD NOT READ after three renderings, and arxiv.org/pdf/...v3 serves the identical 91,211-character text as the HTML and truncates at the same point, so the one untried route of the right kind is the arXiv e-print LaTeX source, arxiv.org/e-print/2608.18062v3, which carries table bodies as markup no converter can truncate. NEAR NEIGHBOUR TO FENCE OFF: TokEval's printed 0.001 against “0.008 or more” are UTF-8 CHARACTER SPLIT RATES, disjoint from round-trip reconstruction in both directions. Corroborating that the premise is in print and unquantified: TokSuite, arXiv:2512.20757 Appendix A, whose glossary partitions whitespace options into lossy and lossless (“Note that this can result in lossy detokenization”) over 14 shipped tokenizers with no fidelity measurement. CAVEAT ON THE KILL'S REACH, recorded because it bears on how much this row is worth: the second adversary's nine sweeps found no cross-field disguise at all, so the rejection rests wholly on this one definitional prior in a single unvenued preprint with no measurement behind the metric.","badge":"Has a part computable from public sources","tier":"A (limbs a and b: public tokenizer configs plus a public corpus, CPU-only, no training); limb (d) nearer B, since it needs a named published per-language loss gap on a re-runnable eval set and no agent verified one printed"},{"id":"OP-UQ-20261022-19","kind":"literature","field":"Computer science and AI","title":"Run the within-item reasoning-budget experiment and report the decomposition: assign the same model-item pairs to different FORCED token budgets, contrast the within-item slope of …","text":"Run the within-item reasoning-budget experiment and report the decomposition: assign the same model-item pairs to different FORCED token budgets, contrast the within-item slope of correctness on log reasoning tokens against the pooled slope on naturally emitted length over the same items, and report the selection share per difficulty stratum and per truncation convention. VERIFICATION RESTATED THIS ROW, and the restatement matters. The word “randomized” is STRUCK from the estimand: Zhou, Ling, Chen, Wang, Fan & Wang 2026 (arXiv:2604.10739v1, §4.1.3) already performs a SATURATED within-item forced-budget design, 32 budget levels crossed with every problem across AIME 2024 and 2025, MATH-500 and GPQA Diamond, and a complete crossing identifies a within-item slope BETTER than randomization, so a row demanding randomization would be asking for a weaker design than the one already run. THREE OF THE FOUR INGREDIENTS ARE ALREADY IN PRINT: that forced-budget grid; the pooled coefficient on naturally emitted length (Su, Healey, Nakov & Cardie 2025, Table 1, -0.1626 to -0.7248 Pearson, unitless, denominator unstated); the within-item curve on naturally emitted length as a PLOT WITH NO NUMBER (Su et al. 2025, Figure 1); and a bin-matched capped-against-natural comparison (Zhou et al. 2026, Table 6, 54.2% natural against 53.8% forced in the 6-8K bin, confounded by difficulty per its Appendix A). WHAT IS MISSING IS ONE REGRESSION AND ONE COMPARISON, in the within-item manipulated-dose form. FIRST CHECK, which may collapse the work: whether Zhou et al. release their per-problem by per-budget correctness grid - if it is public, this drops from “needs a study run” to “needs a re-analysis” and the tier goes to A.","work":[],"target":"","open":0,"source":"arXiv:2606.26502 §4.2, Wang, Han-yu (2026), sole author, no printed affiliation, “Humans Disengage, Reasoning Models Persist: Separating Difficulty Registration from Deliberation Allocation” - “we propose a randomized reasoning-budget experiment” and “We would randomly assign runs of the same model-item pairs to different token budgets”, both verbatim in the paper itself at full text with the grammar intact on both sides of the cut and no scope-setting opener reversing them, plus §5 “would measure”. Unperformed in that paper: no budget condition, cap or truncation anywhere, nominally greedy decoding on reanalysed released data. THE INTAKE'S DESIGNATED NEAREST NEIGHBOUR IS NOW IDENTIFIED AND NARROWS THE REMAINDER WITHOUT REACHING IT: “Reasoning-Aware IRT: Explainable Evaluation of Test-Time Scaling in Reasoning Models”, Chatpatanasiri, Ratthachat (2026), sole author, NeurIPS 2026 poster 139400, OpenReview Szz5xYoydw - an identifier the batch record said did not exist. READ LEVEL ABSTRACT ONLY; paper level COULD NOT READ, with openreview.net/pdf, /attachment, /forum and two api2 routes all failing and no arXiv posting of the title found. It DOES put a reasoning-budget responsiveness slope and an IRT item-difficulty parameter in one likelihood, so nobody may claim that no difficulty-adjusted token relationship has been computed; but its unit is the MODEL not the item, no sentence says the same item appears at two or more budgets, manipulated-against-observed is COULD NOT CHECK, and it DEFINES and ANNOUNCES (“quantified reasoning-token benefits”) rather than printing any slope or variance share, over 42 unnamed models on LiveBench with the compute range nowhere stated. READ Szz5xYoydw AT PAPER LEVEL BEFORE ACTING ON THIS ROW. HU IS SECOND-HAND, NOT A SOURCE: Hu, Y. (2026), PNAS 123(17), e2604554123, DOI 10.1073/pnas.2604554123, is cited by Wang three times and never in a reporting role (“recommends”, “may serve... need not”, “a possibility discussed by”), pnas.org returned client_error on two routes on 2026-10-22, PMC13123912 is unreachable under this environment's rules, and the publication record shows a titled “Reply to Hu” - the signature of a PNAS Letter, which is not the kind of document that could settle whether the experiment was run. Check the vol. 123 no. 17 table of contents for article type first. Before promoting above tier B, also open arXiv:2605.16938 (Hu & Wang 2026, “Effort as Ceiling, Not Dial”) in full: at abstract level it measures trace-length-to-human-RT alignment rather than correctness and prints no slope, but it is the nearest PERFORMED manipulation of an effort setting over fixed items and is one careless step from being conflated with the PNAS citation.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B, and A if Zhou et al.'s per-problem budget grid turns out to be public, since the work is then a re-analysis of released data rather than a study to run"},{"id":"OP-UQ-20261023-08","kind":"literature","field":"Medicine","title":"For a declared multi-analyte set on modern automated clinical-chemistry platforms, how much larger is a laboratory's error rate on proficiency-testing material it knows is being graded than …","text":"For a declared multi-analyte set on modern automated clinical-chemistry platforms, how much larger is a laboratory's error rate on proficiency-testing material it knows is being graded than on the same material submitted blind through the routine patient workflow, and how much of any gap is attributable to differential handling of the PT sample rather than to analytical performance? STATED ON THE POSING PAPERS' OWN TERMS, AND NARROWED TO WHAT IS ACTUALLY OPEN. The question itself is old and was answered QUALITATIVELY 49 years ago: LaMotte LC Jr, Guerrant GO, Lewis DS, Hall CT, “Comparison of Laboratory Performance With Blind and Mail-Distributed Proficiency Testing Samples”, Public Health Reports 1977;92(6):554–560 (PMID 200968) is the candidate's question in its title, read at FULL TEXT at stacks.cdc.gov/view/cdc/65385/cdc_65385_DS1.pdf, and it prints paired declared-versus-blind DETECTION counts per drug in the same laboratories with the blind arm routed through hospitals and methadone centres as ordinary patient specimens (1973 arm: barbiturates 110/110 detected declared against 79 of 110 blind; morphine missed once in 110 against 41 times in 111; methadone missed twice in 110 against 21 times in 106 — the corresponding miss-rate differences of about +28, +36 and +18 percentage points are a READER'S OWN ARITHMETIC on those printed counts, the paper printing no confidence intervals, and its 1975 arm is internally inconsistent and is not leaned on). Its numerator class is MISSED QUALITATIVE DETECTION OPPORTUNITIES, not results falling outside a quantitative acceptability limit, so what it answers is not what is asked here. WHAT IS COMPUTABLE OR EXECUTABLE: nothing from public data. The quantitative single-analyte version exists for ONE analyte in ONE era — Parsons PJ, Reilly AA, Esernio-Jenssen D, “Clinical laboratory evaluation of blood lead proficiency testing: open versus blind”, Clin Chem 2001;47(2):322–330, DOI 10.1093/clinchem/47.2.322, which prints 17.7% against 4.5% with P <0.001 and NO denominators, on a result-level pooled unit rather than a laboratory-level one — and that paper is ABSTRACT-ONLY to every reader who has tried it (eight fetches across four distinct routes, and verified paywalled at the publisher: “You do not currently have access to this article”, the PDF marked “Subscribers Only”), so its signed difference, both arm denominators and its numerator class's exclusions are printed nowhere anyone has reached. FIRST STEP, AND IT IS A LIBRARY STEP RATHER THAN A STUDY: obtain Parsons 2001's Methods and Results tables and answer whether any table prints a per-laboratory signed open-minus-blind difference with its N, whether Methods describe the blind specimens entering the routine patient accessioning workflow indistinguishably or by a separate route, and whether there is a concealment audit or a bias-against-imprecision split. SECOND STEP: open the 1998 own-field review behind PubMed 9448012 at the PUBLISHER (meridian.allenpress.com / archivesofpathology.org — a route no reader has yet attempted; PubMed article pages return CLIENT_ERROR here and PMC is hard-blocked, so the PMID is an identifier to convert and never a route) and read its REFERENCE LIST for the clause “PT materials being treated differently than those from patients”, which is the one document most likely to enumerate any declared-versus-blind study in an analyte other than lead.","work":[],"target":"","open":0,"source":"LaMotte et al. 1977 (full text) answers the question only for qualitative detection and prints no quantitative-acceptability-limit class; Parsons et al. 2001 answers it for ONE analyte and its own closing recommendation that blind PT be used occasionally is unreplicated in any second analyte across four runs' queries; the differential-handling mechanism limb is measured by NO opened source in any of the four runs. Group independence is NOT established: LaMotte 1977 and Boone et al. 1982 (AJPH 72(12):1364–1368, abstract only) share author D.S. Lewis and CDC's laboratory programme, so they are one institutional programme citing its own earlier work.","badge":"Needs laboratory work or restricted data","tier":"C (multi-site, governance-gated, covert submission into live patient workflows; nothing computable from public data — the two first steps above are retrieval, not research)"},{"id":"OP-UQ-20261028-02","kind":"literature","field":"Mathematics","title":"At p = 3, is the reflection-pair conditional law for (Q(sqrt d), Q(sqrt -3d)) over positive fundamental discriminants determined by the 3-RANK alone — i.e. does P(r_3(-3d) = r_3(d)+1 \\| …","text":"At p = 3, is the reflection-pair conditional law for (Q(sqrt d), Q(sqrt -3d)) over positive fundamental discriminants determined by the 3-RANK alone — i.e. does P(r_3(-3d) = r_3(d)+1 \\| Cl_3(Q(sqrt d)) = G) equal 3^-(r_3(G)+1) for every finite abelian 3-group G in the declared rule-generated set — or does it depend on G beyond its rank? NOT OPEN AT RANK GRAIN: Fouvry-Klüners Conjecture 1.1 and eqs. (2)/(5) print the conditional 3^-(r+1), attributed to \"Dutarte 1984, Formula 3, p. 8\", and eq. (11) its aggregate 0.29765117..., computer-tested by Dutarte §4.2 and by Fouvry-Klüners themselves; Belabas, Math. Comp. 73 (2004) 2061-2074, §4.2.3 prints the same law and §5.2 one measured count against it (predicted 6.7, observed 6, at r_3 = 4). Computable part: measure the per-G conditional over fundamental discriminants d <= 10^8-10^9 with confidence intervals and test whether it factors through the rank; separately re-measure the aggregate against 0.29765117..., since Fouvry-Klüners report \"the constants are close, but not too close\". Read Sawin-Wood arXiv:2301.00791v2 §§9, 11-12 FIRST: their Conjecture 1.1's hypotheses are satisfied for K_0 = Q(sqrt -3), Gamma = Z/2, p = 3, and if those sections give the per-G joint law the module-grain part is already conjecturally settled. (Row cells corrected 2026-10-29 per VERIFY-02-e, by the post-batch verification pass.)","work":[],"target":"","open":0,"source":"Fouvry & Klüners, \"On the Spiegelungssatz for the 4-rank\", ANT 4 (2010) no. 5, 493-508: §1 p. 495, after eq. (11), \"But this equality is conjectural for the moment.\"; §3 \"Proofs of our main results\", run-in heading \"The case p=3.\", p. 504, \"Analyzing the proof of Theorem 1.8, we see that everything works for p = 3 as soon as we have a suitable proven version of Conjecture 1.2.\"; Theorem 3.5, p. 505, \"Assume that the following four equations are true\". The paper reaches only 3-ranks and 4-ranks, never group structure.","badge":"Has a part computable from public sources","tier":"A for the aggregate re-measurement; B for the per-G limb, whose novelty is UNVERIFIED pending Sawin-Wood §§9, 11-12","note":"The founding research run has taken this one: 2026-11-24 (aggregate limb only; see research/problems/spiegelung-3rank/)"},{"id":"OP-UQ-20261029-01","kind":"literature","field":"Physics","title":"The origin of the internal microcrack networks in returned carbonaceous asteroid material (Bennu and Ryugu fragments), across the four mechanisms the source names — parent-body …","text":"The origin of the internal microcrack networks in returned carbonaceous asteroid material (Bennu and Ryugu fragments), across the four mechanisms the source names — parent-body fluid-reaction volume change, parent-body impact, on-asteroid thermal fatigue and micrometeoroid impact — rather than the candidate's two. Computable part: crack orientation-tensor and area/number-density statistics from the existing XCT volumes of already-allocated particles, which consume no new sample. The alteration-grade limb is NOT computable from what exists: it needs a per-fragment aqueous-alteration index nobody has defined, and the domain-spacing limb needs a calibrated analogue nobody has shown exists.","work":[],"target":"","open":0,"source":"Ryan, et al. 2026, Nature Communications (DOI 10.1038/s41467-026-68505-1, inferred from the publisher URL slug and not confirmed on a fetched page; PMID 41844589), read as the NTRS 20250010685 accepted manuscript \"with final changes\", not the version of record: the sentence at printed line 430 declares the crack-origin question open in its own opening clause, and lines 442-448 name the four mechanisms as an open-ended set (\"such as\"). Located verbatim by a fresh-context checker at cut points independent of the batch reads (VERIFY-01-a). The companion claim that nobody has MEASURED any of the three estimands is an enumerated absence over three opened documents with 13 unopened titles listed, so it is supported-but-unverified rather than established.","badge":"Crisp, but needs data or tools that are hard to get","tier":"B — the orientation-tensor and crack-density legs are a reanalysis of existing XCT volumes and consume no sample; the alteration-index and domain-spacing legs each need something nobody has built."},{"id":"OP-UQ-20261029-07","kind":"literature","field":"Computer science and AI","title":"Does a sequence model trained on a source of exactly known entropy rate reach that entropy rate as parameters and tokens grow, or settle above it, and is any excess a property of the …","text":"Does a sequence model trained on a source of exactly known entropy rate reach that entropy rate as parameters and tokens grow, or settle above it, and is any excess a property of the architecture class rather than of the source? STATED ON THE POSING PAPERS' OWN TERMS. The one-layer case is CLOSED and the open part is the depth and scale generalisation, which Makkuva et al. pose themselves. Their Theorem 1 gives the global minimum as \"L(theta*) = H(x_{n+1}\\|x_n), the entropy rate of the Markov chain\"; their Figure 2a shows the test loss converging to it; the plateau they report appears only under weight tying and \"Increasing the depth, however, solves the issue\". COMPUTABLE PART, and it is the tractable leg: for small exact-H sources (finite-order Markov chains and probabilistic finite-state automata, H exact by dynamic programming) measure the finite-scale gap KL = H(p,q) - H(p) over a parameter/token ladder for a transformer and for a gated-linear-recurrent/SSM family, and report a fitted asymptote WITH AN INTERVAL against H, plus the interval's sensitivity to the fit form. NOT-COMPUTABLE PART: the theoretical characterisation at higher depths that Makkuva et al. name. TWO WARNINGS, both from documents already opened, which exist so this row is not re-derived from scratch. (1) THE NAIVE FIT IS KNOWN TO FAIL ON THIS FAMILY: Pandey (arXiv:2405.16684) fits exactly the estimator E + A/N^alpha + B/D^beta on five PCFG datasets, N from 4.2M to 1.4B and D from 100K to 100M, and prints E = -0.734, -0.262, -1.446, -1693.171, 1.174 in its Table 2 - and a cross-entropy floor cannot be negative, so the estimator must be re-specified or constrained before any asymptote is claimed. (2) THE FINITE-SCALE QUANTITY IS ALREADY MEASURED and must not be re-presented as new: Borenstein et al. (arXiv:2406.04289) compute it over 2100 random PFSAs for an LSTM and a GPT-2-style transformer. A context length must be declared, because at fixed context even a perfect predictor has floor H_T - H > 0 on a source with memory, and for an ambiguous PCFG the closed-form entropy rule is wrong (H(D) = H(S) + H(D\\|S)), so declare the grammar unambiguous or compute H by inside-outside.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261029-07","open":1,"source":"Makkuva, Bondaschi, Girish, Nagle, Jaggi, Kim & Gastpar, \"Attention with Markov\", arXiv:2402.04161, read at section level by one reader on one route (LATEGATE4-07-2): \"Theoretically characterizing this phenomenon for higher depths is an interesting open direction\". The measurement leg's own gap is declared by Borenstein, Svete, Chan, Valvoda, Nowak, Gastpar, Cotterell & DuSell, arXiv:2406.04289, in its own limitations - \"Our experiments also omit the effect of training dataset size\" - and by Henighan et al., arXiv:2010.14701, which defines the limit and concedes \"we cannot yet obtain a meaningful estimate for the entropy of natural language\". No source any of five readers opened prints a fitted asymptote with an interval against an analytic H.","badge":"Has a part computable from public sources","tier":"A for the finite-scale measurement leg (exact H by dynamic programming, models small enough to train without a cluster); B for the asymptote-with-interval leg, which needs a ladder and a re-specified estimator; B for the theoretical characterisation Makkuva et al. name"},{"id":"OP-UQ-20261029-10","kind":"literature","field":"Computer science and AI","title":"Are non-warmup process executions on JIT-compiling virtual machines largely due to JIT compilation events - that is, to the virtual machine's own profile-guided recompilation - or to …","text":"Are non-warmup process executions on JIT-compiling virtual machines largely due to JIT compilation events - that is, to the virtual machine's own profile-guided recompilation - or to something outside the compiler? STATED ON BARRETT ET AL.'S OWN TERMS: this is their Hypothesis H3 restricted to its JIT disjunct, which they separated and examined on its own (\"we take two VMs and separate out the time taken to perform Garbage Collection (GC) and JIT compilation. These two factors explain only some of the effects we see\") and then declared unsettled, with the scope qualifier they attach to it. WHAT IS ALREADY PARTLY ANSWERED, so that none of it is redone: Barrett et al. give a split correlational result (Figure 7's slowdown at iteration #199 \"correlates with two immediately preceding JIT compilation events\", under their own \"we make no claim that they prove causation\", against Section 5.2's \"in many cases such as Figure 8 neither JIT compilation, nor garbage collection, are sufficient to explain odd behaviours\"); Antoch et al. 2026 dissect one recurrent change with \"No extra dynamic compilation event and no extra garbage collection cycle\" and shift it by a heap-size intervention instead; and Zheng, Bulej & Binder, \"An Empirical Study on Deoptimization in the Graal Compiler\", ECOOP 2017, DOI 10.4230/LIPIcs.ECOOP.2017.30, report scalac averaging \"10 deoptimizations per iteration ... even past the 15th iteration\" while finding the deoptimization policy's effect on the steady-state mean negligible. COMPUTABLE PART, and it is the tractable leg: a day-sized observational re-analysis of Antoch et al.'s released measurement package - per-execution changepoint classification against per-execution compilation and deoptimization event counts, reporting the association and its confidence interval at the execution grain, which no opened source prints. PROPOSED BUT GATED ROUTE: the three-arm interventional design (live recompilation; a per-method plan pinned from iteration 1 with adaptive recompilation disabled; a sham freeze applied only after the pilot's last observed compilation) over a rule-generated subset of Barrett's VM x benchmark matrix at fixed iteration count. THE GATE IS REAL: no current release of any VM in that matrix has been shown to install a recorded per-method plan and then make no further compilation decision - HotSpot's stop-recompiling state is interpreter fallback or repeated deopt logic, the only confirmed instrument is Jikes RVM on a 2007 build, and for the two tracing JITs \"per-method plan\" has no referent. A frozen arm that fails to converge therefore does NOT locate the cause outside the compiler, because deoptimization continues under a freeze and leaves the method interpreted.","work":[{"type":"answer-attempt","what":"attempt an answer","needs":"agent time, open-ended: set a budget","units":1,"done":0}],"target":"A-OPEN-UQ-20261029-10","open":1,"source":"Barrett, Bolz-Tereick, Killick, Mount & Tratt, \"Virtual Machine Warmup Blows Hot and Cold\", OOPSLA 2017, DOI 10.1145/3133876, read in the authors' own LaTeX source (warmup.tex, 108,576 bytes) independently by two readers (LATEGATE4-10-1, LATEGATE4-10-2): Section 5.2, \"The large number of non-warmup cases in our data led us to make the following hypothesis: H3 Non-warmup process executions are largely due to JIT compilation or GC events\", then \"we feel unable to validate or invalidate Hypothesis H3. Whilst some non-warmups are plausibly explained by GC or JIT compilation events, many are not, at least on HotSpot and PyPy\"; Section 9.1.1 names the mechanism, \"VMs have many counters which, when they exceed a certain threshold, cause the VM to change behaviour (e.g. (re)compile code ...)\". Still open in public discourse with the flag-flip intervention performed but uncontrolled: hotspot-dev, May 2016, \"I then tried turning off Tiered Compilation ... and the problem went away\", with a HotSpot developer replying \"A comparison between +TieredCompilation and -TieredCompilation might be very informative\". Antoch et al. 2026 (OOPSLA, DOI 10.1145/3798236 as printed on the document; 10.1145/3839448 in a listing) neither pose nor settle it: its \"a definitive confirmation for a specific workload and platform can only be given by additional experiments\" is an external-validity disclaimer.","badge":"Has a part computable from public sources","tier":"A for the observational re-analysis of Antoch et al.'s released package; B for the three-arm interventional contrast, which is crisp in form but gated on an instrument no current matrix VM is known to have"},{"id":"OP-UQ-20261030-05","kind":"literature","field":"Biology","title":"How much of the cell-to-cell variation in nuclear import rate is attributable to variation in nuclear pore number, and how much to variation in the soluble transport machinery, in MAMMALIAN …","text":"How much of the cell-to-cell variation in nuclear import rate is attributable to variation in nuclear pore number, and how much to variation in the soluble transport machinery, in MAMMALIAN cells — and in yeast, what share does the soluble-factor arm take once it is separated from the residual rather than left inside it? STATED ON THE POSING PAPER'S OWN TERMS, AND NARROWED TO WHAT IS OPEN. The partition is posed, and ONE arm of it is answered, in Durrieu et al., bioRxiv 10.1101/001768 (v1 \"Quantification of nuclear transport in single cells\", posted 2014-01-13; v2 \"Characterization of cell-to-cell variation in nuclear transport rates and identification of its sources\", posted 2022-06-24; published as iScience 2022, doi 10.1016/j.isci.2022.105906). v1 raises the partition in its own words — \"in principle this large variability could be due to significant cell-to-cell differences in the number of nuclear pores or in their permeability\" — and then ATTRIBUTES the correlated arm to shared machinery on a count it borrows rather than makes: \"The number of NPC per cell has been counted by Winey et al -using the same strain and cell cycle position than we used - to be 86 +-16 (CV = 0.19, ten cells)\", against its own measured total \"CV ~= 0.96\", concluding \"This CV is too small to account for the variability we found\". Those three strings are the reader's LABELLED RECONSTRUCTIONS from ordered fetcher segments, not strings any reader saw served whole. The permeability or soluble-machinery arm is discussed and never separated from the residual, so roughly the whole of a CV near 0.96 is left unattributed. THREE LIMITS TRAVEL WITH THIS ROW AND MUST NOT BE DROPPED. (i) The component variance values live in the preprint's Fig. 3B-C, which was rendered to NO reader, so \"the pore-number arm is quantified\" describes what the authors ATTRIBUTE, not a number anybody has seen. (ii) The NPC attribution rests on tagged-nucleoporin fluorescence as an explicitly RELATIVE proxy rather than on counted pores, and the published abstract hedges it and confines it to one cargo class: \"For passive transport, the variability in NPC number might explain most of the variability\". (iii) It is cell-to-cell variation WITHIN one cell type, in isogenic yeast, not a between-cell-type contrast — so this row's yeast limb and its mammalian limb differ in kind, not only in organism. WHAT IS COMPUTABLE OR EXECUTABLE: nothing from public data, and the first step is RETRIEVAL rather than research. (1) Read the iScience version of record, which no reader here has reached (cell.com returns client_error, sciencedirect is robots-closed, PMC and Europe PMC are hard-blocked, and the bioRxiv HTML stops at Materials and Methods for v1 and at Supporting information for v2, so NEITHER version's reference list nor front matter has been read by anyone), and establish whether the published version adds a decomposition v2 does not, and whether its single-cell data are deposited. (2) Establish whether v2's NPC arm is still a borrowed count: v2 drops v1's \"we assume\" and its 86 +-16 error bars, leaving a bare citation, and quantifies GFP-tagged Mlp1, Mlp2 and Nup49 nuclear-envelope fluorescence as an explicitly RELATIVE proxy for pore abundance, so no absolute pore count is measured in either version. (3) The mammalian arm may be an experiment nobody has run, but that is NOT ESTABLISHED. No mammalian variance decomposition of nuclear transport rate surfaced in the sweep, and the reader who ran that sweep logs it INCOMPLETE in its own words — report this as \"not found, search incomplete\", never as \"does not exist\" — with 2 of its 17 searches refused by the turn's budget and several named vocabularies never given a dedicated query. One mammalian paper is named and COULD NOT BE READ at any route: Han et al. 2022, Dev Cell, doi 10.1016/j.devcel.2022.09.017, which that reader calls \"the paper most likely to contain it or something adjacent to it\" (cell.com errored, ScienceDirect is host-closed and was not probed, PMC is hard-blocked). Read that before treating the mammalian arm as open. The experiment itself needs per-cell pore counts and per-cell import rates in the same cells. TWO WARNINGS FROM DOCUMENTS ALREADY OPENED, so that neither is re-derived. (a) DO NOT TAKE THE PER-PORE FLUX FIGURES AS MEASUREMENTS OF A DENOMINATOR: every published absolute per-pore flux a reader could reach is a bulk or patch flux divided by a pore count, and the pore counts differ in kind — Ribbeck and Goerlich 2001 counted an areal density in the very preparation they assayed (\"Counting their number in given areas gave 5.1 +- 0.2 NPCs/um2\") but multiplied it by a surface area modelled by treating nuclei as ellipsoids; Timney et al. took a density from Winey 1997; Yang, Gelles and Musser and Siebrasse and Peters simply assumed 3,000 per nucleus and ~15 per patch. (b) THE SINGLE-MOLECULE LITERATURE DOES NOT SUPPLY THE MISSING NUMBER: it supplies dwell times, efficiencies and event statistics at individual pores, and borrows its flux from bulk work.","work":[],"target":"","open":0,"source":"Durrieu et al. — authors from Crossref's ordered list for the DOI, which the reader believes INCOMPLETE (bioRxiv adds Martin Gollvik) since no reader reached either version's front matter — bioRxiv 10.1101/001768, read at BODY LEVEL on both versions (v1 and v2 full text via bioRxiv; the iScience version of record, doi 10.1016/j.isci.2022.105906, reached by NO route, and neither version's reference list or front matter read by anyone): poses the pore-number-versus-permeability partition in v1 and ATTRIBUTES variance to the pore-number arm on a borrowed count, leaving the permeability arm inside the residual. The absence of a mammalian equivalent is an ENUMERATED ABSENCE from ONE subject-only sweep that its own reader logs as incomplete, not a verified universal, and that reader's words were \"Durrieu et al. is the one I found\". That same sweep found absolute per-pore flux published many times over — but the supports differ in READ LEVEL and in REGIME and must not be cited flat: permeabilised HeLa (Ribbeck and Goerlich 2001, full text; Yang, Gelles and Musser 2004, read from an author-hosted PDF that OpenAlex labels a submitted version, with two figure captions unread), Xenopus oocyte envelopes (Keminer et al. 1999, RECORD ONLY with its denominator unverified — and the one paper that, if it proves a genuine single-pore measurement, would overturn the no-measured-flux finding; Siebrasse and Peters 2002, mostly EXPORT and passive flux rather than signal-mediated import) and live yeast (Timney et al. 2016, PASSIVE diffusion of 27-kD GFP only, reporting no facilitated import flux per NPC; Durrieu et al.). CORRECTION, row cells corrected 2026-10-30 by this batch's own entry audit: the row as first written and committed (ff11f13e) called Durrieu et al. \"a source this rejection did not use\", and that is FALSE — bioRxiv 10.1101/001768 IS UQ-20261030-05's Prior 2 and its nearest prior, used by the rejection in four places. The row rests on the entry's own nearest prior, a weaker provenance than the commit claimed, and that is recorded here so no later reader inherits the error.","badge":"Needs laboratory work or restricted data","tier":"C for the mammalian decomposition, which needs per-cell pore counts and per-cell import rates in the same cells and no public dataset carries both; B for the yeast residual-partition limb IF the iScience version's single-cell data prove deposited, which step (1) settles; the first step itself is retrieval, not research"},{"id":"OP-UQ-20261030-06","kind":"literature","field":"Medicine","title":"Does organ size account for the printed left-right cancer-incidence asymmetry in the BREAST and the OVARY, as it is argued to for the lungs and testes?","text":"Does organ size account for the printed left-right cancer-incidence asymmetry in the BREAST and the OVARY, as it is argued to for the lungs and testes? STATED ON THE POSING PAPER'S OWN TERMS AND NARROWED TO WHAT IS OPEN. Roychoudhuri, Putcha and Moller 2006 reports significant side differences at all five major paired sites (lung IRR 0.87, breast 1.07, testis 0.87, ovary 0.86) and confines its organ-size explanation by its own scope-setting opener to the lungs and testes, quantifying no residual for breast or ovary in anything served. Computable part: assemble the published side-specific mass and volume figures for breast and ovary and ask whether they account for the printed breast and ovary incidence ratios, by the same unlinked two-source arithmetic the 2006 paper used for lung and testis, reporting a residual with an interval rather than a direction. THREE LIMITS TRAVEL WITH THIS ROW. (i) The openness rests on an ABSTRACT-LEVEL read: the paper's Methods, Results and Discussion are paywalled and were not reached by any of five readers over about eighteen fetches (OpenAlex is_oa false and oa_status closed, all four locations pdf_url null; LSHTM Research Online eprint 11810 and KCL Pure hold metadata with no file; rd.springer.com serves the abstract, the section headings and the 20-item reference list only), so whether the 2006 paper itself computes such a residual is UNKNOWN and must be checked against the full text before this row is relied on. Routes still open rather than exhausted: a print or interlibrary copy, scholar.archive.org once its rate limit clears, the publisher PDF. (ii) The size figures DO exist outside that paper, which is what makes the arithmetic constructible: Perven R et al. 2014, \"A Postmortem Study on the Weight of the Human Ovary\", Medicine Today 26(1):12-14, DOI 10.3329/medtoday.v26i1.21304 (right and left ovarian mass at three age bands, p < 0.001, n = 70 bodies and 140 ovaries; its Discussion restates two group-C SDs inconsistently with its own Table II); Ahmed et al. 2011, Bangladesh J Med Sci 10(4), n = 62, which DISAGREES IN SIGN at reproductive age; Pongsatha et al. 2002 (ovarian volumes, right 1.7 +- 0.9 and left 1.8 +- 0.9 cm3, n = 26 of 32); and Scutt 2006, \"Breast asymmetry and predisposition to breast cancer\", which prints a mean left:right breast size ratio of 1.04 (SD 0.18) in its whole sample (cases 1.05, controls 1.03, n = 504). THE INGREDIENTS ARE IN PRINT AND NO SETTLED LEFT-RIGHT CONSTANT EXISTS FOR EITHER ORGAN, and that caveat must travel with them: in the reading reader's own words neither breast figure \"should be quoted as a settled anatomical constant the way the lung's 0.87 is\", and the two breast sources point in OPPOSITE DIRECTIONS with neither dominating - Scutt's 1.04 has the left larger and is a CONE-MODEL mammographic volume rather than a mass, from a screening cohort half of whom developed breast cancer, while Hussain Z et al. 1999, \"Estimation of breast volume and its variation during the menstrual cycle using MRI and stereology\", Br J Radiol 72(855):236-245, DOI 10.1259/bjr.72.855.10396212, PMID 10396212, prints left 561 ml against right 567 ml by MRI stereology in 15 healthy women with \"no significant difference between the mean volume of the left and the right breast (p = 0.294)\", a far better instrument on a sample 34 times smaller (read at ABSTRACT ONLY; the numbers are printed in the abstract itself). The ovary side is no firmer: Perven and Ahmed are two small single-centre Bangladeshi series by overlapping author groups that disagree in sign for reproductive-age women, Perven contradicts itself on one group-C standard deviation, and its postmenopausal absolute weights of about 1 g are flagged by the reader as implausibly low. (iii) The unasked candidate this row came from was REJECTED, and what is routed is only the mass-grain residual, not the candidate's per-side epithelial cell-number estimand, which no opened source has ever used as an exposure.","work":[],"target":"","open":0,"source":"Roychoudhuri R, Putcha V, Moller H 2006, Cancer Causes & Control 17(5):655-662, doi 10.1007/s10552-005-0615-9, PMID 16633912 - asks the five-organ question and confines its size explanation to two of the five; ABSTRACT LEVEL ONLY","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"OP-UQ-20261030-08","kind":"literature","field":"Medicine","title":"Two limbs, both asked in print and both unsettled. (a) RECONCILE A DIRECT CONFLICT ON THE SAME TUMOURS: Lewinsohn et al. 2023 reports 6.35x and 2.83x edge-to-centre birth-rate ratios (Fig. …","text":"Two limbs, both asked in print and both unsettled. (a) RECONCILE A DIRECT CONFLICT ON THE SAME TUMOURS: Lewinsohn et al. 2023 reports 6.35x and 2.83x edge-to-centre birth-rate ratios (Fig. 5d,h) while Angaji et al. 2024 reports that \"the tumour evolved under uniform volume growth; there was no evidence of spatial constraints leading to radially outward growth\" (Discussion), both fitted to the SAME Li et al. 2022 T1/T2 hepatocellular carcinomas, under the names \"boundary-driven versus unrestricted growth\" and \"surface versus volume growth\". Whichever is right, one of two published inferences from one dataset is wrong, and nobody has adjudicated them. (b) THE CROSS-TUMOUR-TYPE HOMOGENEITY LIMB, which Lewinsohn announces in a hedge and which nobody opened performs. THE NEAREST EXISTING INSTRUMENT, new to this record and opened by none of the batch's readers: Fu X et al. 2022, \"Spatial patterns of tumour growth impact clonal diversification in a computational model and the TRACERx Renal study\", Nature Ecology and Evolution, s41559-021-01586-x, full text at https://discovery.ucl.ac.uk/10141320/1/s41559-021-01586-x.pdf - 606 regions from 54 clear-cell renal cell carcinomas with 20 tumours at 10 or more regions, positions as continuous millimetre coordinates, a computed distance-to-margin in millimetres and a normalised radial coordinate d = d1/(d1+d2); Fig. 3e prints P(D <= d) for microdiversity hotspots against surface- and volume-growth models and a null, with the power-law exponent in Figs. 3f-h, and Figs. 4a,d,e print distance-to-margin distributions with a dashed line at 10 mm. That is a third organ with the instrument already built, which makes limb (b) approachable without new tissue. FOUR LIMITS. (i) Angaji et al. 2024 is a REANALYSIS: the 285 samples in one 35 mm planar section are Ling et al.'s, not Angaji's, and only 23 of the 285 carry exome data. (ii) The liver member's margin geometry is UNVERIFIED, which matters because it is the one site anybody claims: a first-hand read found a sample-to-surface distance only INSIDE Angaji's Appendix 2.1 inference algorithm (\"where r is the distance between sl and the tumour surface\", a figure caption, plus two algorithm steps), with no Methods statement that positions were recorded relative to the invasive margin and no printed per-sample margin column, confirmed by a dedicated margin-only second sweep that \"returned only Appendix 2 algorithm lines, not Methods lines\". And Ling et al. 2015 COULD NOT BE READ here - pnas.org refused both ways and PMC is hard-blocked - so the primary sampling geometry is unverified at source; untried routes are core.ac.uk, a PNAS mirror, the CNCB BioProject PRJCA000091, and the paper's Table S8. (ii-b) A CAVEAT ON THE SETTING ITSELF, located first-hand and easy to miss: all three of the Angaji tumours are described as \"well-encapsulated\", which is a weak setting for an invasive-margin question, so the one site the dichotomy has been argued at in kind is encapsulated liver material. (iii) Colorectum does NOT supply a third margin-indexed series: Heide et al. 2022 (EPICC) has 21 to 55 samples per patient but records position only as four peripheral regions on a clock bearing with a qualitative \"close to the tumour edge\". (iv) That Fu et al. 2022 satisfies a three-organ-site generating rule is a cross-reader inference nobody graded against the rule, so treat it as a candidate instrument rather than as an established third site.","work":[],"target":"","open":0,"source":"Lewinsohn MA, Bedford T, Muller NF, Feder AF 2023 and Angaji et al. 2024, which fit opposite growth modes to the same Li et al. 2022 hepatocellular carcinomas and are nowhere reconciled; the cross-type limb is announced by the former and performed by nobody opened","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"OP-UQ-20261030-10","kind":"literature","field":"Medicine","title":"Does the per-crypt mutation burden attributed to the colibactin signatures SBS88 and ID18, measured in normal colonic mucosa, rise with later DECADE OF BIRTH?","text":"Does the per-crypt mutation burden attributed to the colibactin signatures SBS88 and ID18, measured in normal colonic mucosa, rise with later DECADE OF BIRTH? STATED ON THE POSING PAPER'S OWN TERMS AND NARROWED HARD TO WHAT IS LEFT OPEN, because most of the measurement has now been performed. The posing paper asks for the measurement in the tissue and names an AGE-MATCHED case-control design, not a birth-decade axis: \"Future studies should examine the SBS88 and ID18 mutation burdens of normal colorectal crypts from individuals with early-onset colorectal cancer (cases) and age-matched healthy individuals (controls)...\", with the birth-period idea present only as the vaguer \"...genome sequences of appropriately selected colorectal cancers and normal colorectal tissues would inform on this historical flux.\" A dedicated sweep found NO birth vocabulary anywhere in it: \"birth cohort\", \"year of birth\", \"birth year\", \"cohort effect\", \"born\" and \"birth\" are all absent, \"cohort\" occurs six times and is always clinical. PUBLISHED WORK NOT TO REDO: Hiatt et al., medRxiv 2026, has already performed and plotted per-crypt SBS88 and ID18 burden in normal-appearing colonic mucosa taken at colonoscopy - the unit is the individual laser-capture-microdissected crypt with donor as a random effect, 125 crypts from 21 male donors (11 polyp-free, 10 with one or more adenomatous polyps), 116 high-confidence, six anatomical regions, SBS88 and ID18 as the focus - but with AGE as a continuous fixed effect and a NULL headline result on that axis, no birth vocabulary, and no numeric confidence intervals printed per crypt. WHAT IS ACTUALLY OPEN is therefore the birth-decade cross-tabulation alone. TWO ROUTES THAT WOULD MAKE IT A REANALYSIS RATHER THAN A RECRUITMENT STUDY, and would move this row from tier B to tier A if either releases what it needs: Hiatt et al.'s per-crypt supplementary table joined to donors' years of birth, which the preprint does not print; or the Mendeley release of the Lee-Six study carrying signature-level attributions with donor age (that study sampled 2,035 crypts and whole-genome-sequenced 571). TWO WARNINGS ABOUT THAT SECOND ROUTE, both located first-hand. Lee-Six prints no per-crypt attribution confidence: its Fig. 3 marks an \"X0\" bucket for mutations not confidently assignable to any signature, and the 95% confidence intervals it does print are on SBS1 RATE estimates rather than on attribution, so the release may not carry the uncertainty this question asks for. And the reader that opened it warns in terms that \"the paper is frequently cited as having shown an early-life colibactin imprint in normal tissue, and it did not\" - so do not build on the secondary literature's summary of it. NAMED UNOPENED RESIDUE, AND THE FIRST THING TO OPEN: a Nature Genetics 2026 paper from a Japanese group on colibactin whose own title word is \"chronology\", DOI 10.1038/s41588-026-02692-x, read by nobody in either pass, with four enumerated fetchable routes untried - it is the single document most likely to move this question from asked-but-open to answered, and anyone taking this row should settle it first. TWO FURTHER LIMITS. (i) The posing sentence is a verified RECONSTRUCTION, not a raw read: it was assembled from five ordered fragments under a 125-character quoting cap and then re-verified word for word by a separate fetch, which is stronger than the batch had and still not contiguous page text. (ii) Whether a conditional future-work sentence counts as the question having been asked is a judgement and is nobody's reported result; the reader that found it grades the paper as posing the question only \"Partly\".","work":[],"target":"","open":0,"source":"Hiatt et al., medRxiv 2026 (the quantity measured in the right tissue with the right unit, on an AGE axis with a null, and no birth variable anywhere), together with the posing paper's own age-matched future-work sentence - so the tissue-level measurement is done and the birth-decade contrast is not","badge":"Crisp, but needs data or tools that are hard to get","tier":"B"},{"id":"UQ-20261015-04","kind":"new","field":"Other fields","title":"In English Wikipedia, does the hazard of a cited external URL becoming unreachable differ by article topic after conditioning on when the citation was added and on the cited domain's type …","text":"In English Wikipedia, does the hazard of a cited external URL becoming unreachable differ by article topic after conditioning on when the citation was added and on the cited domain's type, and which topics lose live verifiability fastest?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Information science (reference rot)"},{"id":"UQ-20261015-06","kind":"new","field":"Computer science and AI","title":"For dense decoder-only LLMs on a fixed serving engine, with the same numeric format, batch size and forced input/output token counts, does measured GPU board energy per token differ between …","text":"For dense decoder-only LLMs on a fixed serving engine, with the same numeric format, batch size and forced input/output token counts, does measured GPU board energy per token differ between trained weights and shape-identical untrained weights ((b) per-tensor moment-matched Gaussian; (c) the engine's \"dummy\" weights) by more than run-to-run noise, and does any difference sit in prefill, in decode, or in both? [R1, adopted at Gate 1; V0 left \"materially\" undefined, left a gap between its yes and no bars, and admitted MoE routing confounds.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI systems / computer architecture (LLM inference energy)"},{"id":"UQ-20261015-13","kind":"new","field":"Medicine","title":"For new active substances approved by FDA or EMA in a fixed window (e.g. 2010–2018), does the estimated unobserved adverse-event-type count derived from the pooled pre-approval MedDRA …","text":"For new active substances approved by FDA or EMA in a fixed window (e.g. 2010–2018), does the estimated unobserved adverse-event-type count derived from the pooled pre-approval MedDRA preferred-term frequency spectrum (bias-corrected Chao1 minus observed richness; Good-Turing coverage deficit f1/n) predict the number of distinct preferred terms added to the label's adverse-reactions section within five years of approval, with discrimination and calibration beyond a pre-specified baseline of pre-approval patient-years, observed richness, drug class, biologic status and accelerated-approval status; and, secondarily, are label-added terms enriched among terms seen exactly once pre-approval? (R1 adopted at Gate 1; V0 in the record asked for identity prediction and exposure-point extrapolation, both dropped.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine / drug safety, pharmacovigilance, regulatory scienc"},{"id":"UQ-20261015-15","kind":"new","field":"Biology","title":"Restricted to published kinetic measurement pairs on the same enzyme (same organism, same sequence region, same mutational state) and same substrate that differ only in affinity-tag status …","text":"Restricted to published kinetic measurement pairs on the same enzyme (same organism, same sequence region, same mutational state) and same substrate that differ only in affinity-tag status (untagged vs tagged, or N- vs C-terminal) and are condition-matched on temperature, pH, buffer and co-substrate saturation: (a) is the pooled within-pair shift in log10 kcat and log10 KM different from zero and direction-consistent, estimated in a mixed model with tag-type, terminus and laboratory terms; and (b) when a published turnover-number predictor (DLKcat, TurNuP, CatPred or RealKcat) is refitted on re-extracted values with versus without tag/terminus stratification, do held-out error and top-k rankings change beyond resampling noise? [R1, adopted at Gate 1; V0 intake version and the reason for reformulation in the record]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology / enzymology and biochemical data curation"},{"id":"UQ-20261015-16","kind":"new","field":"Other fields","title":"For a closed-loop autonomous inorganic-synthesis campaign whose raw diffraction patterns and per-sample automated decision scores are archived (e.g. A-Lab, Szymanski et al. 2023), taking as …","text":"For a closed-loop autonomous inorganic-synthesis campaign whose raw diffraction patterns and per-sample automated decision scores are archived (e.g. A-Lab, Szymanski et al. 2023), taking as reference standard the majority verdict of >=3 crystallographers who each classify every pattern as target phase present / absent / indeterminate against a pre-specified minor-phase weight-fraction threshold, blinded to the automated verdict, to one another and to the published per-target conclusion — (a) what is the automated-vs-expert-majority disagreement rate, with CI, over *all* attempted targets (not only reported successes), reported against the measured expert-expert agreement (Fleiss kappa / Gwet AC1) on the same patterns as a noise floor; and (b) is the loop's own deployed phase-identification score calibrated against that blinded majority (pre-specified calibration-slope, Brier and AUC bands) well enough for a running campaign to estimate its own false-discovery rate on-line? Scope: phase identification only; novelty adjudication excluded. (R1, the one permitted Gate-1 reformulation; V0 in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"STEM — materials chemistry / autonomous experimentation (sel"},{"id":"UQ-20261015-19","kind":"new","field":"Medicine","title":"In biobanks linking whole-genome/exome data to routine clinical laboratory results (UK Biobank primary-care and hospital extracts, All of Us EHR labs, national lab registries), over a …","text":"In biobanks linking whole-genome/exome data to routine clinical laboratory results (UK Biobank primary-care and hospital extracts, All of Us EHR labs, national lab registries), over a pre-registered analyte set fixed by a published feasibility census of resolvable assay/platform metadata: (a) do coding variants in the gene encoding the measured analyte (single-variant plus epitope-agnostic gene-based burden) associate with the immunoassay-reported clinical value, adjusted for a trans PGS, ancestry, age, sex, assay era and site, and replicate in a second biobank; (b) where two or more platforms are recorded, is there a variant-by-platform interaction; (c) in people measured for the same analyte by both immunoassay and a variant-agnostic orthogonal method (LC-MS/MS on peptides not spanning the variant site, or an activity assay), does the genotype effect fall inside a pre-specified equivalence band (assay-bias prediction) or persist outside it (proteoform-physiology prediction); and (d) for each surviving effect, what is the rate of clinical decision-threshold crossings per 100,000 tests among tested carriers, with CIs, and does carriers' downstream care differ? Pre-specified third outcome: if the census finds too few analytes with usable platform metadata, the reportable answer is the bounded feasibility result plus (a) and (d), with (b) declared not estimable.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — laboratory medicine / clinical chemistry and in-v"},{"id":"UQ-20261015-22","kind":"new","field":"Medicine","title":"Within openly documented platforms only (PK-Sim/OSP, published system-parameter compilations, EMA/FDA submission annexes; proprietary libraries out of scope, the coverage gap itself …","text":"Within openly documented platforms only (PK-Sim/OSP, published system-parameter compilations, EMA/FDA submission annexes; proprietary libraries out of scope, the coverage gap itself reportable), for a pre-specified list of PBPK *system* parameters (MPPGL, CPPGL, hepatocellularity per gram liver, hepatic/renal blood-flow fractions of cardiac output, organ volumes, and the Rodgers–Rowland / Poulin–Theriault tissue-composition inputs): (a) under a pre-registered rule for \"mutually independent primary human measurement\" (distinct subject sample AND assay AND laboratory, with a stated adjudication procedure), how many independent primary human sources, pooled subject N, year range and demographic/procurement composition underlie each default value and each default uncertainty distribution, and what is the shared-source incidence matrix across the parameter set (which parameter pairs descend wholly or partly from the same subject series)? (b) For five decision-bearing published PBPK analyses reproducible in an open platform, does Monte Carlo propagation under provenance-corrected uncertainty — each parameter's uncertainty-on-the-mean rescaled to its effective independent-source count plus the shared-source correlation from (a), population variability left at platform defaults — move the decision metric across a boundary fixed in advance (predicted victim AUC ratio leaving 80–125% or crossing the ICH M12 no-effect boundary; paediatric predicted exposure leaving the adult exposure-matching band)?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine / clinical pharmacology (PBPK, model-informed drug"},{"id":"UQ-20261016-02","kind":"new","field":"Medicine","title":"Treating each of K commercial interaction compendia (Lexicomp, Micromedex, First Databank) as a classifier whose severity label is the configuration surface for EHR alert firing, on a …","text":"Treating each of K commercial interaction compendia (Lexicomp, Micromedex, First Databank) as a classifier whose severity label is the configuration surface for EHR alert firing, on a pre-specified sample of interaction pairs stratified by severity class and over-sampling pairs the compendia grade discordantly, every pair estimated in two or more linked databases under one pre-registered design family (active-comparator new-user cohort, plus SCCS where its assumptions hold), with the estimand harm attributable to the combination rather than to either drug alone and a commensurable pre-specified primary outcome (ADR-coded or all-cause hospitalisation, or death, within 90 days of co-exposure initiation), and pairs failing pre-specified identifiability diagnostics reported as a named \"unidentifiable\" stratum rather than dropped: (a) what is the distribution of pair-level attributable risk within each compendium's severity class, and what share of between-pair variance in measured harm does class membership explain; (b) does severity class rank pairs by measured harm better than chance, against a pre-specified minimum, and equally across the K compendia; (c) in real alert logs, holding sensitivity for total measured harm fixed, what alert volume fires under compendium-derived versus outcome-derived classes, as a reclassification table? (This is R1, the single Gate 1 reformulation; V0 left the estimand, the commensuration rule and the disposition of unidentifiable pairs undefined. Full V0/R1 text: batches/2026-10-16-0033/UQ-20261016-02-record.md)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — clinical informatics / clinical decision support"},{"id":"UQ-20261016-06","kind":"new","field":"Computer science and AI","title":"On long-horizon agentic benchmarks run with greedy decoding, recorded-and-replayed tool responses, fixed seeds and a fixed harness, (i) how large is the residual run-to-run variance in task …","text":"On long-horizon agentic benchmarks run with greedy decoding, recorded-and-replayed tool responses, fixed seeds and a fixed harness, (i) how large is the residual run-to-run variance in task success attributable to batch-composition-dependent floating-point nondeterminism in the serving stack — measured as the gap between replicate variance under default kernels with batch composition deliberately varied and replicate variance under batch-invariant kernels — and (ii) is the default-kernel mean success rate equal to the mean over pinned numeric paths, or systematically lower, with any gap scaling in rollout horizon? (Gate 1 reformulation of the Gate 0 original, which asked for numerics' \"share\" of variance; that share is 1 by construction once all other sources are pinned, so the estimand was degenerate. Original recorded in batches/2026-10-16-0233/UQ-20261016-06-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI — inference systems / evaluation methodology (AI architec"},{"id":"UQ-20261016-07","kind":"new","field":"Medicine","title":"In a paired report–image corpus with intact patient/study series order (e.g. MIMIC-CXR), restricted to carry-forward-eligible assertions (a positive assertion of finding class F in …","text":"In a paired report–image corpus with intact patient/study series order (e.g. MIMIC-CXR), restricted to carry-forward-eligible assertions (a positive assertion of finding class F in follow-up report R_t where F was also positively asserted in the immediately preceding report R_{t-1}, and F is adjudicable from a single image; pure change-descriptors such as \"stable\"/\"improving\"/\"resolved\" excluded from the numerator and reported separately): (a) what fraction of such assertions does a blinded multi-reader panel (>=3 readers, current image alone, no report, no prior) call absent, after subtracting a reader-noise floor estimated on positively-asserted findings in index exams under identical blinding; (b) is the report-label false-positive rate higher on follow-up than on index exams at equal case-mix for the same finding classes, and is the excess concentrated in high-resolution-rate classes (consolidation, effusion, oedema, pneumothorax, line/tube position) rather than persistent structural classes (cardiomegaly, chronic fibrosis); and (c) how much does measured performance of a standard classifier trained and evaluated on report-derived labels change when follow-up exams are excluded or panel-re-labelled, versus a matched random equal-sized exclusion?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — radiology reporting quality/QA, clinical informat"},{"id":"UQ-20261016-12","kind":"new","field":"Computer science and AI","title":"For the N most-downloaded open-weight instruct repositories on the Hugging Face hub, (a) what fraction carry at least one commit landing after the last weight-shard commit that modifies a …","text":"For the N most-downloaded open-weight instruct repositories on the Hugging Face hub, (a) what fraction carry at least one commit landing after the last weight-shard commit that modifies a behaviour-determining non-weight artifact (`tokenizer*`, `*template*`/`chat_template`, `generation_config.json`, `special_tokens_map.json`, `added_tokens.json`), where \"behaviour-determining\" is decided empirically by rendering a fixed prompt set under both revisions and diffing token-ID sequences and stop/EOS configuration rather than by diffing files; and (b) with weight files verified identical and harness, seeds, runtime and decoding pinned, what is the paired score-delta distribution between the earliest and latest such revision on a suite spanning format-sensitive and format-robust tasks, measured against a same-revision repeat-run noise floor obtained in the same study, and what fraction of those deltas exceed both that floor and the empirical distribution of improvement margins claimed as evidence in a sampled set of model-comparison papers?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI — evaluation methodology"},{"id":"UQ-20261016-16","kind":"new","field":"Medicine","title":"In a multi-site EHR corpus spanning roughly 1995–2025, restricted to episodes of documented infection (coded syndrome plus culture- or NAAT-confirmed pathogen) and taking as the episode …","text":"In a multi-site EHR corpus spanning roughly 1995–2025, restricted to episodes of documented infection (coded syndrome plus culture- or NAAT-confirmed pathogen) and taking as the episode peak the maximum temperature recorded strictly before the first antipyretic administration timestamp, with the contemporaneous reference being the afebrile temperature distribution of non-infected patients in the same health system, device class and time-of-day window: within strata of age band, syndrome, pathogen, severity-at-presentation and device class, is the calendar-year slope of (episode peak − contemporaneous afebrile reference) zero, and how does it compare with the calendar-year slope of the afebrile reference itself? (Additive primary scale, mandatory bounded/multiplicative sensitivity analysis; any pre-1950 archival arm reported only as a bias-bounded estimate.) One Gate 1 reformulation used; intaked version and rationale in the record.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — physiology / infectious disease / clinical thermo"},{"id":"UQ-20261016-18","kind":"new","field":"Medicine","title":"In adult ICU patients on continuous norepinephrine, with device-integrated pump-rate logs and timestamped pressure at >=4x the hypothesised cadence frequency: (a) does the pump-rate series …","text":"In adult ICU patients on continuous norepinephrine, with device-integrated pump-rate logs and timestamped pressure at >=4x the hypothesised cadence frequency: (a) does the pump-rate series carry excess band-limited power, and the dose-to-MAP cross-spectrum coherence with loop-consistent phase, in a narrow band centred on the unit's documented assessment/charting cadence (1 h => 2.8e-4 Hz; 2 h => 1.4e-4 Hz), against a pre-specified surrogate noise floor (phase-randomised, block-shuffled) and control band; (b) does that centre frequency move with cadence across units or exogenous protocol/staffing changes; (c) does cadence-band dose-oscillation amplitude predict organ dysfunction (delta SOFA components, new RRT) net of time-weighted mean dose, severity, phenotype and procedure-driven periodicity? [V2, the single permitted Gate 1 reformulation; V1 said \"limit-cycle oscillation tracking charting cadence\" — see record.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — critical care, patient safety, clinical informati"},{"id":"UQ-20261016-21","kind":"new","field":"Medicine","title":"For a pre-specified frame of completed multicentre RCTs whose primary outcome is generated or titrated by a software-containing measurement device named by model: (i) in what fraction can a …","text":"For a pre-specified frame of completed multicentre RCTs whose primary outcome is generated or titrated by a software-containing measurement device named by model: (i) in what fraction can a firmware or calibration-algorithm revision dated inside the enrolment window be established from a pre-specified ordered route list (manufacturer release notes/service bulletins, FDA recall/MAUDE, EU field-safety notices, direct manufacturer enquiry, the trial report), reported explicitly as a lower bound; and (ii) in the subset with a datable revision and recoverable IPD, what is the treatment-effect-by-device-era interaction on the trial's own effect scale, benchmarked against the trial's own pre-specified MCID (fallback: half-width of its primary 95% CI), with era/calendar-time collinearity reported so non-estimable trials are counted as non-estimable rather than null?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — randomised-trial methodology"},{"id":"UQ-20261016-23","kind":"new","field":"Medicine","title":"For a pre-specified list of the drugs most often prescribed to lactating women, (A) what fraction have published human milk concentration-time data satisfying each design criterion a …","text":"For a pre-specified list of the drugs most often prescribed to lactating women, (A) what fraction have published human milk concentration-time data satisfying each design criterion a veterinary regulator imposes on a milk residue-depletion study (milked-subject count, number and spacing of post-dose time points, terminal-phase coverage, assay LOQ relative to the limit, licensed-regimen dosing); and (B) for the qualifying subset, what breastfeeding-interruption intervals follow when the veterinary tolerance-limit rule (upper one-sided 95/95) is applied against each of a pre-stated set of candidate infant-exposure limits, and how does that distribution compare, drug by drug, with the interruption advice mothers are given now?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — clinical pharmacology / lactation pharmacotherapy"},{"id":"UQ-20261016-24","kind":"new","field":"Other fields","title":"For a pre-specified corpus of papers reporting results executed on named cloud-accessible quantum processors, and a pre-specified per-device figure of merit F built from archived …","text":"For a pre-specified corpus of papers reporting results executed on named cloud-accessible quantum processors, and a pre-specified per-device figure of merit F built from archived calibration fields and stable across a declared comparability window (same hardware revision, same recalibration methodology): (a) what fraction of published results can be located in time to the archive's granularity, and what fraction of those fall inside a window the archive still covers; and (b) among the locatable-and-covered results, is the percentile rank of F at the reported execution window — within a pre-specified symmetric comparison window (e.g. ±30 days, truncated at revision boundaries) — uniform on [0,1] or shifted towards favourable ranks, and by how much, reported both as a shift in expected device quality and, on a pre-declared monotone subset of result types, as the implied shift in the headline number? (Gate 1 reformulation, the single permitted one; the as-intaken version is in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"STEM — quantum computing (cloud-accessible superconducting/t"},{"id":"UQ-20261016-27","kind":"new","field":"Medicine","title":"Among recipients of a single vaccine product in a registry recording manufacturing lot number and linked to outcome ascertainment, fitting outcome (infection, or severe outcome) on …","text":"Among recipients of a single vaccine product in a registry recording manufacturing lot number and linked to outcome ascertainment, fitting outcome (infection, or severe outcome) on lot-level random intercepts nested within shipment block and conditioning on vaccination date, time since dose, dose number, geography and recipient characteristics: is the between-lot SD of the lot random effect distinguishable from zero, and what one-sided upper bound do the data place on it? (Gate 1 version B; the as-intaken version A and the reformulation record are in the record file.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — vaccinology"},{"id":"UQ-20261016-28","kind":"new","field":"Medicine","title":"For a pre-specified frame of multi-site laboratory records (>=K sites, >=15 years, analytes restricted in advance to those with documented commutability across the method generations …","text":"For a pre-specified frame of multi-site laboratory records (>=K sites, >=15 years, analytes restricted in advance to those with documented commutability across the method generations present) and a pre-registered list of published secular-trend claims resting on them: (a) what breakpoints and offsets does a pairwise-reference procedure transplanted from climate-station homogenization (contemporaneous co-catchment sites as reference series; SNHT / pairwise comparison / ACMANT-style detection on differenced series) detect per site-analyte; (b) against independently retrieved analyzer/method/calibrator change logs, what are the sensitivity and specificity of detection and the agreement of estimated with documented offsets; and (c) on the homogenized record, what fraction of each published trend's magnitude is attributable to breakpoint offsets, and how many trends retain sign and significance? [R1, the one Gate 1 reformulation, adopted. V0 as intaken, and the three under-specifications R1 fixed, are in the record.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — laboratory medicine, clinical epidemiology"},{"id":"UQ-20261016-30","kind":"new","field":"Computer science and AI","title":"For training runs whose restart history and data pipeline are auditable (open runs, or a deliberately instrumented replication under shipped recovery semantics), taking the run's *claimed* …","text":"For training runs whose restart history and data pipeline are auditable (open runs, or a deliberately instrumented replication under shipped recovery semantics), taking the run's *claimed* training sequence as an artifact (a manifest with an order, or, where order is only procedural, the sequence (seed, loader version, world size) would have produced absent faults): (a) what is the divergence between claimed and realized token sequence induced by dataloader-state recovery at each restart and in total, reported both as a multiset divergence (tokens/documents never consumed; consumed more times than claimed, as a fraction of nominal) and as an ordering divergence (displacement from claimed position); and (b) under a pre-registered test with a stated detection floor, does per-document memorization or trajectory-specific influence differ for documents adjacent to a restart boundary relative to matched documents away from any boundary?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI — large-scale training systems and training-data provenan"},{"id":"UQ-20261016-31","kind":"new","field":"Other fields","title":"For a cohort of individually identified LEO satellites (NORAD IDs) of one hardware model, observed with one instrument in fixed bands and a fixed beam/elevation configuration, with multiple …","text":"For a cohort of individually identified LEO satellites (NORAD IDs) of one hardware model, observed with one instrument in fixed bands and a fixed beam/elevation configuration, with multiple passes per satellite per epoch and >=2 epochs >=6 months apart: (a) how does the variance of per-satellite band-limited radiated power (normalised to 1000 km) partition into pass-within-epoch, epoch-within-satellite, between-satellite-within-model and between-model components; (b) with model fixed, does epoch-level per-satellite emission change with on-orbit age; (c) what fraction of previously-detected satellites still in orbit fall below a stated, sensitivity-matched per-satellite upper limit at the later epoch? (Gate 1 reformulation; intake version asked whether UEMR is a fixed property of a hardware model or varies over a satellite's operational life, biasing snapshot-based aggregate forecasts.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"STEM — radio astronomy / spectrum engineering and satellite"},{"id":"UQ-20261016-32","kind":"new","field":"Medicine","title":"For organ sites whose T category turns on knife-edge size thresholds, what is the distribution of specimen-handling-induced change in measured tumour size (in situ -> fresh gross -> …","text":"For organ sites whose T category turns on knife-edge size thresholds, what is the distribution of specimen-handling-induced change in measured tumour size (in situ -> fresh gross -> post-fixation gross -> histologic), and what fraction of staged patients lie within that distribution's width of a threshold, so that their stage, adjuvant therapy and trial eligibility are set by specimen handling rather than by the tumour?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — surgical pathology, cancer staging. Adjacent: reg"},{"id":"UQ-20261016-33","kind":"new","field":"Medicine","title":"Computed with safeguards material-balance discipline — an inventory-difference statistic, a propagated measurement-and-documentation variance, and a stated detection probability at a stated …","text":"Computed with safeguards material-balance discipline — an inventory-difference statistic, a propagated measurement-and-documentation variance, and a stated detection probability at a stated false-alarm rate — what is the smallest sustained controlled-substance diversion rate a hospital's reconciliation and analytics can detect per dispensing unit per month, and how does that minimum detectable rate compare with quantities in adjudicated diversion cases? Question (Gate 1 reformulation, one reformulation used, both versions on the record): For a named ADC-served unit and drug-formulation class, with ID = (beginning inventory + receipts) − (recorded administered + documented waste + returns + ending inventory) and a propagated sigma_ID in which every term is declared either a measured variance or an interval bound (witnessed waste unmeasured by construction), what is the smallest sustained monthly removal M at which each of three named tests — (a) the unit's current discrepancy-review practice, (b) a reproducible vendor alarm rule, (c) a safeguards-style sequential test on cumulative ID (CUMUF/Page-type) — attains Pd = 95% at Pfa = 1 per unit-year; and how does M compare with per-month rates reconstructed from adjudicated cases? (Reformulated because the intake version fixed no test, no (Pd, Pfa) pair and no units.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — hospital pharmacy / patient safety / drug-diversi"},{"id":"UQ-20261016-34","kind":"new","field":"Biology","title":"In a dense whole-brain connectome whose two hemispheres were reconstructed from a single image volume, how large must a difference in a cell-type-to-cell-type connection weight be before it …","text":"In a dense whole-brain connectome whose two hemispheres were reconstructed from a single image volume, how large must a difference in a cell-type-to-cell-type connection weight be before it exceeds the reconstruction-and-proofreading noise floor — i.e. what is the detection limit for any connectome-to-connectome comparison, measured by independent re-reconstruction of the same volume? (Gate 1 reformulation used for Gates 2–3 demotes \"independent re-reconstruction\" from the question to one candidate estimator, and adds stratification by edge weight, cell type, neurite length and proofreading effort; both versions in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — connectomics / systems neuroscience (EM reconstruc"},{"id":"UQ-20261016-35","kind":"new","field":"Medicine","title":"In a biobank operating a deletion-on-withdrawal mandate, using dated withdrawal-ID tranches and a pre-fixed panel of headline estimates (k GWAS associations, k' hazard ratios, one polygenic …","text":"In a biobank operating a deletion-on-withdrawal mandate, using dated withdrawal-ID tranches and a pre-fixed panel of headline estimates (k GWAS associations, k' hazard ratios, one polygenic score's discrimination): (a) what is the pre-deletion standardised difference between withdrawn and retained participants on the exposures, covariates and outcomes the cohort is actually used to study; (b) how far does each headline estimate move when recomputed on the frame immediately before and immediately after each tranche, against its Monte Carlo error and pre-declared decision boundaries; and (c) does the cumulative movement accumulate monotonically in the direction (a) predicts — systematic drift rather than noise?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine/biology — biobank and cohort research methods"},{"id":"UQ-20261016-36","kind":"new","field":"Medicine","title":"Within a single ART or cell-therapy facility, among cryostored units of one specimen class frozen under one protocol, what share of the residual between-unit variance in a per-unit …","text":"Within a single ART or cell-therapy facility, among cryostored units of one specimen class frozen under one protocol, what share of the residual between-unit variance in a per-unit post-thaw endpoint is attributable to the unit's static storage coordinate (vessel, canister, rack, height), estimated with cohort, calendar date, donor and operator adjusted and with re-racking and tank-transfer events as the identifying variation, and what is the effect size per 10 °C of a pre-specified time-weighted static storage temperature derived from the facility's own thermal map? (Gate 1 reformulation; it is the version judged here.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine/biology — cryobiology, ART laboratories, biobanking"},{"id":"UQ-20261016-41","kind":"new","field":"Other fields","title":"For the elementary functions in deployed math libraries, how do the rate of last-bit disagreement between implementations and the distribution of error against the correctly-rounded result …","text":"For the elementary functions in deployed math libraries, how do the rate of last-bit disagreement between implementations and the distribution of error against the correctly-rounded result change when measured over the argument distribution that real scientific and machine-learning codes actually generate, rather than over the uniform-over-representable-domain weighting on which published worst-case error figures rest? (Gate 1 reformulation used, one only, recorded in full in batches/2026-10-16-1633/UQ-20261016-41-record.md: fixed precision, RNE, implementation set I = {glibc, LLVM-libc, a vendor CPU library, a GPU device library + its fast-math variant}, F = {exp, log, pow, sin, cos, tan, erf, exp2, rsqrt, tanh}; per observed argument x the predicates D(x) = \"members of I disagree\", E(x) = \"member differs from the MPFR correctly-rounded value\", with ulp error e(x); report Pr[D(x)] and the distribution of e(x) under (i) usage weighting from an instrumented corpus and (ii) uniform weighting over the representable domain, plus the per-function ratio.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"STEM — numerical computing / scientific software (computer a"},{"id":"UQ-20261016-43","kind":"new","field":"Other fields","title":"Treating each published electrocatalyst durability run as a right-censored lifetime observation whose censoring time is the author's chosen test duration: what lifetime distribution does …","text":"Treating each published electrocatalyst durability run as a right-censored lifetime observation whose censoring time is the author's chosen test duration: what lifetime distribution does the published corpus actually support, and is the censoring informative — does the stopping time depend on the degradation the experimenter was watching? (Gate 1 reformulation, the graded version, adds a pre-specified frame (OER, pH class, current-density band, cell type), one pre-fixed failure definition (overpotential at fixed current exceeds its run-initial value by a pre-fixed Delta), and four limbs: (i) stopping-time distribution and mass on convention values (10/12/24/100/500/1000 h); (ii) Kaplan-Meier plus Weibull/lognormal fit with pre-registered sensitivity over the comparability restriction and a stated publication-selection model; (iii) does end-of-run degradation rate predict stopping time given design covariates, which under non-informative censoring it should not; (iv) test duration needed to separate two catalysts at 80% power, two-sided alpha 0.05. Both versions are in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"STEM — electrocatalysis / energy materials (OER durability r"},{"id":"UQ-20261016-46","kind":"new","field":"Computer science and AI","title":"For corpora distributed as URL manifests (LAION-2B-en/Re-LAION, DataComp CommonPool, YFCC100M, OBELICS), pinned to an archived manifest revision and a resolution date T: (i) is the …","text":"For corpora distributed as URL manifests (LAION-2B-en/Re-LAION, DataComp CommonPool, YFCC100M, OBELICS), pinned to an archived manifest revision and a resolution date T: (i) is the still-retrievable subset a selective rather than random thinning, selective on covariates the manifest itself records (registrable domain, TLD, language, caption length, licence, aesthetic and NSFW deciles, dimensions, shard), measured as per-covariate retention ratios with CIs plus out-of-fold AUC and calibration of a retention model against a pre-registered null band on N = 200k rows per corpus; and (ii) at fixed compute, does a model trained on the retrievable-at-T subset differ from one trained on a size-matched random subsample of the same archived manifest by more than a ±2 SD within-arm seed-to-seed equivalence band on the dataset's own suite (k ≥ 5 seeds per arm)?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — data layer (web-scale pretraining corpora,"},{"id":"UQ-20261016-49","kind":"new","field":"Computer science and AI","title":"For matched pretraining runs differing only in numeric format (BF16 control vs MXFP8 vs MXFP4/NVFP4; identical data, order, seed, token count), what is the slope beta of the per-stratum …","text":"For matched pretraining runs differing only in numeric format (BF16 control vs MXFP8 vs MXFP4/NVFP4; identical data, order, seed, token count), what is the slope beta of the per-stratum held-out loss gap to the BF16 control against log training-corpus frequency, and does that slope (i) differ from zero against a seed-variance baseline and (ii) track the per-block flush-to-zero rate of gradient entries resolved by the same strata? (Gate 1 reformulation, one allowed; Version A — \"is the low-precision loss penalty uniform across the data distribution or does it grow with rarity?\" — recorded in batches/2026-10-16-1833/UQ-20261016-49-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — numeric formats and large-scale pretrainin"},{"id":"UQ-20261016-51","kind":"new","field":"Computer science and AI","title":"For a pre-registered item frame and an open-data model whose pretraining corpus is indexed (OLMo/Dolma, Pythia/Pile, LLM360, DCLM), retrieving every corpus occurrence of an item stem above …","text":"For a pre-registered item frame and an open-data model whose pretraining corpus is indexed (OLMo/Dolma, Pythia/Pile, LLM360, DCLM), retrieving every corpus occurrence of an item stem above a fixed fuzzy-match threshold and classifying each into {states gold, states non-gold, states no answer, gold itself erroneous}: (a) what are the occurrence- and item-weighted class fractions, with CIs and a reported extractor precision/recall on a human-adjudicated sample; and (b) conditioning on difficulty estimated from zero-occurrence models, is accuracy on non-gold-dominated items (>=50% of answer-stating occurrences disagree with gold) below accuracy on matched occurrence-free items — i.e. is the contamination correction to a reported score signed, and how many points does it move when non-gold-dominated items are removed rather than retained? (Gate 1 version 2; intake version 1 in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — evaluation methodology and the training-da"},{"id":"UQ-20261016-52","kind":"new","field":"Computer science and AI","title":"Across the released \"base\" checkpoints that research uses as the pre-post-training control, how much post-training-like behaviour (refusal on harmful requests, chat-template preference …","text":"Across the released \"base\" checkpoints that research uses as the pre-post-training control, how much post-training-like behaviour (refusal on harmful requests, chat-template preference, zero-shot instruction following, assistant-persona self-reference) is already present relative to a documented pre-instruction-era reference base, how far does that presence track instruction-formatted content in the pretraining corpus where the corpus is open, and by how much does it bias published estimates of what post-training adds?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — pretraining/post-training pipeline design"},{"id":"UQ-20261016-54","kind":"new","field":"Computer science and AI","title":"For a pre-specified set of open-weight releases R, over the population A(R) of publicly available derivative artifacts whose lineage includes R — partitioned in advance into (i) format-only …","text":"For a pre-specified set of open-weight releases R, over the population A(R) of publicly available derivative artifacts whose lineage includes R — partitioned in advance into (i) format-only requantizations, (ii) fine-tunes, (iii) merges, (iv) behaviour-modification derivatives (abliterated/\"uncensored\"), with a declared rule for multi-class artifacts and for merges with parents outside R — and with the PRIMARY weight being each artifact's cumulative hub download count at a pinned census date (per-file where exposed, per-repo with a stated within-repo allocation rule otherwise): how large is D = E_w[m(a)] − m(ref), where m is each of a pre-specified capability suite and a pre-specified refusal/jailbreak-resistance measure, m(ref) is measured on the pinned reference weights through the SAME inference engine and precision path as the class being compared (format-matched control), each component of D is judged against a pre-declared decision margin, and D is reported with CIs, a stated census coverage error, sensitivity across >=3 alternative weightings, and a variance decomposition into between-class and within-class (uploader) components?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — open-weight derivative ecosystem (third-pa"},{"id":"UQ-20261016-55","kind":"new","field":"Computer science and AI","title":"Over a pre-specified window and a pre-registered set of enumerable public records of removal demands against LLM training data (Lumen DMCA notices naming dataset/model hosts, court-ordered …","text":"Over a pre-specified window and a pre-registered set of enumerable public records of removal demands against LLM training data (Lumen DMCA notices naming dataset/model hosts, court-ordered and voluntary dataset withdrawals, documented consent withdrawals, DOI-resolvable retractions), what is the joint distribution of (legal basis, demands per unit time, retrievable artifacts per demand, and — for the subset resolvable to a named open corpus such as Dolma or peS2o — document count, token share and co-document entanglement with retained material), with the unobserved confidential fraction explicitly bounded; and do the published forget sets of TOFU, MUSE, WMDP and DUSK fall inside or outside the support of that distribution?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — training-data governance (LLM machine unle"},{"id":"UQ-20261016-58","kind":"new","field":"Biology","title":"In a defined frame of RNA submissions carrying a recorded integrity score and a documented accept/reject/re-extract decision, with each source taxon assigned a 28S hidden-break status, (a) …","text":"In a defined frame of RNA submissions carrying a recorded integrity score and a documented accept/reject/re-extract decision, with each source taxon assigned a 28S hidden-break status, (a) what is the break-free vs break-bearing difference in recorded integrity score and in per-sample rejection and re-extraction rate, adjusted for preservation route, tissue, protocol, input mass and body size with denominators stated; and (b) in matched RNA from one break-bearing and one break-free species degraded in the same graded series, what is the mapping RIN_break(d) → RIN_free(d) at equal true degradation d measured independently (DV200, spike-in fragment length, library 3' bias), and therefore what numeric correction does a RIN ≥ 7-type gate require in a break-bearing taxon? (c, secondary/exploratory) After conditioning on research effort, body size, collection difficulty and preservation, is break status associated with whether a taxon has any transcriptome at all? (Gate 1 reformulation; one reformulation used, for well-posedness only. Gate 0 intake wording and the full limb specification are in batches/2026-10-16-2155/UQ-20261016-58-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — invertebrate molecular biology / RNA quality metro"},{"id":"UQ-20261016-64","kind":"new","field":"Medicine","title":"In a corpus of ambulatory encounters retaining both the verbatim transcript and the final signed note, with a pre-specified set of index diagnoses/outcomes established independently from …","text":"In a corpus of ambulatory encounters retaining both the verbatim transcript and the final signed note, with a pre-specified set of index diagnoses/outcomes established independently from the EHR at a pre-specified lag L (adjudication rule fixed in advance; the index encounter's own coding excluded), what is the difference in out-of-sample discrimination, calibration and decision-curve net benefit between a transcript-input predictor and a note-input predictor — under (a) length- and summary-matched input controls, (b) a human-transcribed reference subsample isolating ASR loss from documentation loss, and (c) pre-specified subgroup-by-artefact interactions (interpreter use, limited language proficiency, dysarthria/cognitive impairment, speech rate, accent/first-language group) — and does the difference persist on pre-ambient, human-written notes from recorded encounters?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — clinical documentation and diagnostic error"},{"id":"UQ-20261016-65","kind":"new","field":"Medicine","title":"In sites whose viewer/PACS logs emit series-level display events, and under a provenance map and series taxonomy declared before any data are pulled: (i) what proportion of *diagnostically …","text":"In sites whose viewer/PACS logs emit series-level display events, and under a provenance map and series taxonomy declared before any data are pulled: (i) what proportion of *diagnostically intended* series (excluding localizers/scouts, dose reports, failed/repeated acquisitions and auto-generated reformats/parameter maps) carry no display event attributable to any reader in the interpreting chain between study-available-in-PACS and report signature, counting a displayed derived series as coverage of each source series the provenance map says it encodes; and (ii) in a stratified sample of those never-displayed series, what is the per-series rate of actionable findings under a pre-specified actionability taxonomy, read by >=2 blinded readers with adjudication and the original report withheld? (Gate 1 reformulation; intake version — \"what fraction of diagnostically intended archived series are never displayed to any interpreting reader before signature, and what is the blinded re-read yield in those series?\" — recorded in the record, substantively identical.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — radiology care delivery, diagnostic quality and s"},{"id":"UQ-20261017-06","kind":"new","field":"Computer science and AI","title":"Train k >= 3 sparse-MoE language models under one recipe differing only in seed (router/expert init and data order), at a scale at which OLMoE's router-saturation curve reproduces; with a …","text":"Train k >= 3 sparse-MoE language models under one recipe differing only in seed (router/expert init and data order), at a scale at which OLMoE's router-saturation curve reproduces; with a pre-declared probe corpus, layer set, top-k and expert matching rule M (Hungarian matching on per-expert activation profiles), measure with CIs (i) A_cross, cross-run agreement of the token-to-expert partition after M (ARI/NMI) at the 1%-of-pretraining checkpoint and at the end; (ii) S, the same agreement within a run between its 1% and final checkpoints (OLMoE's ~60% top-8 saturation); (iii) A_0, nulls from expert label permutation and from matching one run to an unrelated run; and (iv) the share of between-seed variance in terminal held-out loss and downstream scores predictable from 1%-checkpoint routing statistics — reporting A_cross - A_0 and A_cross/S per layer and the sensitivity of all four to the load-balancing auxiliary-loss weight. (Gate 1 version A, as intaken, recorded not graded: is the token-to-expert partition that saturates in the first ~1% of MoE pretraining canonical — reproduced up to expert relabelling by independent runs of one recipe — or an arbitrary early lottery, and does it predict the run's terminal quality? One reformulation used; Gate 1 budget spent.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — sparse mixture-of-experts LM design and pr"},{"id":"UQ-20261017-07","kind":"new","field":"Computer science and AI","title":"For ONE fixed Common Crawl source pool re-filtered at a matched keep rate by T >= 2 quality classifiers whose positive labels come from different annotator (\"teacher\") models — chosen …","text":"For ONE fixed Common Crawl source pool re-filtered at a matched keep rate by T >= 2 quality classifiers whose positive labels come from different annotator (\"teacher\") models — chosen capability-matched across families so teacher IDENTITY is not confounded with teacher CAPABILITY — crossed with A >= 3 pre-declared architecture/recipe arms at matched FLOPs and matched token budget, with S >= 2 seeds per cell and one evaluation suite declared before any run: (i) how large is the teacher x arm interaction variance component relative to the within-cell seed variance (ratio with CI), and (ii) how many of the A(A-1)/2 pairwise architecture contrasts reverse SIGN between teachers at a pre-registered minimum effect size?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — pretraining data layer (model-based qualit"},{"id":"UQ-20261017-08","kind":"new","field":"Computer science and AI","title":"For open model releases that ship optimizer state alongside weights, how much more does an adversary learn about the final phase of training — document membership, presence of a data …","text":"For open model releases that ship optimizer state alongside weights, how much more does an adversary learn about the final phase of training — document membership, presence of a data source, or reconstructable content — from (weights + Adam moment tensors) than from weights alone at matched attack strength, and what fraction of major open-weight releases ship that state?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — open-release artifact engineering and the"},{"id":"UQ-20261017-11","kind":"new","field":"Biology","title":"In reference genome assemblies produced by the standard Earth BioGenome-era pipeline, what fraction of genuine recent gene duplicates is removed by the haplotypic-duplication purging step …","text":"In reference genome assemblies produced by the standard Earth BioGenome-era pipeline, what fraction of genuine recent gene duplicates is removed by the haplotypic-duplication purging step (purge_dups / purge_haplotigs plus manual curation), and by how much does that removal shift published estimates of gene-family expansion and contraction rates?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — comparative/evolutionary genomics"},{"id":"UQ-20261017-15","kind":"new","field":"Biology","title":"For each assay class in current interactome-mapping use (HT-Y2H, AP-MS of lysates, binary recomposition assays of the MAPPIT/LUMIER/PCA type, proximity labelling, in-cell crosslinking MS) …","text":"For each assay class in current interactome-mapping use (HT-Y2H, AP-MS of lysates, binary recomposition assays of the MAPPIT/LUMIER/PCA type, proximity labelling, in-cell crosslinking MS), taking each assay's working concentration regime and detection limit from published protocols as bounded intervals and taking detectability to mean that a law-of-mass-action equilibrium complex fraction exceeds the assay's LOD at that working concentration: (a) where does each assay's detectability boundary lie in the (Kd, intracellular concentration) plane for one declared cell type; (b) what is the union of those regions, and hence the complement invisible to the whole toolkit; (c) what share of pairs falls in the complement under two declared denominators — a reference set with independently measured affinities, and all pairs among proteins expressed in that cell type weighted by a stated Kd prior; and (d) restated under the window, what does at least one published \"fraction of the interactome mapped\" figure become? [v1 at intake was the same question without a declared denominator or detectability criterion; v2 above is the one permitted Gate 1 reformulation and is the version graded.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — interactomics / systems biology (PPI mapping, inte"},{"id":"UQ-20261017-17","kind":"new","field":"Medicine","title":"In adult inpatients with an acute pain episode scored serially for >= 48 h, with a then-test at a randomly assigned day and a pre-registered external anchor set (opioid-equivalent …","text":"In adult inpatients with an acute pain episode scored serially for >= 48 h, with a then-test at a randomly assigned day and a pre-registered external anchor set (opioid-equivalent consumption/PCA demands, QST, a functional milestone such as time to first ambulation): (a) does a longitudinal measurement-invariance model of the serial 0–10 NRS, anchors as reference, reject intercept (scalar) invariance across the episode; (b) under a pre-declared operationalisation of recalibration (then-test difference, or fitted intercept drift), what fraction of the mean observed within-episode NRS reduction is recalibration rather than change in anchored pain; and (c) at the NRS <= 4 titration target and the 2-point/30% MCID, what misclassification rate of \"target attained\"/\"MCID achieved\" does that recalibration induce? Both estimates must be shown not to be recall error, via randomised then-test timing and an anchor-only refit. (V2; the single Gate 1 reformulation, spent to pin population, operationalisation, anchor set and estimands. V1 and full text in batches/2026-10-17-0742/UQ-20261017-17-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — acute pain management and analgesic-trial methodo"},{"id":"UQ-20261017-19","kind":"new","field":"Medicine","title":"Using package- and lot-level provenance recorded by serialized drug track-and-trace (GS1/EPCIS under US DSCSA or EU FMD), for a product set pre-specified before any data pull: (i) in a real …","text":"Using package- and lot-level provenance recorded by serialized drug track-and-trace (GS1/EPCIS under US DSCSA or EU FMD), for a product set pre-specified before any data pull: (i) in a real serialization-to-dispensing linkage held by one large dispenser, wholesaler or regulator, what are the distributions of manufacture-to-dispensing interval, remaining labelled shelf life at dispensing, and custody-path length / cumulative per-step dwell time, by product and dispensing channel (retail, mail-order, hospital, 340B/specialty), and how much of their variance is within product-and-manufacturer rather than between (a pre-registered within-product ICC declared in advance as the gate on limbs ii-iii); (ii) for products passing that gate, does measured potency (assay % label claim and dissolution, USP/Ph.Eur. monograph as reference) in retrieved patient-held or returned units vary with remaining shelf life and cumulative dwell time, with batch identity as a random effect so the estimand is the within-batch provenance slope rather than between-batch quality; (iii) for any product with a named, routinely measured potency-sensitive endpoint pre-specified at protocol stage, what is the cohort association between those provenance variables and that endpoint, channel and patient mix adjusted? (Gate 1 V2; the single permitted reformulation is spent. V1 and what the reformulation changed: see batches/2026-10-17-0742/UQ-20261017-19-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — clinical pharmacology, pharmaceutical supply/heal"},{"id":"UQ-20261017-21","kind":"new","field":"Other fields","title":"Over a pre-declared window and airspace set, with exposure defined from non-GNSS-derived evidence only (regulator bulletins, NOTAMs, spectrum-monitoring records) and each aircraft report …","text":"Over a pre-declared window and airspace set, with exposure defined from non-GNSS-derived evidence only (regulator bulletins, NOTAMs, spectrum-monitoring records) and each aircraft report joined to an archived NWP observation-feedback record, do aircraft-derived meteorological observations (AMDAR and Mode-S EHS/ADS-B-derived u/v wind and temperature) differ between exposed and matched unexposed airspace in (i) observation-minus-background bias and standard deviation, stratified by aircraft navigation configuration, (ii) the rate of gross positional misassignment detectable as kinematic inconsistency between successive reports from one airframe, and (iii) the fraction of such reports that survives operational quality control into the analysis and the analysis increments they produce — or are the exposed and unexposed departure statistics indistinguishable inside a pre-declared equivalence band with no excess QC rejection rate? (V2; reformulated once at Gate 1 from a V1 that left exposure definition, comparator and null unspecified. V1 and the diff are in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — atmospheric science / NWP data assimilation"},{"id":"UQ-20261017-22","kind":"new","field":"Other fields","title":"For long-run Li-ion cell-cycling experiments — (a) PROSPECTIVE: under a design in which cells are rotated between channels on a pre-declared schedule (>=3 channels x >=3 cells per group …","text":"For long-run Li-ion cell-cycling experiments — (a) PROSPECTIVE: under a design in which cells are rotated between channels on a pre-declared schedule (>=3 channels x >=3 cells per group, sham rotations, traceable per-channel current/voltage/temperature calibration, logged chamber position), what are the cell, channel and cell-by-channel variance components, with intervals, of per-interval degradation rate and of pre-declared trajectory features, and what cycle-life variance share do they imply under the declared trajectory model; and (b) ARCHIVAL: in archived protocol-ranking experiments where the same physical channels hosted cells on different protocols across rounds (Severson 2019; Attia 2020), what is the channel-level variance when channel enters as a random effect alongside protocol, and does the top-k protocol set change under channel-shrunken protocol estimates? (Graded version is V2; V1 — \"what share of between-cell variance in cycle life is attributable to the channel\" — failed Gate 1 as unidentifiable in the designs it criticises. Both versions in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — electrochemical engineering"},{"id":"UQ-20261017-24","kind":"new","field":"Other fields","title":"Now that spacecraft-reentry metal input to the stratosphere is comparable to or larger than the cosmic-dust input for several elements, by how much does it bias the tracer-based constraints …","text":"Now that spacecraft-reentry metal input to the stratosphere is comparable to or larger than the cosmic-dust input for several elements, by how much does it bias the tracer-based constraints on cosmic-dust influx to Earth, and can meteoric and spacecraft material still be separated per particle and per snow/ice layer well enough to preserve those constraints as reentry mass grows? (Gate 1 reformulation V2, used for Gates 2-4: for each published method that constrains extraterrestrial mass influx from metal abundances — per-particle stratospheric aerosol, mesospheric metal layers, meteoric smoke, polar snow/firn/ice — state its tracer elements and compute (a) the fractional bias implied by the published per-element anthropogenic reentry flux and its uncertainty and (b) the reentry mass or date at which that bias exceeds the method's own quoted precision, with the meteoric/spacecraft separation rule declared in advance and its misattribution rate estimated on pre-space-age archived material.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — atmospheric chemistry and aerosol science"},{"id":"UQ-20261017-25","kind":"new","field":"Other fields","title":"Over a pre-declared frame of (site, issued value, issue date) triples from dated standards and published quantile maps — 50-year wind speeds, 100-year flood discharges, 100-year significant …","text":"Over a pre-declared frame of (site, issued value, issue date) triples from dated standards and published quantile maps — 50-year wind speeds, 100-year flood discharges, 100-year significant wave heights — restricted to issued values carrying an explicit nominal annual exceedance probability p, what is the pooled realized exceedance rate in the post-issue site-years, estimated under a declared spatial-dependence model and reported as a ratio to nominal p; and under a pre-declared decomposition, how much of any departure is attributable to (a) issue-era estimator bias (issue-era estimator vs modern estimator on the identical issue-era record), (b) parameter and record-length uncertainty at issue, and (c) post-issue trend?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — hydrology, meteorology, coastal and wind engine"},{"id":"UQ-20261017-27","kind":"new","field":"Computer science and AI","title":"For one pretraining recipe at a scale where several parallelism configurations are feasible, run a crossed design of C ≥ 3 configurations × S ≥ 3 seeds — holding global batch size …","text":"For one pretraining recipe at a scale where several parallelism configurations are feasible, run a crossed design of C ≥ 3 configurations × S ≥ 3 seeds — holding global batch size, global-batch membership and order, seed, numeric formats and token count fixed, and restricting C in advance to a matchable set of changes that provably do not alter the mathematical objective (excluding e.g. Megatron-LM #7464 vocab-parallel label smoothing on the local vocabulary, #1754 non-divisible vocab) — what are the between-configuration and between-seed variance components with confidence intervals, what interval covers σ²_config/σ²_seed for (a) held-out loss at fixed token count and (b) each member of a pre-registered downstream metric set, is the upper confidence limit of that ratio below 1 (the invariance verdict), and which axis (rank count, micro-batch count, sharding style) carries any excess?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — distributed training systems (secondary: s"},{"id":"UQ-20261017-28","kind":"new","field":"Computer science and AI","title":"At a fixed pretraining checkpoint theta, what is the design effect deff(theta, B) of a stack's shipped batch formation (shard assignment + shuffle buffer + rank sharding) — the variance of …","text":"At a fixed pretraining checkpoint theta, what is the design effect deff(theta, B) of a stack's shipped batch formation (shard assignment + shuffle buffer + rank sharding) — the variance of the minibatch gradient's scalar projection on the full-corpus gradient direction under the real sampling scheme divided by the same variance under i.i.d.-with-replacement resampling of the same corpus at identical nominal B, the two arms differing in nothing but design — what within-batch gradient ICC rho does it imply under deff = 1 + (m-1)rho for a declared m, does multiplying tr(Sigma) by deff move B_simple = tr(Sigma)/|G|^2 and the critical-batch-size prescription past a pre-registered band (NULL <= 1.1 / MODEST 1.1-2 / MATERIAL > 2), and is the correction stable across checkpoints and shuffle-buffer sizes? (V1, the single permitted Gate 1 reformulation; V0 and the reason for reformulating are in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — training systems and optimization (batch f"},{"id":"UQ-20261017-29","kind":"new","field":"Computer science and AI","title":"On a dated, pinned frame F of the public post-training data pool (enumerable snapshot of public instruction-tuning and preference datasets, inclusion rule declared before any pull), under a …","text":"On a dated, pinned frame F of the public post-training data pool (enumerable snapshot of public instruction-tuning and preference datasets, inclusion rule declared before any pull), under a pre-declared normalization N to a canonical (instruction, [context], response-or-preference-pair) form and a pre-declared ladder of three near-duplicate thresholds t1<t2<t3: (a) what is the example-level cross-dataset duplication graph — pairwise overlap shares, the pool's de-duplicated count |F|_dedup(t) as a curve in t, and the distribution over distinct examples of how many named datasets each appears in; (b) for at least three published mixtures, what are the realized distinct-example proportions of the components against the declared weights under a pre-declared multi-component attribution rule (fractional / first-wins / set-of-origins), with component rank order before and after; and (c) what is the retrievability-adjusted version of (a), stating the unretrievable share of F at the snapshot date?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — post-training data layer (curation, mixtur"},{"id":"UQ-20261017-30","kind":"new","field":"Computer science and AI","title":"In published LLM and agent evaluations that release per-item logs with error fields, on a pre-declared frame: (a) what share of the nominal denominator carries a harness-side failure, by …","text":"In published LLM and agent evaluations that release per-item logs with error fields, on a pre-declared frame: (a) what share of the nominal denominator carries a harness-side failure, by class, under a hand-validated taxonomy; (b) holding the estimand fixed, how far apart are the drop-the-item (per-protocol) and score-as-failure (ITT) estimators in score, rank correlation and counted pairwise rank reversals; (c) separately, as a distinct estimand, what does retry-to-completion give; (d) does harness-failure probability correlate with model identity (making the drop estimator biased, not merely lossy); and (e) what fraction of published evaluations state their convention at all? (Gate 1 reformulation, the one permitted; Gate 0 original in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — evaluation methodology (harness and leader"},{"id":"UQ-20261017-31","kind":"new","field":"Biology","title":"V1 (scored as canonical, retained per Gate 1): in droplet scRNA-seq of dissociated tissue, is the ambient-RNA (\"soup\") profile a quantitative record of the cell types destroyed during …","text":"V1 (scored as canonical, retained per Gate 1): in droplet scRNA-seq of dissociated tissue, is the ambient-RNA (\"soup\") profile a quantitative record of the cell types destroyed during dissociation — does deconvolving it against a pre-declared reference recover the identity and relative mass of the lost populations well enough to correct that run's cell-type composition estimate? V2 (Gate 1 reformulation, well-posedness only): for a tissue block split across modalities, does the soup profile — deconvolved against a pre-declared signature matrix, converted from RNA mass to cell counts via independently measured per-type RNA content and per-type degradation — give a per-type missing-count estimate whose calibration slope on the (in-situ minus droplet) deficit is distinguishable from 0 and from 1, with interval?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — single-cell genomics methodology, tissue-atlas com"},{"id":"UQ-20261017-33","kind":"new","field":"Biology","title":"Over a pre-declared frame of published non-clinical biological analyses that re-run end-to-end from archived code and data and reproduce their published headline numbers to a declared …","text":"Over a pre-declared frame of published non-clinical biological analyses that re-run end-to-end from archived code and data and reproduce their published headline numbers to a declared tolerance, and over a pre-registered frequency-weighted catalogue of single-point faults, what is the per-fault probability that an injected fault is both SILENT (the run completes and trips no hard failure, flagged threshold or visibly anomalous sanity plot among those the pipeline itself emits, judged by a blinded rubric with inter-rater agreement reported) and CONSEQUENTIAL (the paper's pre-extracted headline claim changes past that paper's own stated threshold), and does that probability partition more into analysis class than into the authors' software practices? (Gate 1 reformulation V1 adopted; V0 intake text and the full V1 wording in batches/2026-10-17-1421/UQ-20261017-33-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — computational-biology research methods / metascien"},{"id":"UQ-20261017-34","kind":"new","field":"Biology","title":"Across genetically identical, identically reared individuals, is the absolute cell number of an organ regulated as a total — with compensatory negative covariance between its constituent …","text":"Across genetically identical, identically reared individuals, is the absolute cell number of an organ regulated as a total — with compensatory negative covariance between its constituent regions or cell types — or are the parts regulated independently, so that the variance of the total is the sum of the parts' variances? (Gate 1 reformulation, the version graded; one reformulation used: in a cohort of n isogenic, identically reared individuals, with a nested technical-replicate layer and a pre-declared partition, does the across-individual covariance matrix of absolute regional cell counts carry negative off-diagonal structure large enough to put Var(total) significantly below SUM Var(parts) once the technical component is subtracted, and does the sign replicate in a second line and under both an atlas and a registration-free marker partition? The reformulation drops the intake's \"regulated as a total\" mechanism claim, which the intake itself conceded is not identifiable from covariance.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — developmental biology / organ-size control"},{"id":"UQ-20261017-35","kind":"new","field":"Biology","title":"Over a frame of research-biology protocol parameters enumerated BEFORE any tracing by a pre-registered rule (frequency of exact numeric-plus-unit strings in a dated protocols.io + …","text":"Over a frame of research-biology protocol parameters enumerated BEFORE any tracing by a pre-registered rule (frequency of exact numeric-plus-unit strings in a dated protocols.io + Methods-section corpus, with physically or instrumentally forced parameters flagged in advance), and traced under a written, dual-coded rubric to exactly one of four states — (i) primary optimisation found, conditions still current; (ii) primary optimisation found, conditions superseded; (iii) traced to a non-evidential source (vendor document, textbook, earlier protocol); (iv) chain unresolvable — (a) what are those four rates, with intervals, a coder-agreement statistic, and forced parameters reported separately; and (b) for a random subsample in state (ii), does re-running the original optimisation under current conditions move the optimum beyond a pre-declared margin? (V1 as intaken, one permitted Gate 1 reformulation: \"For the canonical default parameters of experimental biology protocols, what fraction can be traced to a primary determination that actually optimised a measurable endpoint, and among those, what fraction were optimised under conditions no longer in use?\" V1 left denominator, coding rule and limb (b) implicit.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — experimental laboratory methods"},{"id":"UQ-20261017-36","kind":"new","field":"Medicine","title":"In an inhaled-corticosteroid dose-ranging design in which nominal dose is randomised and per-patient delivered lung dose is independently estimated (recorded inhalation profiles plus …","text":"In an inhaled-corticosteroid dose-ranging design in which nominal dose is randomised and per-patient delivered lung dose is independently estimated (recorded inhalation profiles plus device-specific in-vitro flow-to-dose characterisation, with actuation counts for adherence), how much do the fitted dose–response curve's maximum slope and ED50 differ when the exposure variable is estimated delivered dose rather than assigned nominal dose; and of the gap, what share is attributable to (a) dispersion of the nominal→delivered multiplier, (b) pharmacodynamic saturation, and (c) between-patient heterogeneity in corticosteroid responsiveness — with a stated test of whether the delivery multiplier is independent of baseline severity? (V2, the Gate 1 reformulation; the one permitted reformulation was used. V1 asked whether the reported ICS flatness is \"partly an artefact\" of randomising label dose, and was re-specified because it named classical measurement error as the mechanism, which is wrong under randomisation.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — respiratory medicine / clinical pharmacology of i"},{"id":"UQ-20261017-40","kind":"new","field":"Medicine","title":"On one case set reviewed twice under a pre-registered protocol, what is the signed difference in the classified diagnostic-error rate between (A) standard unblinded chart review with the …","text":"On one case set reviewed twice under a pre-registered protocol, what is the signed difference in the classified diagnostic-error rate between (A) standard unblinded chart review with the full record available, and (B) review in which the index encounter's own diagnostic assertions and every downstream repetition traceable to them are redacted, while subsequently generated findings, test results and diagnoses not traceable to the index assertion are retained — reported with its uncertainty, a measured index of blinding success, and the same contrast computed on a subset whose diagnosis is anchored to an index-independent reference (autopsy, mandated external re-adjudication, or a registry with independent ascertainment) to fix the bias direction?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — diagnostic safety"},{"id":"UQ-20261017-41","kind":"new","field":"Other fields","title":"For a pre-declared frame of NORAD-identified Starlink satellites labelled by launch group, design generation and target shell, under a failure proxy declared before any data pull (decay …","text":"For a pre-declared frame of NORAD-identified Starlink satellites labelled by launch group, design generation and target shell, under a failure proxy declared before any data pull (decay onset within T days of launch with no operator decommissioning signature) plus two pre-declared alternative proxies as a sensitivity axis, fit a discrete-time competing-risks hazard model with a launch-group random intercept, conditioning on each unit's cumulative geomagnetic exposure over its own orbit-raising window, its target shell and its design generation: what is the interval estimate of the between-launch-group intercept variance tau^2 (and the implied median hazard ratio between two randomly drawn launch groups), and what does propagating that tau^2 through a standard debris-environment / PMD-compliance model do to the predicted distribution — not merely the mean — of non-disposed objects? (V2, the one permitted Gate 1 reformulation, scored as canonical; V1 named the manufacturing lot, which no public record identifies. Both in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — aerospace / space-systems engineering"},{"id":"UQ-20261017-42","kind":"new","field":"Other fields","title":"For a declared, version-pinned high-throughput DFT attempt frame (every structure submitted, with per-task terminal states retained, or a frame re-run from scratch) and a pre-registered …","text":"For a declared, version-pinned high-throughput DFT attempt frame (every structure submitted, with per-task terminal states retained, or a frame re-run from scratch) and a pre-registered recovery protocol applied to a random sample of terminally failed tasks (escalated mixing/preconditioner, smearing, k-grid, initial magnetic configuration, symmetry, step limits) plus cross-code recovery: (a) conditional on composition and structure under a pre-declared featurization, is the distribution of formation energy, band gap, magnetic moment/ordering and dynamical stability the same among recovered-failed as among retained entries (the ignorability null), and what is the hand-adjudicated split of failures into numerics-driven and physics-driven (the latter a declared outcome category, not a missing value); and (b) when the recovered set is reinstated, by how much does at least one published downstream statistic move — a screening hit rate, the count of entries on or within X meV/atom of the convex hull, or the held-out error of a universal MLIP retrained with the recovered entries included? (V2; V1 and the Gate 1 reformulation rationale in batches/2026-10-17-1823/UQ-20261017-42-record.md)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — computational materials science / electronic-st"},{"id":"UQ-20261017-44","kind":"new","field":"Other fields","title":"Over a pre-declared frame of theorem-level declarations in human-authored machine-checked libraries and blueprint projects that carry an attribution to a specific published theorem (library …","text":"Over a pre-declared frame of theorem-level declarations in human-authored machine-checked libraries and blueprint projects that carry an attribution to a specific published theorem (library source attributions, docstring references, blueprint-to-paper node maps), and comparing each against the published statement read under a declared blanket-hypothesis rule (standing conventions such as \"all rings here are commutative Noetherian\" count as stated hypotheses of the published theorem): what is the signed rate of logical-strength divergence — the share formalized strictly weaker (hypotheses dropped or generalized, or a strictly weaker axiom set) against the share formalized strictly stronger (the formalization had to assume more) — decomposed into mechanically detected divergences (axiom set via `#print axioms`, declared-but-unused binders, typeclass weakening relative to the published hypothesis) and hand-adjudicated substantive ones on a random sample with inter-adjudicator agreement; and does the weaker-side rate vary with the source's publication age, length or subfield?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — mathematics: formalization, metamathematics, ma"},{"id":"UQ-20261017-48","kind":"new","field":"Computer science and AI","title":"For one named, dated model x benchmark score panel published as the basis of a capability trend series — the Epoch Capabilities Index, 179 models x 38 benchmarks, 1324 observed scores — …","text":"For one named, dated model x benchmark score panel published as the basis of a capability trend series — the Epoch Capabilities Index, 179 models x 38 benchmarks, 1324 observed scores — with each cell's observation indicator R_ij and each benchmark's first/last-report dates recovered: (0) does a unidimensional latent model fit the panel well enough for \"the trend\" to be a defined object (pre-step, not assumed); (a) does Pr(R_ij = 1) depend on fitted latent capability theta_i and fitted benchmark difficulty b_j after conditioning on the pre-declared covariate set Z = {model release date, developer, open/closed weights, benchmark age, benchmark licence/access, citation count, evaluation cost}; (b) under a pre-declared family of MNAR departures — a shared-parameter selection model with sensitivity parameter gamma on theta, and a pattern-mixture alternative indexed by the mean shift delta between observed and unobserved cells — what are the SIGNED changes in the fitted theta-vs-date trend's intercept and slope, expressed as a change in the implied doubling time, with Manski-style worst-case bounds; (c) does that change exceed the series' own reported uncertainty? (R1, the one permitted Gate 1 reformulation; V0 as intaken is recorded alongside it in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — evaluation methodology (TARGET field, deci"},{"id":"UQ-20261017-49","kind":"new","field":"Computer science and AI","title":"For each published model-based pretraining quality filter F (FineWeb-Edu educational-value classifier; DCLM fastText; Nemotron-CC ensemble) applied at its shipped threshold to a pinned …","text":"For each published model-based pretraining quality filter F (FineWeb-Edu educational-value classifier; DCLM fastText; Nemotron-CC ensemble) applied at its shipped threshold to a pinned, dated Common Crawl snapshot S, what is the enrichment ratio E(F,S) = [prevalence of machine-generated documents in the kept set] / [prevalence in the source pool], with both prevalences corrected for detector sensitivity and specificity estimated on a hand-labelled, provenance-anchored validation subsample drawn separately from the kept and discarded strata, reported with intervals propagating that correction, across a keep-rate ladder obtained by moving F's own threshold at fixed F and stratified by snapshot date — and is E monotone increasing in stringency? (One permitted Gate 1 reformulation used, for well-posedness only: it added stratum-specific validation sampling, a fixed-filter rather than pipeline-stage ladder, and a documents-vs-tokens unit declaration. Intake version recorded verbatim in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — pretraining data layer (model-based qualit"},{"id":"UQ-20261017-50","kind":"new","field":"Computer science and AI","title":"Restricted to runs declaring clipping of a GLOBAL gradient norm at nominal threshold c (c = 1.0 the index case), with a step CLIPPED when the stack's clip coefficient is < 1: (a) what is …","text":"Restricted to runs declaring clipping of a GLOBAL gradient norm at nominal threshold c (c = 1.0 the index case), with a step CLIPPED when the stack's clip coefficient is < 1: (a) what is the clipped-step fraction as a function of training progress, per run, from released pre-clip gradient-norm series or instrumented reproductions; and (b) under a band pre-declared from seed replicates, are BOTH the clipped-step fraction AND the realized-update deviation (relative L2 and cosine of the applied update from the update that clipping-disabled would have applied, at matched checkpoints) invariant to (i) model scale along a ladder at fixed c and (ii) the parameter grouping over which the stack reduces the norm — and if not, what c'(scale, grouping) reproduces a reference run's two endpoints? (V2; the one permitted Gate 1 reformulation of V1, for well-posedness only — V1 left \"actually active\" and \"same intervention\" undefined and let limb (b) rest on gradient-norm scaling.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — training systems and optimization (pretrai"},{"id":"UQ-20261017-53","kind":"new","field":"Biology","title":"For a pre-declared gene set and a pre-declared isoform-individuation rule (splice-junction-chain identity at a declared 5'/3' tolerance), treating each of >= 2 independent deep long-read …","text":"For a pre-declared gene set and a pre-declared isoform-individuation rule (splice-junction-chain identity at a declared 5'/3' tolerance), treating each of >= 2 independent deep long-read libraries per tissue as an incomplete sample of a gene's distinct spliced-isoform classes: (a) what does a false-positive-aware richness estimator (coverage-based rarefaction/extrapolation, Chao/Good-Turing extended with a contamination term calibrated per read class from spike-ins and technical replicates) give for the number of unobserved REAL isoforms per gene, with intervals; (b) does its prediction of how many new isoforms one further independent library reveals match a held-out library; and (c) is the fitted per-gene asymptote finite and depth-stable across all admissible contamination models, or does no admissible model close the curve — in which case \"isoforms per gene\" is a depth-indexed quantity, not an estimand? (V2; V1 and the Gate 1 reformulation rationale in batches/2026-10-17-2257/UQ-20261017-53-record.md)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — transcriptomics / genome annotation (target field:"},{"id":"UQ-20261017-54","kind":"new","field":"Biology","title":"For macromolecular complexes whose ligand- or nucleotide-bound states are resolvable and countable in situ by cryo-electron tomography, and whose state is a reversible binding equilibrium …","text":"For macromolecular complexes whose ligand- or nucleotide-bound states are resolvable and countable in situ by cryo-electron tomography, and whose state is a reversible binding equilibrium on the timescale of the measurement (driven cycles admitted only with a declared steady-state rather than equilibrium null), does the measured in-cell occupancy of each bound state match the occupancy predicted from in vitro dissociation constants and the measured or bounded intracellular FREE ligand concentration, and what is the sign and magnitude of the signed log-ratio discrepancy across complexes?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — structural cell biology (in-cell cryo-electron tom"},{"id":"UQ-20261017-55","kind":"new","field":"Biology","title":"For K >= 3 cell types pre-declared from tissues whose in vivo temperature is distinctly non-37 °C (at least one cooler and one warmer), in a 2x2 factorial crossing tissue-matched vs 37 °C …","text":"For K >= 3 cell types pre-declared from tissues whose in vivo temperature is distinctly non-37 °C (at least one cooler and one warmer), in a 2x2 factorial crossing tissue-matched vs 37 °C temperature with physioxic vs atmospheric oxygen, with proliferation-rate-matched controls and a distance metric to a freshly isolated in vivo reference profile both declared before any data are taken: what fraction of the baseline in vitro-to-in vivo distance is closed by temperature correction, reported per cell type with confidence intervals alongside the fraction closed by oxygen correction measured on the same scale and in the same experiment, and the temperature x oxygen interaction?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — cell-culture methodology and in vitro model fideli"},{"id":"UQ-20261018-02","kind":"new","field":"Medicine","title":"In a labour-curve dataset with per-examination dilatation records (Consortium on Safe Labor, WHO BOLD, or LaPS), under (i) an error model for digital cervical dilatation estimated from …","text":"In a labour-curve dataset with per-examination dilatation records (Consortium on Safe Labor, WHO BOLD, or LaPS), under (i) an error model for digital cervical dilatation estimated from paired same-time-point measurements — replicate independent examiners primary, an instrumented/ultrasound reference secondary — comprising an error variance (as a function of true dilatation), examiner random effects and an explicit whole-centimetre coarsening process, and (ii) a jointly fitted informative-observation-time model for the examination schedule: (a) what is the shift in the median and 95th-centile dilatation-versus-time curves and in the implied action line, stated relative to the published naive fit and to that fit's own confidence bands; (b) what proportion of recorded labour-dystocia / failure-to-progress diagnoses change classification under the error-corrected curve at the published threshold, applied mechanically as written; and (c) how do (a) and (b) decompose between the measurement-error and observation-timing components? Measurand declaration is load-bearing: true dilatation is defined procedurally as the maximal internal os diameter an examiner using a stated standardised technique and examination pressure would obtain. (V1 intake form and the reasoning for the one permitted Gate 1 reformulation: batches/2026-10-18-0130/UQ-20261018-02-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — obstetrics / intrapartum care (target field, whos"},{"id":"UQ-20261018-05","kind":"new","field":"Medicine","title":"In hospital systems where infusate history is attributable to a SPECIFIC peripheral IV catheter (line-level administration documentation or validated pump-to-line association), fitting a …","text":"In hospital systems where infusate history is attributable to a SPECIFIC peripheral IV catheter (line-level administration documentation or validated pump-to-line association), fitting a cause-specific nested frailty survival model for catheter failure with random effects for patient, inserter, ward and device lot plus a per-admixture infusate term: (a) on the log-hazard scale, what is the variance partition coefficient of the infusate component for each failure mode (phlebitis, infiltration/extravasation, occlusion, dislodgement, infection), with an interval — a declared DESCRIPTIVE decomposition, any causal reading of \"attributable\" demoted to a secondary analysis under a stated identification strategy for confounding by acuity; and (b) does the incumbent binary access rule (osmolarity above ~600 mOsm/L, or pH outside ~5–9, implying central access) discriminate and calibrate against (i) the fitted infusate-attributable hazard and (ii) extravasation injury as a co-primary endpoint, as well as an index estimated from the same data under internal–external cross-validation across systems? (V2; the one Gate 1 reformulation. V1 and the reason for reformulation are in batches/2026-10-18-0130/UQ-20261018-05-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — infusion therapy and vascular access"},{"id":"UQ-20261018-08","kind":"new","field":"Other fields","title":"In a jurisdiction holding a retrievable register of performance-based (\"alternative solution\" / \"performance solution\" / equivalency) fire-safety approvals joinable to individual buildings …","text":"In a jurisdiction holding a retrievable register of performance-based (\"alternative solution\" / \"performance solution\" / equivalency) fire-safety approvals joinable to individual buildings, and with frame, covariate set and non-inferiority margin declared before any data pull: (A) for what fraction of buildings in the frame can design pathway be recovered, and how many code-relevant fire incidents accrue to the performance-based stratum, and (B) conditional on (A) clearing a declared power threshold, among buildings in which a fire actually occurred, does the performance-based stratum differ from otherwise-comparable prescriptively designed buildings — matched or weighted on occupancy class, height, construction era and suppression provision — in realized engineering outcomes, with flame and smoke spread beyond the compartment of origin as the primary endpoint and structural damage and casualties secondary? (V2, the one Gate 1 reformulation. V1, as intaken: \"Among buildings in which a fire has actually occurred, do those designed by performance-based fire engineering differ from otherwise-comparable prescriptively designed buildings in realized engineering outcomes — fire and smoke spread beyond the compartment of origin, and structural damage — once occupancy, height, era and suppression provision are matched?\" V2 fixes the frame, makes the margin a pre-declaration requirement, and promotes recoverability to limb (A) so the question is answerable whichever way the records fall.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — fire safety engineering and building-code polic"},{"id":"UQ-20261018-10","kind":"new","field":"Other fields","title":"For one declared national installed base of static residential electricity meters, taking a probability sample stratified by meter model, firmware revision and build year from a …","text":"For one declared national installed base of static residential electricity meters, taking a probability sample stratified by meter model, firmware revision and build year from a distribution utility's asset register, and applying a pre-declared library of residential load mixes synthesised from a published appliance current-waveform set against a reference instrument whose immunity to those same stimuli is demonstrated rather than assumed: what is the population-weighted distribution of relative registration error per mix (mean with CI, plus lower and upper tail quantiles), and, under a declared national load-composition model, what fraction of billed residential energy does that distribution imply is misregistered? (v2; the one permitted Gate 1 reformulation of v1, which asked the same thing without a sampling frame, a declared mix library, a demonstrated-immune reference, or the conditional status of the billed-energy limb.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — electrical metrology / power engineering"},{"id":"UQ-20261018-14","kind":"new","field":"Computer science and AI","title":"Over the modded-nanogpt speedrun's record series (8×H100 / FineWeb val-loss ≤3.28), under a pre-declared protocol (≥5 re-timings per record on ≥2 nodes, in two arms — A1 period-correct …","text":"Over the modded-nanogpt speedrun's record series (8×H100 / FineWeb val-loss ≤3.28), under a pre-declared protocol (≥5 re-timings per record on ≥2 nodes, in two arms — A1 period-correct environments, A2 one common modern environment; a step-down counted as surviving only if the re-timed distributions separate at p<0.01; the surviving share computed log-additively; plus a pre-declared transfer ladder on which each accepted change's retained speedup is reported with a CI), what share of the cumulative recorded wall-clock speedup survives (i) re-timing and (ii) transfer, and how many records no longer run, by failure class? (V2, the one permitted Gate 1 reformulation; V1 intake version retained in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — training-systems optimization"},{"id":"UQ-20261018-15","kind":"new","field":"Computer science and AI","title":"For >=2 open pretraining runs with dense cooldown checkpoints and one pinned harness, decompose each benchmark's cooldown-phase score change into (i) a sharpening/format component — the …","text":"For >=2 open pretraining runs with dense cooldown checkpoints and one pinned harness, decompose each benchmark's cooldown-phase score change into (i) a sharpening/format component — the part reproduced on the PRE-cooldown checkpoint by a fixed-weight output transform fitted on held-out items (temperature/entropy rescaling; length-normalised or rank-based option scoring; a label-emission format correction), no weight update — and (ii) a knowledge residual read by a pre-declared probe panel held fixed across checkpoints; report the share per benchmark with uncertainty, a manipulation check, and the re-ranking of >=3 published annealing data mixes under (ii) alone. (V2; the one permitted Gate 1 reformulation, spent. V1 asked the same without an estimator — see record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — pretraining schedule design, the annealing"},{"id":"UQ-20261018-16","kind":"new","field":"Biology","title":"Over a frame of co-held microbial accessions declared before any sequencing — strains linked as \"equivalent\" across two or more independent collections (ATCC, DSMZ, NCTC, CIP, JCM, NCIMB) …","text":"Over a frame of co-held microbial accessions declared before any sequencing — strains linked as \"equivalent\" across two or more independent collections (ATCC, DSMZ, NCTC, CIP, JCM, NCIMB) by catalogue cross-reference or StrainInfo identifier matching — sequence the material as distributed by each collection (freshly ordered ampoules, primary arm; distributor-provenanced public assemblies, secondary arm) and report (a) the pairwise cross-collection divergence distribution partitioned into SNV / indel / IS / plasmid / prophage classes; (b) the share of accession pairs exceeding a comparator measured inside the same study — the divergence between two independently revived ampoules of one lot from one collection — not a stipulated threshold; (c) the dependence of divergence on transfers-since-deposit and years-since-deposit, under a pre-declared rule separating post-deposit drift from cross-referencing error. (This is V2, the one Gate 1 reformulation, adopted as canonical. V1, superseded at Gate 1: same question with \"a pre-declared within-strain comparator\", which was undefined and so answerable by stipulation.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — microbiology / microbial systematics and biologica"},{"id":"UQ-20261018-18","kind":"new","field":"Biology","title":"For specimen and occurrence records bearing an open-nomenclature qualifier (\"cf.\", \"aff.\", \"sp.\", \"?\"), drawn only from sources in which qualifier survival from original label to delivered …","text":"For specimen and occurrence records bearing an open-nomenclature qualifier (\"cf.\", \"aff.\", \"sp.\", \"?\"), drawn only from sources in which qualifier survival from original label to delivered record has been verified end-to-end, and under a resolution rule declared before any data pull: what is the per-qualifier agreement rate with an independent later determination at a declared rank (reported separately for a revision-based arm and a sequence-backed arm), does that rate order the qualifiers in the sequence their published usage guidance implies, and does the between-stratum spread of that rate across determiner, institution, higher taxon and decade stay inside a pre-declared tolerance — the tolerance being the criterion for whether an aggregator may read the mark as a transferable probability?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — systematics/taxonomy and biodiversity informatics"},{"id":"UQ-20261018-20","kind":"new","field":"Biology","title":"For one declared tissue in a declared species, strain, sex, age and housing condition, assayed in a declared physiological state with a pre-declared in situ marker panel whose per-modality …","text":"For one declared tissue in a declared species, strain, sex, age and housing condition, assayed in a declared physiological state with a pre-declared in situ marker panel whose per-modality sensitivity and specificity have been measured in that same tissue against induced positive controls: what is the per-modality prevalence of marker-positive dying cells per unit tissue (with intervals, an explicit multi-positive fraction and an explicit unclassified residual), and — where a modality's corpse-persistence time is independently measured or bounded in that tissue — the implied per-modality death incidence per unit tissue per day, reconciled against an independently measured total turnover? (V2, the graded version; V1 as intaken: what share of in vivo physiological cell death is apoptotic and what share proceeds by each non-apoptotic regulated modality.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — cell biology (regulated cell death, tissue homeost"},{"id":"UQ-20261021-01","kind":"new","field":"Medicine","title":"V2 (Gate 1 reformulation, the one permitted; scored as canonical) — In >=2 independent cohorts or trials holding per-patient time-stamped electronic dosing records over whole inter-visit …","text":"V2 (Gate 1 reformulation, the one permitted; scored as canonical) — In >=2 independent cohorts or trials holding per-patient time-stamped electronic dosing records over whole inter-visit intervals and a visit-measured biomarker whose pharmacodynamic response time is shorter than that interval (BP, LDL, HIV RNA, IOP, INR), under one pre-declared exposure-response model per biomarker with >=2 model forms as sensitivity: what is the signed difference, per randomised arm and in the arm contrast, between the treatment effect as the visit-measured analysis reports it and the effect predicted when each patient's realised doses are redistributed uniformly across the interval (dose-count-preserving; visit-entrained component removed, total exposure fixed), expressed as a fraction of the observed arm difference against a pre-declared margin, with HbA1c as the pre-specified falsification arm in which the difference must vanish? V1 (as intaken) differs only in specification, not in object; both texts in batches/2026-10-21-0452/UQ-20261021-01-record.md.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — clinical-trial methodology and chronic-disease th"},{"id":"UQ-20261021-03","kind":"new","field":"Medicine","title":"For each of a pre-declared set of medication-error classes, restricted per class to orders whose barrier-capability set holds >=2 barriers (CPOE alert, pharmacist verification, barcode …","text":"For each of a pre-declared set of medication-error classes, restricted per class to orders whose barrier-capability set holds >=2 barriers (CPOE alert, pharmacist verification, barcode administration) with per-barrier outcome joinable to the order record: (a) estimate P(barrier k+1 fails | barrier k failed) against the same cohort's marginal P(barrier k+1 fails), with intervals; (b) express the coupling as a CCF beta factor (or alpha-factor set) with an interval; (c) report the ratio of realised all-barrier passage probability to the prediction from that same cohort's own marginals; (d) bound the unobserved \"passed every barrier, never detected\" stratum with declared assumptions; (e) record whether any of the site's own published barrier/FMEA/business-case analyses states a product of barrier failure probabilities. (V2; V1 and the Gate 1 reformulation rationale are in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — patient safety, hospital pharmacy and medication"},{"id":"UQ-20261021-04","kind":"new","field":"Medicine","title":"For a pre-declared set of payer-by-service cells drawn from the first years of CMS-0057-F public prior-authorization reporting, what fraction of prior-authorization-requiring clinical …","text":"For a pre-declared set of payer-by-service cells drawn from the first years of CMS-0057-F public prior-authorization reporting, what fraction of prior-authorization-requiring clinical decisions terminate on the provider side before any request reaches the payer, and does cross-payer variation in the published denial rate predict that pre-submission attrition rate with a negative sign — in what share of cells does adding attrition reverse the ranking of payers by obstruction, against a flip threshold fixed before any data pull? (V2; the one permitted Gate 1 reformulation. V1 and the two factual corrections that forced it are in batches/2026-10-21-0452/UQ-20261021-04-record.md.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — health systems, insurance coverage, access to car"},{"id":"UQ-20261021-05","kind":"new","field":"Medicine","title":"On declared wards served by identified medical-gas pipeline legs, with leg flow and pressure logged at <=1 min, delivered flow measured at instrumented terminal units on a sampled subset of …","text":"On declared wards served by identified medical-gas pipeline legs, with leg flow and pressure logged at <=1 min, delivered flow measured at instrumented terminal units on a sampled subset of outlets, and per-patient-hour prescribed device and flowmeter setting from the EHR: (i) is delivered-minus-set flow at an outlet a function of EXOGENOUS leg load — concurrent draw by patients other than the index patient, as a fraction of that leg's engineering design flow, breakpoint pre-declared — and (ii) what share of within-patient variation in a pre-declared oxygenation endpoint (SpO2 time-in-target, FiO2 shortfall, device escalation) is attributable to that load, under within-patient contrasts and a negative-control leg? (V2; V1 and the single permitted Gate 1 reformulation are in the record.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — critical/respiratory care and hospital medical-ga"},{"id":"UQ-20261021-08","kind":"new","field":"Other fields","title":"Under a forensic-style black-box design — specimens failed in the laboratory by mechanisms known by construction, a mechanism label set and an explicit inconclusive option fixed in advance …","text":"Under a forensic-style black-box design — specimens failed in the laboratory by mechanisms known by construction, a mechanism label set and an explicit inconclusive option fixed in advance, examiners working independently and blind both to the answer and to one another, and each specimen randomised across context arms declared in advance as either NON-DIAGNOSTIC (which side retained the examiner) or DIAGNOSTIC-BUT-MANIPULATED-IN-VERIDICALITY (a service-history narrative that is true, false, or withheld) — what are the false-attribution rate, the inconclusive rate and the inter-examiner reproducibility of expert fracture-mode and failure-mode determination in engineering failure analysis, and by how much does each context arm shift them relative to the no-context arm?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — materials engineering / failure analysis and fo"},{"id":"UQ-20261021-09","kind":"new","field":"Other fields","title":"On a building frame declared before any data pull in one EGMS-covered region, with the damage cut fixed in advance at Burland D>=2 (D>=3 as a pre-specified sensitivity arm) and the …","text":"On a building frame declared before any data pull in one EGMS-covered region, with the damage cut fixed in advance at Burland D>=2 (D>=3 as a pre-specified sensitivity arm) and the predictor declared as EGMS-derived within-footprint differential vertical velocity over the service observation window rather than as cumulative angular distortion since construction: (a) what are the sensitivity, specificity, ROC/AUC with intervals and — on a probabilistically drawn, independently verified sub-sample that fixes damage prevalence — the positive predictive value of exceeding each criterion's own limiting value, evaluated only for those criteria whose measurand the service supplies (Skempton–MacDonald delta/L; Burland–Wroth Delta/L under a declared inflection-point rule), with Boscardin–Cording reported as not evaluable for want of horizontal strain; and (b) how much of any shortfall is attributable to the rate-for-cumulative substitution, estimated on the subset also carrying bed-joint levelling? (This is V2, the one Gate 1 reformulation, scored as canonical; V1 asked more loosely whether the Skempton–MacDonald / Burland–Wroth / Boscardin–Cording family discriminates damaged from undamaged buildings at population scale.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — geotechnical/structural engineering (target fie"},{"id":"UQ-20261021-10","kind":"new","field":"Other fields","title":"For a declared region and window and a frame declared before any data pull, on one pre-declared crosswalk layer (cathode-active-material chemistry shares by mass of arriving battery mass …","text":"For a declared region and window and a frame declared before any data pull, on one pre-declared crosswalk layer (cathode-active-material chemistry shares by mass of arriving battery mass, with black-mass element content reported as a separate second layer): (a) what is the measured arrival-composition distribution under a sampling protocol declared in advance and reported with its fundamental-sampling-error and grouping-and-segregation budget and detection limits; (b) over a declared literature frame of recycling-process and LCA studies that state an input composition, what is the distribution of *assumed* compositions on that same layer, with the non-stating excluded share reported as a primary result; and (c) what is the signed gap, and what does it do to those studies' recovery-efficiency and recycled-content figures when their own models are re-run on the measured composition? (Format = stratifier; state of health defined only on the intact-pack/module sub-stream, with the not-evaluable remainder's mass share reported.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — materials/chemical engineering (Li-ion battery"},{"id":"UQ-20261021-12","kind":"new","field":"Computer science and AI","title":"In reward models trained by the standard pairwise (Bradley-Terry) objective — whose likelihood depends only on reward differences within a prompt's comparison set, leaving the fitted reward …","text":"In reward models trained by the standard pairwise (Bradley-Terry) objective — whose likelihood depends only on reward differences within a prompt's comparison set, leaving the fitted reward identified only up to an additive function of the prompt — (i) what share of the variance in the scalar reward is that per-prompt offset, with CIs, for >= 3 released pairwise-trained reward models on >= 2 preference corpora, with the panel declared; (ii) is the between-prompt component reproducible across k re-fits with different seeds and permuted prompt order, or seed-contingent; and (iii) for each named shipped practice whose decision rule genuinely spans prompts, what is the decision-flip rate when the score is centred within prompt, computed under that practice's own stated decision rule, with a CI?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — post-training and reward modelling (target"},{"id":"UQ-20261021-13","kind":"new","field":"Computer science and AI","title":"On a pre-declared frame F of preference corpora carrying stable per-annotator identifiers (or a declared proxy: vendor, shift, guideline revision), under a pre-declared cross-classified …","text":"On a pre-declared frame F of preference corpora carrying stable per-annotator identifiers (or a declared proxy: vendor, shift, guideline revision), under a pre-declared cross-classified Bradley-Terry/logistic model of the pairwise outcome with crossed random effects for annotator, annotator-cluster and item plus a linear-probability companion — (a) what are the variance components and the implied annotator-level and cluster-level intraclass correlations, on both declared scales, with CIs; (b) what Kish design effect and effective sample size N_eff do they imply when computed with the UNEQUAL cluster sizes actually present rather than an equal-cluster formula, with sensitivity to the cluster definition; and (c) holding total labels fixed and varying the number of distinct annotators, does reward-model accuracy (or a declared RLHF endpoint) track N_eff rather than N, against pre-registered bands (NULL Deff <= 1.1 / MODEST 1.1-2 / MATERIAL > 2)? [This is V1, the single permitted Gate 1 reformulation; V0 asked the same thing without declaring the ICC scale, the frame, the model or the bands, and for a binary outcome the latent-logistic and linear-probability ICCs are different numbers from one fit. Full V0 text and the reformulation note: batches/2026-10-21-1833/UQ-20261021-13-record.md.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — the human-preference data layer (reward mo"},{"id":"UQ-20261021-15","kind":"new","field":"Computer science and AI","title":"Over an enumerated frame of published studies that applied a since-retired commercial model snapshot and released per-item outputs plus a recoverable configuration: (a) what is the per-item …","text":"Over an enumerated frame of published studies that applied a since-retired commercial model snapshot and released per-item outputs plus a recoverable configuration: (a) what is the per-item agreement between the archived predecessor outputs and freshly collected outputs from the vendor-designated successor named in dated vendor documentation, under the recorded configuration, stratified by task class, with a declared distance per output type, read against the predecessor's own archived run-to-run band; and (b) under a pre-declared rule mapping each paper's own stated claim and threshold onto a re-derivable decision on the same items, with inter-rater reliability on the mapping, what share of those studies' conclusions reverse, with a confidence interval — the excluded share and exclusion reasons being part of the answer?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — evaluation methodology and model-lifecycle"},{"id":"UQ-20261022-01","kind":"new","field":"Biology","title":"Over a frame of published animal respirometry studies declared before any data pull that report both O2 consumption and CO2 production (or an RQ/RER computed from them) for the same …","text":"Over a frame of published animal respirometry studies declared before any data pull that report both O2 consumption and CO2 production (or an RQ/RER computed from them) for the same individuals or same declared group, with the unit fixed in advance as one reported value-pair at the finest grain the paper prints and the feasibility window fixed in advance at RQ 0.70-1.00 with pre-declared arms at the clinical 0.67-1.30 and at taxon/state exemptions (anaerobiosis, net lipogenesis, discontinuous gas exchange with CO2 storage, aquatic carbonate buffering, non-steady state): (i) what is the infeasible share, with a CI, by taxon, respirometry mode and decade, against a dual-gas denominator that is itself uncounted; (ii) per respirometry mode, derived from that mode's own computation, which error classes an infeasible RQ can and cannot identify, and only then what bound if any it places on the reported mass-specific metabolic rate; and (iii) under pre-declared exclusion and correction rules, does the refitted interspecific allometric exponent move beyond its published confidence interval? [Operative form is V2 = R1, the single permitted Gate 1 reformulation; V1 and the two changes R1 makes are in the record.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — comparative/organismal physiology and metabolic ec"},{"id":"UQ-20261022-03","kind":"new","field":"Biology","title":"On a pinned release of the ProteinGym substitution DMS benchmark (217 assays, ~2.7M missense variants), restricted to assays whose distributed raw pre-preprocessing files carry >=2 …","text":"On a pinned release of the ProteinGym substitution DMS benchmark (217 assays, ~2.7M missense variants), restricted to assays whose distributed raw pre-preprocessing files carry >=2 independently selected replicate measurements per variant — with the eligible share itself reported as a primary result — and under estimators declared before any data pull (primary: variant-level between-replicate reliability on the merged-score scale, Spearman-Brown stepped up to the k replicates merged into the released DMS_score; sensitivity arms: a rank-reliability analogue, an Enrich2/DiMSum per-variant-SE reliability, and a reliability-heteroscedasticity-stratified arm): (a) what is each eligible assay's own test-retest reliability, with bootstrap CIs; (b) when each published zero-shot predictor-assay rank correlation is disattenuated by that reliability, what share of the apparent headroom to perfect prediction (1 - rho_observed) is assay measurement error rather than model error, with its uncertainty; and (c) does the published ranking of predictors change, reported as Kendall tau between published and disattenuated orderings plus a count of pairwise reversals in a pre-declared top-k?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — protein science / functional genomics (variant-eff"},{"id":"UQ-20261022-05","kind":"new","field":"Biology","title":"For a pre-declared panel of commercial research antibodies, each pinned to a catalogue number and a dated datasheet of record: (i) is the vendor-recommended working dilution for a named …","text":"For a pre-declared panel of commercial research antibodies, each pinned to a catalogue number and a dated datasheet of record: (i) is the vendor-recommended working dilution for a named application predicted by the product's stated stock concentration, or by a measurable binding constant plus the nominal target abundance in the recommended sample type, under a comparison declared in advance; and (ii) across a pre-declared sample of published immunoassays using that panel, in what fraction is the mass-per-volume or molar antibody concentration in the incubation computable at all from the paper plus that datasheet, and among papers quoting the same nominal dilution for the same catalogue number, what is the spread in computed concentration? [R1, adopted at Gate 1; V0 superseded there for well-posedness — both versions in the record.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — experimental methods and research-reagent practice"},{"id":"UQ-20261022-06","kind":"new","field":"Medicine","title":"In >=2 accredited clinical laboratories running different middleware vendors and different repeat rule sets, under a rule declared before any data pull for which runs count as the \"first …","text":"In >=2 accredited clinical laboratories running different middleware vendors and different repeat rule sets, under a rule declared before any data pull for which runs count as the \"first valid measurement\", (a) per analyte, what share of released results is not the first valid measurement of that analyte on that specimen, decomposed by the rule that caused the replacement (rerun, dilution, delta-check repeat, critical-value repeat, cross-instrument confirmation); (b) how do the paired first-measurement and released-result distributions differ; and (c) recomputed on both substrates, do the reference-interval limits, the prevalence of threshold-crossing abnormality and the within-person monitoring delta differ by more than a materiality bound fixed in advance — with the share of candidate laboratories whose logs could not supply superseded measurements at all reported as a primary result?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — laboratory medicine / clinical chemistry (target"},{"id":"UQ-20261022-07","kind":"new","field":"Medicine","title":"For a frame of completed placebo-controlled trials declared before any specimen is pulled (study class licensed or obtainable outside the trial's own prescribing channel during the …","text":"For a frame of completed placebo-controlled trials declared before any specimen is pulled (study class licensed or obtainable outside the trial's own prescribing channel during the enrolment window; scheduled-visit control-arm biospecimens retained; release permissible under the governing consent): what is the proportion of control-arm participant-visits at which the study class is detected by one pre-declared validated assay whose limit of detection and false-positive rate are reported and whose detection window is stated against the visit interval; what is that positivity's concordance with the same participant's protocol-recorded concomitant medication; and what is the signed difference between the trial's reported primary estimate and the estimate under one contamination-adjusted estimand declared before any assay result is seen — reported with the share of the declared frame whose governance refused release, so the denominator is auditable?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — randomised-trial methodology and clinical pharmac"},{"id":"UQ-20261022-08","kind":"new","field":"Medicine","title":"For a health system that replaced its EHR, with a queryable legacy archive and a declared look-back window W before cutover date T: (i) per pre-declared fact class (problem-list entries …","text":"For a health system that replaced its EHR, with a queryable legacy archive and a declared look-back window W before cutover date T: (i) per pre-declared fact class (problem-list entries, medication orders, allergies, quantitative labs with units, immunisations, procedures, notes), what fraction of the facts present in the SOURCE system's structured tables within W is present, queryable and value-identical in the TARGET system's computable record, under a correspondence rule fixed before any data pull, with \"no admissible correspondent in the target model\" counted as its own category rather than dropped; and (ii) on at least three named longitudinal estimands (incident-diabetes rate, prevalent ACE-inhibitor exposure, Charlson comorbidity prevalence) computed from the target system's standard research extract, is there a level or slope discontinuity at T exceeding a materiality bound declared in advance, where \"artefactual\" is established by re-deriving the same estimand for the same patients from the legacy archive and by a pre-declared no-cutover control window of equal length (plus a contemporaneous non-converting control site where available)?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — clinical informatics / health-systems data infras"},{"id":"UQ-20261022-10","kind":"new","field":"Medicine","title":"For a declared jurisdiction and window, under a support-withdrawal event definition fixed and published before any data pull (minimum per-class constituents of \"support\" …","text":"For a declared jurisdiction and window, under a support-withdrawal event definition fixed and published before any data pull (minimum per-class constituents of \"support\": programming/interrogation, firmware and security updates, consumable and external-component supply, replacement-part supply, remote monitoring, a named clinical point of contact): (i) what is the enumerated list of support-withdrawal events and, per event, the estimated number of living recipients with source and stated uncertainty; and (ii) for events whose recipients are followable, what is the incidence of therapy loss, revision, explant and newly acquired imaging or treatment contraindication in the post-exit period versus the same recipients' pre-exit period and versus matched recipients of still-supported same-class devices — estimand declared per class, null permitted for passive classes, and the share of events whose exposed population could not be counted and the share of classes with no possible outcome ascertainment reported as results rather than caveats.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — implantable-device safety and post-market surveil"},{"id":"UQ-20261022-12","kind":"new","field":"Other fields","title":"Over a frame F of (standard test method, material class) pairs declared before any data pull and admitted only when (a) two or more independent interlaboratory precision studies of the SAME …","text":"Over a frame F of (standard test method, material class) pairs declared before any data pull and admitted only when (a) two or more independent interlaboratory precision studies of the SAME designated method exist on materials matching a declared rule, and (b) each study's laboratory count p, material count m and replicate structure n are recoverable from a public or purchasable document, what is the distribution of log(R2/R1) of the two published reproducibility limits, and does its realized spread exceed the pair-specific spread implied by the sampling distribution of each study's own s_R at its own (p, m, n)? Pairs failing (b) are enumerated as a reported coverage gap rather than dropped. [Adopted wording is the one permitted Gate 1 reformulation (R1 in the record); the Gate 0 intake wording V0 is listed below. Second limb: the joint distribution of (age of the study behind the precision statement, p, m) over an enumerated frame of currently active methods.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — measurement science and standardisation (analyt"},{"id":"UQ-20261022-13","kind":"new","field":"Other fields","title":"For earthquakes with M >= M0 in a declared region and window, reading back from agency A's own versioned event history (or an archived snapshot series or dated bulletins) the magnitude …","text":"For earthquakes with M >= M0 in a declared region and window, reading back from agency A's own versioned event history (or an archived snapshot series or dated bulletins) the magnitude m_tau that A had published at latency tau after origin, and fixing \"final\" as A's value m_D at a declared date D: (a) is the revision r = m_D - m_tau mean-zero (bias in magnitude units, with CI) and orthogonal to the settlement-instant information set (depth, region, station count/azimuthal gap, magnitude type, local time, m_tau itself), reported as a news-versus-noise decomposition; and (b) over the publicly documented population of parametric contracts and automated response thresholds keyed to A's published magnitude, how many trigger decisions flip under m_D rather than m_tau, with the sign of each flip and the money or action at stake?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — seismology and operational earthquake informati"},{"id":"UQ-20261022-15","kind":"new","field":"Other fields","title":"For a declared frame of the six HITRAN-format line parameters (nu_ij, S_ij, gamma_air, gamma_self, n_air, delta_air) of the transitions carrying at least a declared share X of the …","text":"For a declared frame of the six HITRAN-format line parameters (nu_ij, S_ij, gamma_air, gamma_self, n_air, delta_air) of the transitions carrying at least a declared share X of the Jacobian-weighted absorption in the fitting windows of a declared set of operational column retrievals, at a pinned compilation release: resolving each parameter's own per-parameter reference index to its primary source, and under a pre-declared independence rule scored at two strictness levels (R-strict: distinct apparatus AND calibration standard AND sample AND no shared author AND distinct theoretical method/fitting code, each criterion reported separately; R-weak: distinct publication only), what is (i) the count n of mutually independent primary determinations per parameter and whether they agree within stated uncertainties, (ii) the share of sensitivity-weighted parameter mass with n <= 1 at each strictness level, and (iii) for each parameter with n <= 1, which declared retrievals and ground networks actually read it, established from each retrieval's own documented spectroscopy source rather than assumed?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — molecular spectroscopy and atmospheric remote s"},{"id":"UQ-20261022-16","kind":"new","field":"Computer science and AI","title":"For a pre-declared set of shipped open-weight LLM releases, a pre-declared prompt set, and a detector-defined set U of under-trained vocabulary items (reported SEPARATELY from the set R of …","text":"For a pre-declared set of shipped open-weight LLM releases, a pre-declared prompt set, and a detector-defined set U of under-trained vocabulary items (reported SEPARATELY from the set R of tokenizer-unreachable items, since the two sets and their hazard meanings differ), under free self-conditioned generation: (i) what is the mean and upper-tail step-wise pre-truncation probability mass on U and on R; (ii) at what share of generation steps does at least one member of U (resp. R) remain inside the sampling support after the release's own declared default truncation rule is applied — with the arm defined per artifact from `generation_config.json`/model card, and an explicitly declared substitute arm recorded as such for releases that ship none; and (iii) what is the realised emission rate of members of U and of R per 10^6 generated tokens, against a null of a vocabulary subset matched on unigram frequency profile?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — the tokenizer/vocabulary layer and the inf"},{"id":"UQ-20261022-18","kind":"new","field":"Computer science and AI","title":"For a pre-declared set of shipped vision-language models crossed with input modes (native resize; each dynamic-tiling / any-resolution setting), probed with synthetic targets (sine …","text":"For a pre-declared set of shipped vision-language models crossed with input modes (native resize; each dynamic-tiling / any-resolution setting), probed with synthetic targets (sine gratings; slanted edges) swept over spatial frequency expressed both in cycles per image and in cycles per encoder patch, crossed with Michelson contrast, orientation and phase, under a 2AFC readout with pre-declared low-frequency positive controls and an enforced chance level: (i) at what frequency does orientation-discrimination accuracy fall to a pre-declared 75%-correct criterion, and what is the contrast threshold as a function of frequency; (ii) what is the ratio of that cutoff to the nominal patch-Nyquist limit; (iii) is any above-cutoff correct responding attributable to resize-kernel aliasing rather than to true transmission; (iv) in a pre-registered out-of-sample comparison with the model x input-mode arm as the unit, does the per-arm cutoff explain variance in fine-detail task accuracy (small text, counting, dense-chart QA) beyond input pixel count and vision-token/patch count?","work":[],"target":"","open":0,"badge":"Provisional","domain":"AI architecture — multimodal model design (vision encoder, r"},{"id":"UQ-20261023-01","kind":"new","field":"Biology","title":"For >=2 published cross-day unit matchers at declared operating points, applied to chronic high-density extracellular recordings in which unit identity is labelled by at least one …","text":"For >=2 published cross-day unit matchers at declared operating points, applied to chronic high-density extracellular recordings in which unit identity is labelled by at least one construction that does NOT use the functional response later used to measure tuning, (a) what are the matcher's false-match and split/merge rates, (b) what apparent change do those rates ALONE induce in >=2 published drift statistics under a declared null of zero true drift — the matching-error drift floor — and (c) do published drift magnitudes, matched on brain area and interval, exceed that floor? [This is V2, the Gate 1 reformulation, the single permitted one, and the version Gates 2-5 and the post-batch verification pass were run against; the original per-paper decomposition wording is recorded verbatim in ledger/batches/2026-10-23-0033/UQ-20261023-01-record.md.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — systems neuroscience"},{"id":"UQ-20261023-02","kind":"new","field":"Biology","title":"For >= 3 nominally constant-condition (DD or LL) recording chambers in >= 2 facilities, instrumented with passive multi-channel logs (temperature, vibration, sound, CO2, humidity …","text":"For >= 3 nominally constant-condition (DD or LL) recording chambers in >= 2 facilities, instrumented with passive multi-channel logs (temperature, vibration, sound, CO2, humidity, door/access events) at <= 1 min resolution over >= 2 complete experiments: (a) what is the amplitude and phase of the 24-hour component of each channel, with CIs, and does the temperature channel's amplitude reach or exceed the documented thermal entrainment threshold for the preparation under test; and (b) in a prospective chamber-crossed design running one fixed genotype or preparation across those same instrumented chambers, with chamber assignment randomised or counterbalanced, how much of the observed between-chamber variance in free-running period (tau) is attributable to the chambers' measured 24-hour amplitude, estimated as a chamber-level variance component alongside an imposed-cue-versus-sham arm at the measured facility amplitude testing for period change, phase-angle locking and after-effects?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — chronobiology (organismal and cell-autonomous circ"},{"id":"UQ-20261023-03","kind":"new","field":"Biology","title":"For single *Escherichia coli* cells held in a microfluidic trap and subjected to repeated hypo-osmotic downshocks of fixed amplitude DPi (each below the single-shock lytic threshold) at a …","text":"For single *Escherichia coli* cells held in a microfluidic trap and subjected to repeated hypo-osmotic downshocks of fixed amplitude DPi (each below the single-shock lytic threshold) at a fixed recovery interval, does the per-cell hazard of lysis depend on the cycle index n after conditioning on the largest amplitude the cell has experienced — and if so, (a) is median cycles-to-lysis N(DPi) describable by a stress-life power law log N = a - b log DPi across >= 4 amplitudes, (b) is there an amplitude below which no lysis occurs within the attainable cycle budget, and (c) in a two-block mixed-amplitude sequence, does SUM(n_i / N_i) = 1 at failure as Palmgren-Miner predicts — each tested in a growing arm and in a wall-synthesis-inhibited arm?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — bacterial cell biophysics (cell-envelope mechanics"},{"id":"UQ-20261023-04","kind":"new","field":"Biology","title":"In nanopore adaptive (\"Read Until\") sequencing, where the instrument ejects reads mid-translocation on a reference-dependent decision taken on each read's first few hundred to few thousand …","text":"In nanopore adaptive (\"Read Until\") sequencing, where the instrument ejects reads mid-translocation on a reference-dependent decision taken on each read's first few hundred to few thousand bases, what signed bias does that data-dependent selection induce in estimands computed from the retained reads — reference-allele fraction and heterozygote recovery at target loci, insertion/SV recall by size class, repeat-length distribution, per-site methylation fraction — and is the bias correctable from the run's own retained output, i.e. the ejected reads' first-chunk prefixes joined by read_id to the logged sequence/unblock action, with the decision rule replayed over them to reconstruct a selection propensity?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — genomics methods and the data layer (long-read nan"},{"id":"UQ-20261023-06","kind":"new","field":"Medicine","title":"For a frame declared before any data pull — completed randomised trials or registry cohorts that (i) report a consensus CGM metric as a primary or key secondary endpoint, (ii) used a sensor …","text":"For a frame declared before any data pull — completed randomised trials or registry cohorts that (i) report a consensus CGM metric as a primary or key secondary endpoint, (ii) used a sensor model for which a published pressure-induced-sensor-attenuation (PISA) detector with a stated operating characteristic exists, and (iii) hold retrievable per-reading traces with timestamps, the excluded share reported as denominator attrition — what is the change, in percentage points, of nocturnal percent time <70 mg/dL and percent time <54 mg/dL, and of level-2 hypoglycaemic event count per 14 days, when readings flagged at a pre-declared PISA detector operating point are handled under a pre-declared removal rule (flag-as-missing with the imputation strategy fixed in advance); what is the detector's own false-positive contribution to that change, bounded from simultaneous dual-sensor-wear data at the same operating point; and does the recomputed between-arm difference, with confidence interval, cross the trial's own pre-specified margin (fallback: half-width of its primary 95% CI) or change sign, across a pre-declared sensitivity band of operating points?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — diabetes care"},{"id":"UQ-20261023-07","kind":"new","field":"Medicine","title":"In adult inpatients transfused under a single-unit policy, what fraction of the between-episode variance in the post-transfusion haemoglobin increment is attributable to the measured …","text":"In adult inpatients transfused under a single-unit policy, what fraction of the between-episode variance in the post-transfusion haemoglobin increment is attributable to the measured haemoglobin mass of the specific red-cell unit issued, and does the probability of needing a second unit depend on which unit the patient happened to receive? Reformulation note: one reformulation was used at Gate 1 (V2), adding non-bleeding adult inpatients at a service with a documented single-unit-then-reassess policy, a declared 12-48 h sampling window, inventory issue order within the ABO/Rh- and specification-compatible pool as L2's assignment mechanism with a stated covariate-balance test, a 48-h second-unit hazard, and a third limb (c) asking the pre-declared change in the 48-h second-unit rate under mass-based issuing. V1 and V2 are both on the record; V2 is the version scored.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — transfusion medicine / patient blood management."},{"id":"UQ-20261023-10","kind":"new","field":"Medicine","title":"In a cohort of hospital admissions with linked timestamped medication-administration and laboratory records, restricted to a pre-declared drug list whose labels state a renal dose threshold …","text":"In a cohort of hospital admissions with linked timestamped medication-administration and laboratory records, restricted to a pre-declared drug list whose labels state a renal dose threshold and a single full dose per indication (titrated drugs excluded by pre-declared rule) and to episodes in which the administered dose fell below the labelled full dose while measured clearance was below that drug's label threshold, then taking renal recovery as clearance returning above that same label threshold and staying above it for a declared interval (primary 24 h; sensitivity arms at 12 h and 48 h and a cystatin-C/measured-clearance arm): (a) what is the cumulative incidence of dose restoration to the labelled full dose as a function of time since recovery, with drug discontinuation, discharge and death as competing risks; (b) what share of episodes is never restored before the first of those events; (c) what is the exposure deficit, as administered over labelled full dose integrated across the post-recovery pre-event window, per drug class; (d) what share of non-restorations is documented-deliberate rather than undocumented; and (e) per contributing site, does the deployed renal dosing rule set contain any rule that fires on a dose below the labelled full dose at a clearance above the threshold? [This is V2, the one permitted Gate 1 reformulation, scored as canonical. V1 asked the same five limbs without fixing the recovery clock, the denominator of \"intended exposure\" or the integration window; V2 fixes each by stipulation and moves the rule-directionality limb from the motivating prose into a reported output. No limb was added or dropped. THREE one-sentence repairs are owed and are noted under Scores: the primary instrument should read \"estimated creatinine clearance (Cockcroft-Gault where the label specifies an equation)\" — not merely \"estimated clearance\", because two of the five labels opened post-batch name no estimating equation at all; limb (c)'s integral should say whether it is the integral of a ratio or the ratio of integrals; and the \"pre-declared drug list\" this clause restricts to must actually be ENUMERATED, with its exclusion rule widened beyond titration to the pathogen- and day-of-therapy-conditional dosing the opened labels print. None of the three changes a limb.]","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — hospital pharmacy, nephrology/AKI, antimicrobial"},{"id":"UQ-20261023-11","kind":"new","field":"Other fields","title":"For one declared seismic network N over one declared window W, with the station frame fixed by rule (channels whose FDSN epoch covers >=90% of W), the reference fixed as a NAMED published …","text":"For one declared seismic network N over one declared window W, with the station frame fixed by rule (channels whose FDSN epoch covers >=90% of W), the reference fixed as a NAMED published capability or completeness product for N on a declared magnitude scale, and the grid enumerated at clustering window w in {15 min, 1 h, 6 h}, margin dM in {0.2, 0.3, 0.5} magnitude units and duration T in {1, 3, 6, 12} h — estimate from per-channel availability records and a declared model mapping the up-channel set at t to a realized threshold field: (a) the share of downtime station-hours falling in multi-station coincident clusters in excess of a per-station independent (Poisson/renewal) null, at each w, with a permutation interval; (b) the paired probabilities of an interval of >=T h in which the realized threshold exceeds the named reference by >=dM, computed once under the independent null and once under the measured joint downtime process, reported as a ratio over the (dM, T) grid; and (c) the share of realized-threshold variance attributable to correlated versus independent downtime under a declared variance decomposition. This is V2, the one Gate 1 reformulation (V1 and the reasons for the repair are in batches/2026-10-23-1233/UQ-20261023-11-record.md, Gate 0). V1 left dM, T and w undeclared and presupposed a unique \"published capability map\"; V2 enumerates the grid, states the frame as a rule, and requires the reference to be a named document.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — observational seismology and monitoring-network"},{"id":"UQ-20261023-12","kind":"new","field":"Other fields","title":"In at least one real field-instrument fleet whose calibration-management records hold, per calibration event, the instrument model, the scheduled due date (or the recall interval in force …","text":"In at least one real field-instrument fleet whose calibration-management records hold, per calibration event, the instrument model, the scheduled due date (or the recall interval in force, from which it is derivable), the actual calibration date, and a numeric as-found deviation per calibrated characteristic together with that characteristic's tolerance limit — is the arrival time for calibration independent of the as-found deviation state after conditioning on elapsed time since the previous calibration, instrument model and a usage proxy; and, expressed as the change in days and as a percentage of the current interval in the interval that meets a declared end-of-period in-tolerance target, what are the sign and size of the bias that any such dependence imparts to the estimated in-tolerance-probability-versus-elapsed-time curve from which calibration intervals are set?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — metrology and measurement-systems engineering ("},{"id":"UQ-20261023-14","kind":"new","field":"Other fields","title":"Over a frame declared before any data pull — all (operator, clock-or-receiver-model) strata with a per-unit time-error, phase-offset, holdover-state or alarm record obtainable at >= 1 …","text":"Over a frame declared before any data pull — all (operator, clock-or-receiver-model) strata with a per-unit time-error, phase-offset, holdover-state or alarm record obtainable at >= 1 sample / 15 min for >= 30 consecutive days spanning a declared disturbance epoch, carrying a model or holdover-oscillator-class identifier, and whose application is governed by one of the limit-bearing documents given by the rule below — and with disturbance epochs declared ONLY from evidence generated outside the units under study (regulator interference bulletins, NOTAMs, ADS-B-derived interference products, GPS/Galileo NAGUs, constellation or ground-segment anomaly notices): what is the distribution of maximum |time error| delivered to the dependent application, per epoch and per model stratum (median and upper quantiles with contributing-unit counts), and what fraction of units exceeded the numeric limit its governing document states, with a Clopper-Pearson interval and with the share of the nominal denominator lost to missing records reported?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Other STEM — time and frequency metrology, and the timing la"},{"id":"UQ-20261029-03","kind":"new","field":"Physics","title":"At three or more temperatures in 70-150 K, where the stacking state is quasi-frozen on a laboratory timescale, what is the ratio of mean grain-grain sintered-contact tensile strength for …","text":"At three or more temperatures in 70-150 K, where the stacking state is quasi-frozen on a laboratory timescale, what is the ratio of mean grain-grain sintered-contact tensile strength for stacking-disordered/cubic (Isd/Ic) water ice to that for hexagonal (Ih) ice, at matched temperature, contact time, load, grain radius and specific surface area, with stacking order measured on the same grains before and after each contact test; and at one declared anneal temperature in 170-200 K, does contact strength change through an isothermal anneal that converts Isd to Ih, measured against a paired Ih control held at the same temperature for the same duration?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Physics — cryogenic surface physics and contact mechanics"},{"id":"UQ-20261029-05","kind":"new","field":"Physics","title":"For ice grown from the vapour in one chamber at matched supersaturation, by how many kelvin does each of the three plate/column habit transition temperatures move between H2O and D2O, and …","text":"For ice grown from the vapour in one chamber at matched supersaturation, by how many kelvin does each of the three plate/column habit transition temperatures move between H2O and D2O, and does the measured set of shifts agree with the shift computed from D2O's own premelting driving force (the distance from its sublimation line to the metastable prolongation of its condensation line, a fixed-Δp threshold) or with the near-zero shift a step-generation kinetics mechanism with its own activation energies would require? (This is V2, the one permitted Gate 1 reformulation, scored as canonical; V1 fixed the premelting prediction at D2O's +3.8 K melting-point offset, a scaling the record's own premelting source denies.)","work":[],"target":"","open":0,"badge":"Provisional","domain":"Physics — ice physics, crystal growth from the vapour (surfa"},{"id":"UQ-20261029-06","kind":"new","field":"Computer science and AI","title":"Train networks of one fixed architecture, initialisation and token budget under one fixed recipe on synthetic data whose input covariance eigenvalues follow lambda_i proportional to …","text":"Train networks of one fixed architecture, initialisation and token budget under one fixed recipe on synthetic data whose input covariance eigenvalues follow lambda_i proportional to i^-beta, over the enumerated grid beta in {0.5, 1.0, 1.5, 2.0, 2.5, 3.0} crossed with (eta, B) in {1e-3, 4e-3, 1.6e-2} x {16, 64, 256}; estimating the ESD power-law tail exponent alpha by the Hill estimator on a declared 10% tail fraction over every hidden weight matrix with min(m,n) >= 512, what is the dimension of the resulting alpha surface — does it collapse onto a curve in beta alone, in log T alone (T = eta/B), onto a single combination beta^a T^b, or does it require both arguments irreducibly — and what are the partials d(alpha)/d(beta) and d(alpha)/d(log T) at the grid centre, with confidence intervals?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Computer science — AI architecture and learning dynamics (me"},{"id":"UQ-20261029-08","kind":"new","field":"Computer science and AI","title":"For a managed-runtime program traced to exact object death times on a single declared clock (bytes allocated), does the death hazard of a heap object depend only on its age, or do the …","text":"For a managed-runtime program traced to exact object death times on a single declared clock (bytes allocated), does the death hazard of a heap object depend only on its age, or do the identifiable curvatures of the death-time (period) and allocation-epoch (cohort) axes differ from zero — reporting (i) second-difference curvature sequences for the period and cohort axes with intervals, (ii) a pre-declared likelihood-ratio test of the age-only submodel, and (iii) nested deviance reductions under ALL orderings of the three axes, since under p = c + a no unique split exists? (This is V2, the one permitted Gate 1 reformulation, and the version scored; V1 asked in its third clause for a single deviance \"split\" that the exact dependence it invokes makes non-identifiable.)","work":[{"type":"ask-adversary","what":"attack the question","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-ADV-UQ-20261029-08","open":1,"badge":"Provisional","domain":"Computer science — programming-language runtimes and memory"},{"id":"UQ-20261030-01","kind":"new","field":"Biology","title":"In two or more symmetrically dividing mammalian cell lines, over >=150 live-tracked divisions per line, with three damage species labelled simultaneously in the same cell — (i) …","text":"In two or more symmetrically dividing mammalian cell lines, over >=150 live-tracked divisions per line, with three damage species labelled simultaneously in the same cell — (i) aged/depolarised mitochondria, (ii) cytosolic misfolded-protein inclusions, (iii) lipofuscin-autofluorescent lysosomes — and the daughter order in every division fixed by one species-independent rule (the daughter inheriting the older mother centriole), is the matrix of within-division Spearman rank correlations between the volume-normalised signed asymmetries a_s = (x1 − x2)/(x1 + x2) all-positive (one sorting axis), indistinguishable from a species-label-permutation null (independent per-species mechanisms), or negative (active routing of different junk to different daughters)?","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — cell biology (cell division, protein quality contr"},{"id":"UQ-20261030-02","kind":"new","field":"Biology","title":"In isogenic human cell lines each carrying one tagged, inducible, single-copy L1 donor at a mapped chromosomal locus, does the per-bin rate of de-novo L1 insertion depend on that bin's …","text":"In isogenic human cell lines each carrying one tagged, inducible, single-copy L1 donor at a mapped chromosomal locus, does the per-bin rate of de-novo L1 insertion depend on that bin's distance-normalised 3D contact frequency with the donor locus (observed/expected at matched genomic separation), with the primary estimate on TRANS bins, conditional on endonuclease-consensus density, chromatin accessibility, replication timing and base composition — and does the coefficient move when the donor is moved to the opposite A/B compartment? Insertions must be recovered without selection for expression of the tag.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — genome biology (retrotransposon biology, insertion"},{"id":"UQ-20261030-03","kind":"new","field":"Biology","title":"For lytic viruses whose per-cell infectious burst has already been resolved by plaque titration of single-cell lysates (a rule-generated set; HSV-1 in human keratinocytes is the one …","text":"For lytic viruses whose per-cell infectious burst has already been resolved by plaque titration of single-cell lysates (a rule-generated set; HSV-1 in human keratinocytes is the one verified member), in one permissive adherent human cell line per virus, with cells infected synchronously at matched multiplicity inside a pre-registered 0-2 h window after a tracked mitosis: (i) what is the negative-binomial dispersion parameter k of infectious progeny (PFU) per individual cell, with a confidence interval, and (ii) what share of the log-output variance is shared between freshly divided sister cells, measured as the sister-pair intraclass correlation against a null of non-sister pairs matched on cell-cycle phase and multiplicity? This is V2, the one reformulation permitted at Gate 1; V1 is under Alternative formulations. Reformulation note: V1 pre-declared \"at least two viruses with bounded single-round bursts\" and enumerated none; V2 replaces the unenumerated set with a stated rule plus one opened, verified member and fixes the post-division window and the matched null in the question. The rule, not the membership, was supplied.","work":[],"target":"","open":0,"badge":"Provisional","domain":"Biology — infection biology, within-host virus dynamics (sin"},{"id":"UQ-20261030-04","kind":"new","field":"Biology","title":"Within a single cell, is the number of de-novo somatic mutations carried by each individual near-full-length mtDNA molecule distributed as the Poisson expectation computed from that same …","text":"Within a single cell, is the number of de-novo somatic mutations carried by each individual near-full-length mtDNA molecule distributed as the Poisson expectation computed from that same cell's per-base de-novo mutation frequency times the called molecule length, or is it overdispersed — a minority of molecules carrying a disproportionate share of the cell's mutations, as a replication hierarchy among genome copies would produce?","work":[{"type":"ask-adversary","what":"attack the question","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-ADV-UQ-20261030-04","open":1,"badge":"Provisional","domain":"Biology — mitochondrial genetics and genome replication (sin"},{"id":"UQ-20261030-07","kind":"new","field":"Medicine","title":"Across human one-to-many transmission clusters of an acute respiratory virus, what is the donor-level intraclass correlation of log10 transmission bottleneck size N_b — i.e. do the several …","text":"Across human one-to-many transmission clusters of an acute respiratory virus, what is the donor-level intraclass correlation of log10 transmission bottleneck size N_b — i.e. do the several recipients infected by one donor show correlated founding-population sizes, and what fraction of between-event variance in bottleneck width sits at the donor level? (Judged on the Gate 1 reformulation V2, which pins one beta-binomial exact estimator, a 2% iSNV calling threshold, >=100x coverage, recipient specimens within 3 days of recipient symptom onset, a permutation null within setting type, adjustment for donor viral load / symptom status / days-since-onset, and a frame-admission gate of >=15 donors each with >=2 qualifying recipients; V1 as submitted is in batches/2026-10-30-1304/UQ-20261030-07-record.md, Gate 0.)","work":[{"type":"ask-adversary","what":"attack the question","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-ADV-UQ-20261030-07","open":1,"badge":"Provisional","domain":"Medicine — infectious-disease epidemiology and human transmi"},{"id":"UQ-20261030-09","kind":"new","field":"Medicine","title":"In pancreatic ductal adenocarcinoma resected after a gemcitabine-containing neoadjuvant regimen, is the per-microregion probability that a tumour cell is residual-and-viable graded by local …","text":"In pancreatic ductal adenocarcinoma resected after a gemcitabine-containing neoadjuvant regimen, is the per-microregion probability that a tumour cell is residual-and-viable graded by local bacterial occupancy at the 10-100 um scale, net of necrosis fraction, hypoxia marker and distance to nearest perfused vessel? This is the Gate 1 reformulation (the one permitted), not the submitted wording. As submitted: \"In human tumours resected after neoadjuvant chemotherapy with a drug that intratumoural bacteria can inactivate, are the surviving viable tumour cells spatially co-located with bacteria-colonised microniches at the 10-100 um scale, and does local bacterial load grade the local probability of tumour-cell survival?\" The repair was forced by a pre-declared, unenumerated drug set; the set is now one member (gemcitabine) under a stated generating rule (bacterial enzymatic inactivation of the parent compound with the inactivated metabolite identified by mass spectrometry; Geller et al. 2017, HPLC-MS/MS, Figs 1C and 2B-C).","work":[],"target":"","open":0,"badge":"Provisional","domain":"Medicine — cancer (incomplete tumour elimination by chemothe"},{"id":"RESULT-0","kind":"check","field":"Mathematics","title":"G(3,9) = 49","text":"There is no set of 49 integers whose consecutive gaps are all at most 9 and which contains no three terms in arithmetic progression. (A 48-element set exists, so this is G(3,9) = 49; three independent searches inside this project agree, and this unit asks for confirmation from outside it.)","work":[{"type":"answer-reproduce","what":"reproduce the result independently","needs":"CPU only: about 1 CPU-hour growing the set outward from its middle; a few CPU-hours for plain backtracking in C","units":1,"done":0}],"target":"A-REP-G39-49","open":1,"badge":"Confirmed inside the project","note":"Confirmed: 3 of 3 skeptics, three independent exhaustive searches; witness answer/witness/G_s9_48elements.txt"},{"id":"RESULT-2","kind":"check","field":"Mathematics","title":"M(3,7) = 51","text":"There is no choice of one integer from each of the 51 blocks [7i, 7i+6], i = 0..50, such that no three chosen integers form an arithmetic progression. (A valid choice from 50 blocks exists, so this statement is equivalent to M(3,7) = 51, where Brown, Landman and Robertson, arXiv:0706.4420, Table 1, print 48.)","work":[{"type":"answer-reproduce","what":"reproduce the result independently","needs":"CPU only: under 2 CPU-hours with a most-constrained-block-first backtracking search using the mirror symmetry; about 32 CPU-hours for plain backtracking","units":1,"done":0}],"target":"A-REP-M37-51","open":1,"badge":"Lead, not confirmed","note":"Lead: two programs agree, but the skeptic gate went 0 of 3 because searches ran out of time; witness answer/witness/M_s7_50blocks.txt"},{"id":"RESULT-3","kind":"check","field":"Mathematics","title":"w*(3;5) = 76","text":"Every colouring of 1..76 with 5 colours contains x, x+d, x+2d (d >= 1) whose colours c1, c2, c3 satisfy c1 + c3 = 2*c2. (The matching lower bound w*(3;5) >= 76 is classical; only this upper bound is new.)","work":[{"type":"answer-reproduce","what":"reproduce the result independently","needs":"CPU only: about 4.3 CPU-hours with a propagating search split into about 100,000 pieces; make your run resumable, since a restart should cost only the pieces in flight","units":1,"done":0}],"target":"A-REP-W35-76","open":1,"badge":"Lead, not confirmed","note":"Lead: two skeptics on different models reproduced the full search; two gates each went 1 of 3 after restarts killed the other searches"},{"id":"RESULT-4","kind":"check","field":"Mathematics","title":"G(3,10) = 57","text":"If all 90 pieces return None, G(3,10) = 57 (a 56-element set is known: answer/witness/G_s10_56elements.txt). Brown, Landman and Robertson's 2007 table leaves G(3,10) as '?'.","work":[{"type":"answer-piece","what":"run one piece of the search","needs":"CPU only, about an hour a piece","units":90,"done":0}],"target":"A-PIECE-G310-57-","open":90,"badge":"Lead, not confirmed","note":"Lower bound only: a 56-element set (answer/witness/G_s10_56elements.txt); the proof that no 57-element set exists is about 90 CPU-hours and is split into pieces"},{"id":"ASK-ANY","kind":"ask","field":"Any field","title":"Ask something nobody has asked, in any field","text":"Propose five candidate un-asked questions in any field of knowledge, each passing the Depth requirement of LEDGER.md (deep, with a clear test of what would count as an answer, and important if answered), none a duplicate of ledger/INDEX.md.","work":[{"type":"ask-generate","what":"propose smaller questions toward it","needs":"agent time and web search, about an hour","units":1,"done":0}],"target":"Q-GEN-1","open":1},{"id":"V-LR-BOOK-2014","kind":"check","field":"Mathematics","title":"Library unit: does the 2014 Landman-Robertson book already correct the 2007 table?","text":"In B. M. Landman and A. Robertson, Ramsey Theory on the Integers, 2nd edition, American Mathematical Society, 2014: does the book give values or bounds for G(3,s) (s = 6..10), M(3,s) (s = 4..8) or w*(3;5), and if so, which, and do any of them differ from Table 1 of arXiv:0706.4420?","work":[{"type":"ask-verify","what":"open and check a source","needs":"web search, or a person with the source","units":1,"done":0}],"target":"V-LR-BOOK-2014","open":1,"note":"The only open objection on this project's corrections to the 2007 table is that nobody could read this book from a machine. It needs a person with a library or the book."}]};
